window.MTEC_NEWS = {"_info": {"beschreibung": "Freigegebene bzw. zur Freigabe vorbereitete Einträge für den M-TEC News- & Leak-Ticker. Zusammenfassungen sind KI-gestützt (Grok Bot) in eigenen Worten verfasst.", "modus": "live", "stand": "2026-11-18T20:03:09.950Z", "zeitzone": "Europe/Vienna"}, "eintraege": [{"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T20:03:09.710Z"}, "id": "2026-11-18-gta6-streaming-rekord", "datum": "2026-11-18T18:52:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Streaming", "titel": "GTA 6 bricht Streaming-Rekorde: laut Streams Charts 3,29 Mio. gleichzeitige Twitch-Zuschauer und rund 7,9 Mio. über alle Plattformen vor dem weltweiten Start", "schlagzeile": "GTA 6 bricht schon vor dem Start den Streaming-Weltrekord", "kurz": "Noch bevor GTA 6 in den meisten Ländern spielbar ist, hat es den Rekord für Livestream-Zuschauer gebrochen. Laut Streams Charts schauten zeitgleich fast 7,9 Millionen Menschen auf Twitch, YouTube, Kick und anderen Plattformen zu, davon 3,29 Millionen allein auf Twitch.", "zusammenfassung": "GTA 6 startet regional gestaffelt, in Neuseeland war es bereits am 18. November spielbar, später auch in Singapur und Hongkong. Nach vorläufigen Daten des Analysedienstes Streams Charts erreichte das Spiel laut Polygon in der Spitze 7.886.402 gleichzeitige Zuschauer über alle Plattformen. Twitch lag mit 3,29 Millionen vorne, gefolgt von YouTube mit 3,19 Millionen und Kick mit 1,48 Millionen. Damit ist GTA 6 nach diesen Daten auch die meistgesehene Spielekategorie der Twitch-Geschichte, vor League of Legends mit 3,11 Millionen und Fortnite mit 3,04 Millionen. Den bisherigen Plattform-übergreifenden Rekord für einen Spielestart hielt laut Streams Charts die geschlossene Beta von Valorant aus dem Jahr 2020 mit 1,74 Millionen Zuschauern; damals gab es allerdings Beta-Zugänge fürs Zuschauen. Eurogamer hatte am frühen Nachmittag noch 6,38 Millionen Zuschauer gemeldet, die Zahl stieg also im Tagesverlauf weiter. Weil weitere Regionen erst noch freigeschaltet werden, könnten die Werte noch steigen. Es handelt sich um vorläufige Messwerte eines Drittanbieters, nicht um offizielle Zahlen von Twitch oder Rockstar. Der offizielle Start auf PS5 und Xbox Series ist am 19. November.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/gta-6-streaming-record-twitch-viewers-reviews/"}, "weitere_links": [{"name": "Eurogamer", "url": "https://www.eurogamer.net/grand-theft-auto-6-streaming-record-broken"}], "tags": ["GTA 6", "Twitch", "Streaming", "Rekord", "Rockstar"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Cozy home streaming room at dusk behind an empty gaming chair: microphone on boom arm, controller, monitors with a blurred sunny coastal city street with palm trees, side monitor with abstract colorful chat-like blocks, warm lamp and cool window light, terracotta plant pot, no people.", "bild": {"datei": "assets/img/news/2026-11-18-gta6-streaming-rekord.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T20:03:09.427Z"}, "id": "2026-11-18-jedec-ddr6-vorschau", "datum": "2026-11-18T18:33:48+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM"], "kategorie": "Arbeitsspeicher", "titel": "JEDEC zeigt erste DDR6-Eckdaten: Start bei 12,8 GT/s, 96 Bit breiter Datenbus, 74-mm-Module, Formfaktoren RDIMM, UDIMM und CAMM möglich", "schlagzeile": "DDR6 nimmt Form an: 50 % mehr Bandbreite und viel kürzere Module", "kurz": "Das Normungsgremium JEDEC hat erstmals offiziell Eckdaten zum kommenden Arbeitsspeicher DDR6 vorgestellt. RDIMMs sollen bei 12,8 GT/s starten, der Datenbus wächst von 64 auf 96 Bit, und die Bandbreite soll zum Start um mehr als 50 % steigen. Es handelt sich ausdrücklich um Entwicklungspläne, nicht um einen fertigen Standard.", "zusammenfassung": "Die JEDEC Solid State Technology Association hat am 18. November eine Vorschau auf den DDR6-Standard veröffentlicht, der im Komitee JC-42 entwickelt wird. Laut JEDEC soll DDR6 bei RDIMMs mit 12,8 GT/s starten, nach 9,2 GT/s bei DDR5; die Roadmap reicht bis 14,4 GT/s und darüber hinaus. Der Datenbus wird von 64 auf 96 DQ verbreitert, also um 50 %. Zusammen mit den höheren Datenraten soll das zum Start mehr als 50 % zusätzliche Bandbreite bringen. JEDEC betont selbst, dass dieses Bandbreitenziel nicht gleichbedeutend mit entsprechend mehr Leistung in Anwendungen ist. Neu ist eine Pseudo-Channel-Architektur, außerdem verdoppelt sich die Zahl der Bänke. DRAM-Chips sollen bis zu 128 Gbit Dichte erreichen. Auffällig für PC-Bastler: Die Module werden mit 74 mm deutlich kürzer als DDR5-Riegel mit 133 mm. Als mögliche Formfaktoren nennt JEDEC RDIMM, UDIMM und CAMM, also nicht nur CAMM. Dazu kommen flexible ECC-Varianten und eine bessere Effizienz durch VSS-terminierte Ein- und Ausgänge sowie Stromsparmodi für Rechenzentren. Der Fokus liegt klar auf Servern und KI-Rechenzentren. Alle Angaben können sich laut JEDEC im weiteren Standardisierungsprozess noch ändern. Einen Termin für den fertigen Standard oder erste Produkte nennt die Pressemitteilung nicht.", "quelle": {"name": "JEDEC (Pressemitteilung)", "url": "https://www.jedec.org/news/pressreleases/jedec%C2%AE-previews-next-generation-ddr6-dram-higher-performance-greater-capacity"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354995/jedec-previews-next-generation-ddr6-dram"}], "tags": ["DDR6", "JEDEC", "RAM", "CAMM", "Arbeitsspeicher"], "img_prompt": "Close-up of compact unbranded engineering-sample memory modules on a warm wooden lab workbench, gold edge contacts along one long edge only, tweezers and a blurred probe, dusty teal accent; documentary hardware photo style (stil).", "bild": {"datei": "assets/img/news/2026-11-18-jedec-ddr6-vorschau.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:27.037Z"}, "id": "2026-11-18-rockstar-gewerkschaft-abstimmung", "datum": "2026-11-18T16:56:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6", "Spieleindustrie"], "kategorie": "Unternehmen", "titel": "Rund 1.600 Rockstar-Beschäftigte im Vereinigten Königreich stimmen über die Anerkennung einer Gewerkschaft ab, die Auszählung endet am 26. November", "schlagzeile": "1.600 Rockstar-Beschäftigte stimmen über eine Gewerkschaft ab", "kurz": "Während GTA 6 startet, stimmen mehr als 1.600 Rockstar-Beschäftigte im Vereinigten Königreich über die Anerkennung einer Gewerkschaft ab. Die Frist endet am 26. November. Entschieden ist damit noch nichts; bei einem Ja wäre es nach PC Gamer die größte Spiele-Gewerkschaft des Landes.", "zusammenfassung": "PC Gamer und Polygon berichten über die Abstimmung, die mit dem Test- und Starttag von GTA 6 zusammenfällt. In einem Gastbeitrag für The Guardian schreibt der Rockstar-Animationsprogrammierer und Gewerkschaftsvertreter Nestor Uriarte, hinter den Rekordzahlen stünden Tausende Menschen, die einen fairen Anteil am Erfolg sehen sollten. Mit einer anerkannten Vertretung wolle man Löhne, Arbeitsbedingungen und Boni besser absichern und auch den Einsatz von KI in der Entwicklung verhandeln. Uriarte nennt anhaltende Sorgen zu Mehrarbeit, zu einem möglichen Gender-Pay-Gap und zu unklaren Bonusregeln; zugleich betont er, die Initiative komme von Beschäftigten im Studio, nicht von außen. Ob die Mehrheit zustimmt, steht erst nach dem 26. November fest. Parallel läuft in Glasgow ein Tribunal zu Vorwürfen, Rockstar habe gewerkschaftlich aktive Mitarbeiter benachteiligt oder entlassen; über diesen Streit ist gerichtlich noch nicht abschließend entschieden. Uriarte verweist außerdem auf die Entlassungen bei Firaxis im gleichen Konzernumfeld. Eine Stellungnahme von Rockstar zur laufenden Abstimmung liegt in den vorliegenden Berichten nicht vor.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/we-need-to-come-together-on-the-eve-of-gta-6-1-600-rockstar-workers-are-voting-on-unionization/"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/gta-6-devs-union-vote-recognition/"}], "tags": ["Rockstar Games", "Gewerkschaft", "GTA 6", "Vereinigtes Königreich"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. Original adult characters only if needed, coherent anatomy and hands. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Warm late-afternoon union-hall table scene: a stack of unmarked paper ballots and a simple wooden box on a scuffed table, several empty chairs, a window with golden light, a dusty-teal enamel pitcher as accent, no readable text, no logos, no faces close enough to identify, no game characters.", "bild": {"datei": "assets/img/news/2026-11-18-rockstar-gewerkschaft-abstimmung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.821Z"}, "id": "2026-11-18-gta6-technik-fsr4-series-s", "datum": "2026-11-18T15:43:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6", "Grafik"], "kategorie": "Technik", "titel": "Rockstar bestätigt Technik von GTA 6: 1440p mit Upscaling auf 4K bei PS5, PS5 Pro und Series X, 720p mit FSR 4 auf 1080p bei der Series S, Ziel sind 30 Bilder pro Sekunde", "schlagzeile": "GTA 6: 1440p auf PS5 und Series X, Series S startet mit FSR 4 bei 720p", "kurz": "Rockstar hat gegenüber Wccftech die Technik von GTA 6 auf den Konsolen bestätigt. PlayStation 5, PS5 Pro und Xbox Series X rechnen intern in 1440p und skalieren auf 4K hoch, die Series S startet bei 720p und nutzt als erstes Spiel auf der Konsole AMD FSR 4 für 1080p. Ziel sind 30 Bilder pro Sekunde, konstant hält das laut Analysen nur die PS5 Pro.", "zusammenfassung": "Die Angaben stammen von Rockstar und wurden von ComputerBase und Tom's Hardware aufgegriffen. Auf PS5 und Series X kommt demnach eine hauseigene TAA-Lösung zum Zuge, auf der PS5 Pro Sonys PSSR, auf der Series S FSR 4. Anschließend wird auf allen Plattformen eine 4K-Benutzeroberfläche darübergelegt. Raytracing-gestützte globale Beleuchtung ist auch auf der Series S vorgesehen, die Umsetzung wird an die jeweilige Hardware angepasst. Raytraced-Schatten nennt ComputerBase nur für die PS5 Pro. Das Bildziel von 30 fps erreicht die günstigere Xbox und die normale PS5 laut Tabelle nicht immer konstant, die PS5 Pro soll die Marke halten. Gegenüber Kotaku sagte Technikchef Marc Chambers laut VGC, die „Basispräsentation“ auf der PS5 Pro umfasse Reflexionen und globale Beleuchtung per Raytracing sowie die höhere Schärfe durch PSSR. Der Prozessor der PS5 Pro sei etwas besser als in der normalen PS5, aber nicht stark genug, um die komplexe Simulation mit höherer Bildrate laufen zu lassen. Eine Absenkung der Grafik zugunsten von 60 fps klingt in dieser Aussage nicht nach einem geplanten Weg. Die oft dunkleren Bildränder bezeichnet Rockstar als künstlerische Entscheidung, abschalten lässt sich die Vignettierung derzeit nicht; einen Fehler, der sie zeitweise zu stark machte, hat das Studio nach eigenen Angaben behoben. Eine PC-Version mit eigenen Grafikstufen bleibt ohne Termin. Die Aussagen bestätigen frühere Berichte, wonach GTA 6 auch auf der PS5 Pro bei 30 fps bleibt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/gaming/gta-6-erstes-spiel-mit-amd-fsr-4-auf-der-xbox-series-s.100389/"}, "weitere_links": [{"name": "Tom's Hardware", "url": "https://www.tomshardware.com/video-games/console-gaming/gta-vi-runs-at-1440p-on-ps5-and-xbox-series-x-but-just-720p-with-upscaling-on-series-s-rockstar-details-upscaling-technologies-for-launch"}, {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/rockstar-says-ps5-pro-cant-handle-gta-6-at-60-fps/"}], "tags": ["GTA 6", "FSR 4", "Xbox Series S", "PS5 Pro", "PSSR"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. Original adult characters only if needed, coherent anatomy and hands. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Warm late-afternoon living-room scene: a large unmarked television seen from behind a couch, the screen showing an original out-of-focus sunlit coastal city street (not a known game view), two plain unbranded game controllers on a wooden table, a terracotta mug as accent, natural window light, no logos, no text, no UI, not a real screenshot.", "bild": {"datei": "assets/img/news/2026-11-18-gta6-technik-fsr4-series-s.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.602Z"}, "id": "2026-11-18-am5-agesa-vcore-14-ryzen-8000", "datum": "2026-11-18T14:15:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "CPU"], "kategorie": "Mainboards", "titel": "AGESA 1.3.0.1f Patch A begrenzt bei ausgewählten Ryzen-8000-Prozessoren die Kernspannung auf 1,4 Volt; MSI und Asus verteilen bereits passende BIOS-Versionen", "schlagzeile": "Neues AM5-BIOS: Vcore bei manchen Ryzen-8000-CPUs auf 1,4 Volt begrenzt", "kurz": "Ein neues AGESA-Update begrenzt bei ausgewählten Ryzen-8000-Prozessoren die Kernspannung auf höchstens 1,4 Volt. MSI nennt die Änderung in den Release Notes, sagt aber nicht, welche Modelle betroffen sind. Asus verteilt bereits Beta-BIOS-Versionen und warnt davor, alte Profile zu übernehmen.", "zusammenfassung": "Die Firmware trägt die Bezeichnung AGESA 1.3.0.1f Patch A, berichtet PCGH. In den MSI-Release-Notes steht wörtlich, die maximale Vcore werde für ausgewählte CPUs der Ryzen-8000-Serie auf 1,4 Volt begrenzt. Welche Modelle das sind und ob die Vorgabe von AMD stammt, ist offen. Die Regelung betrifft die Versorgung der Rechenkerne und ist von der bereits bekannten SoC-Spannungsgrenze von 1,3 Volt zu unterscheiden. Unklar bleibt auch, ob nur manuell gesetzte Werte oder zusätzlich die automatische Regelung und Precision Boost Overdrive eingeschränkt werden. Auswirkungen auf die Alltagsleistung sind nicht belegt, fürs manuelle Übertakten kann die Grenze spürbar werden. Zusätzlich führt das Update eine neue POST-Anzeige für das DDR5-Speichertraining ein: Auf dem zweistelligen Display läuft während der Initialisierung eine Zahlenfolge von 00 bis 09 im Sekundentakt, danach beginnt sie von vorn. Das ist keine Prozentanzeige, soll aber helfen zu erkennen, ob das Board noch trainiert oder hängt. Asus bietet die Firmware bereits als Beta für ausgewählte Boards der Serien X870, X870E und X670E an und warnt ausdrücklich davor, gespeicherte UEFI-Profile älterer AGESA-Versionen zu importieren. Wer ein stabil laufendes System hat, muss wegen der POST-Anzeige nicht auf eine Beta wechseln.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Ryzen-7-8700G-CPU-280151/News/BIOS-Update-Spannung-Reduktion-1560422/"}, "weitere_links": [], "tags": ["AMD", "AM5", "AGESA", "Ryzen 8000", "BIOS"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. An open unbranded AM5-style motherboard on a wooden workbench, a bare unmarked CPU in a small plastic tray beside it, a simple screwdriver and a terracotta cable comb as muted accent, warm late-morning window light, shallow depth of field, no readable text, no logos, no brand markings, no faces.", "bild": {"datei": "assets/img/news/2026-11-18-am5-agesa-vcore-14-ryzen-8000.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.713Z"}, "id": "2026-11-18-gta6-tests-metacritic-99", "datum": "2026-11-18T13:17:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA-6-Tests sind erschienen: Metacritic liegt derzeit bei 99 Punkten, der Verkaufsstart für PlayStation 5 und Xbox Series X|S ist der 19. November 2026, ein PC-Termin fehlt weiter", "schlagzeile": "GTA 6 startet: Tests feiern das Spiel, Metacritic liegt derzeit bei 99", "kurz": "Die Tests zu Grand Theft Auto 6 sind da, bei Metacritic steht das Spiel derzeit bei 99 Punkten und damit gleichauf mit Zelda: Ocarina of Time. Offizieller Start auf PlayStation 5 und Xbox Series X|S ist der 19. November 2026, in Neuseeland ist es bereits spielbar. Ein Termin für die PC-Version hat Rockstar weiter nicht genannt.", "zusammenfassung": "Viele große Fachmedien vergeben Höchstwertungen, berichtet unter anderem Polygon. OpenCritic liegt derzeit bei 98 Punkten. Die Werte können sich noch ändern, je mehr Tests dazukommen. Gelobt werden vor allem die Dichte der Spielwelt Leonida, die Beziehung zwischen Jason und Lucia und der Detailgrad; vereinzelt gibt es Kritik an einem langsamen Einstieg, an umständlicher Bedienung oder an ungelenktem Kampf. Rockstar-Präsident Sam Houser hat aus Anlass des Starts eine seltene Erklärung abgegeben, die IGN vorliegt: Das Studio wolle die Erwartungen übertreffen und zeigen, wozu Spiele fähig seien, und blicke auf „viele weitere Jahre“ gemeinsamer Erlebnisse. Was genau damit gemeint ist, etwa ein Online-Modus, sagt Rockstar nicht. In manchen Zeitzonen, etwa in Neuseeland, können Spieler das Spiel bereits starten, in Europa typischerweise in der Nacht zum 19. November. Berichte über Vorverkaufserlöse von mehr als 1,5 Milliarden US-Dollar stammen von Marktbeobachtern, nicht von einer offiziellen Rockstar-Mitteilung. Die PC-Fassung bleibt ohne Termin, ein Cloud-Streaming über Xbox wird als Zwischenlösung genannt. Wer Wertungen und Verkaufszahlen zitiert, sollte den Stand vom 18. November 2026 im Blick behalten, beides kann sich schnell ändern. PlayStation hat den Start offiziell auf Donnerstag, den 19. November, datiert. Der Support weist darauf hin, dass vor dem Spielen ein PS5-Systemupdate nötig ist.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/gta-6-review-roundup/"}, "weitere_links": [{"name": "IGN (Sam Houser)", "url": "https://www.ign.com/articles/rockstar-president-sam-houser-issues-rare-statement-to-celebrate-gta-6-launch"}, {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/GTA-6-Spiel-55239/News/Test-Review-Metascore-Bewertungen-1560408/"}, {"name": "PC Games (Test)", "url": "https://www.pcgames.de/GTA-6-Spiel-55239/Tests/Review-Rockstar-Wertung-Lucia-Jason-1560203/"}, {"name": "PlayStation", "url": "https://x.com/PlayStation/status/2123084055071908103"}, {"name": "PlayStation Support", "url": "https://x.com/PS_Support_US/status/2122863683881619685"}], "tags": ["GTA 6", "Rockstar Games", "Metacritic", "PlayStation 5", "Xbox"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. Original adult characters only if needed, coherent anatomy and hands. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Cinematic late-afternoon scene on a sun-bleached coastal city boulevard: an original generic sports car parked at a cracked curb, palm shadows on warm asphalt, pastel motel facades without signs, a distant unbranded television store window softly reflecting the street, golden natural light, rich colors, no recognizable game characters, no logos, no text, no copied map or UI, not a screenshot.", "bild": {"datei": "assets/img/news/2026-11-18-gta6-tests-metacritic-99.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:27.443Z"}, "id": "2026-11-18-windows-server-2028-vorschau", "datum": "2026-11-18T11:01:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Microsoft veröffentlicht eine öffentliche Vorschau von Windows Server 2028 mit härterer Standardabsicherung, lokalem KI-Betrieb und neuer Speichertechnik, nennt aber noch keinen Termin für die fertige Version", "schlagzeile": "Windows Server 2028 ist als öffentliche Vorschau da – ohne Fertigtermin", "kurz": "Microsoft hat eine öffentliche Vorschau von Windows Server 2028 freigegeben. Sie zielt auf eine härtere Standardabsicherung, lokalen KI-Betrieb und schnelleren Speicher, etwa mit nativem NVMe. Einen Termin für die fertige Version nennt der Konzern nicht.", "zusammenfassung": "Das schreibt Microsoft im Blog der Windows-Server-Techcommunity, berichtet heise. Interessierte können sich außerdem für das Technology Adoption Program bewerben. Damit ist zugleich klar, dass Microsoft weiter ein Serverbetriebssystem für den Einsatz im eigenen Rechenzentrum anbietet und nicht nur Cloud-Dienste. Zur Sicherheit soll eine standardmäßig gehärtete Server-Core-Konfiguration gehören, dazu eine neue Security-Baseline, Trusted Launch für Generation-2-VMs und der Beginn der Unterstützung für vertrauliche virtuelle Maschinen auf passender Hardware vor Ort. Geplant sind außerdem automatische Zertifikate und Vorbereitungen für Post-Quanten-Kryptografie. Mehr Tempo versprechen ein standardmäßig aktiver nativer NVMe-Stapel, NVMe über TCP und RDMA sowie die Möglichkeit, von ReFS-Laufwerken zu starten. Die Serververwaltung soll als Vorschau in Microsoft Intune einziehen, der Virtualisierungsmodus des Windows Admin Center ist allgemein verfügbar. Im Bereich KI spricht Microsoft von „hybrider Intelligenz“: Inferenz soll näher an den Daten oder unter eigener Kontrolle laufen können, unter anderem mit Foundry Local, Windows ML, vLLM und llama.cpp. Als Hardware-Vorschau nennt Microsoft AMDs Instinct-Karte MI350P für das erste Halbjahr 2027. Microsoft eXecution Containers sollen lokale Inferenz zusätzlich isolieren. Bleibt es beim üblichen Rhythmus, könnte die fertige Version in etwa einem Jahr erscheinen; verbindlich ist das nicht. Die Vorschau läuft über das Windows-Insider-Programm für Server.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Windows-Server-2028-Oeffentliche-Vorschau-verfuegbar-11528845.html"}, "weitere_links": [], "tags": ["Windows Server 2028", "Microsoft", "NVMe", "Intune", "KI"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. A clean on-premises server rack in a small business closet, warm daylight from a high window, unbranded servers with soft status lights, a blank-screen KVM monitor on a folding tray, an olive cloth on the tray as accent, no readable text, no logos, no brand markings, no people.", "bild": {"datei": "assets/img/news/2026-11-18-windows-server-2028-vorschau.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.478Z"}, "id": "2026-11-18-amd-ces-2027-zen6-teaser", "datum": "2026-11-18T11:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["AMD", "CPU"], "kategorie": "Prozessoren", "titel": "AMD kündigt einen Auftritt zur CES 2027 am 5. Januar in Las Vegas an; ein Teaser zeigt ein sehr dünnes Notebook, offizielle Chipdetails fehlen noch", "schlagzeile": "AMD macht CES-2027-Auftritt fest – Zen 6 für Notebooks wird erwartet", "kurz": "AMD hat einen Auftritt zur CES 2027 in Las Vegas fest zugesagt. Der Termin ist der 5. Januar 2027 um 10 Uhr Ortszeit, 19 Uhr mitteleuropäischer Zeit. Ein Teaser zeigt ein sehr dünnes, leicht aufgeklapptes Notebook; welche Chips AMD genau vorstellt, ist noch nicht bestätigt.", "zusammenfassung": "Den Termin nannte AMD-Manager Jack Huynh am 17. November auf X, berichtet ComputerBase; auch PCGH greift die Ankündigung auf. Huynh schreibt von einer „nächsten Ära des Rechnens“ und will auf der CES in der Mandalay Bay einen Ausblick zeigen. Das beigefügte Bild deutet auf besonders flache Notebooks hin. In den vergangenen Jahren hat AMD zur CES typischerweise neue Mobilprozessoren vorgestellt, ein Verkaufsstart folgt oft erst Monate später. ComputerBase verknüpft den Teaser mit den bereits bekannten Codenamen Medusa Point für kommende Notebook-Chips und mit inoffiziellen Sample-Listungen der vergangenen Wochen, etwa zu 10-, 8- und 6-Kern-Varianten. Diese Konfigurationen und Takte sind nicht von AMD bestätigt. Ebenso unbestätigt ist, ob zur CES auch Desktop-Ableger mit Zen 6 gezeigt werden; PCGH wirft diese Frage auf, eine offizielle Antwort gibt es nicht. Auch Berichte über zusätzliche sehr sparsame Kerne unterhalb von Zen 6 und Zen 6c bleiben vorerst Spekulation. Bis zum 5. Januar sind also vor allem der Termin und der Notebook-Teaser belastbar, technische Daten erst, wenn AMD sie selbst nennt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/prozessoren/medusa-point-und-co-amd-teasert-neue-notebook-chips-fuer-ces-2027-an.100382/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/AMD-Zen-Architektur-261795/News/Zen-6-Desktop-Prozessoren-CES-2027-1560410/"}], "tags": ["AMD", "CES 2027", "Zen 6", "Medusa Point", "Notebook"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. An ultra-thin unbranded silver laptop standing slightly open on a light oak desk beside a window, blank dark screen with no logos, a closed notebook and a terracotta ceramic cup as muted accent, warm late-morning daylight, shallow depth of field, no people, no readable text, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-18-amd-ces-2027-zen6-teaser.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.348Z"}, "id": "2026-11-18-nvidia-q3-huang-bleibt-draussen", "datum": "2026-11-18T00:26:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia"], "kategorie": "Unternehmen", "titel": "Nvidia legt im ersten Quartalsbericht nach Jensens Huangs Rücktritt 115,8 Milliarden US-Dollar Umsatz vor; der Verwaltungsrat beabsichtigt nicht, Huang wieder als CEO einzusetzen", "schlagzeile": "Rekordquartal bei Nvidia: Verwaltungsrat schließt Huangs Rückkehr als CEO aus", "kurz": "Nvidia hat im dritten Geschäftsquartal 115,8 Milliarden US-Dollar Umsatz und 65,3 Milliarden Dollar Gewinn erzielt und damit die Erwartungen übertroffen. Verwaltungsratschef Harvey Jones erklärte, das Gremium beabsichtige nicht, den zurückgetretenen Jensen Huang wieder als CEO einzusetzen. Huang hatte sich zuvor bereiterklärt, zurückzukehren, falls der Rat das für richtig hält.", "zusammenfassung": "Es ist der erste Quartalsbericht seit Huangs Rücktritt in der Vorwoche. Den Umsatz beziffert Nvidia offiziell auf 115,8 Milliarden US-Dollar, 103 Prozent mehr als ein Jahr zuvor und 20 Prozent mehr als im Vorquartal; der Gewinn stieg auf 65,3 Milliarden Dollar. Allein die Rechenzentren-Sparte kam auf 107,6 Milliarden Dollar (plus 110 Prozent). Die früher eigenständige Gaming-Sparte ist in Edge Computing aufgegangen und erzielte dort zusammen 8,2 Milliarden Dollar, ein Plus von 42 Prozent. Interimschefin und Finanzchefin Colette Kress sprach von einem starken Start der Serverplattform Vera Rubin und einem unverändert gültigen Produktplan. Für das vierte Quartal, das eine Woche länger dauert, erwartet Nvidia 130 Milliarden Dollar Umsatz plus/minus 3 Prozent, ohne Rechenzentrums-Chips für China. Die Bruttomarge soll auf 71 bis 72 Prozent sinken. Die Verpflichtungen für kommende Komponenten stiegen auf 390 Milliarden Dollar nach 279 Milliarden im Vorquartal, laut ComputerBase vor allem wegen teurer Speicherverträge. Zu Beginn der Analystenkonferenz stellte Verwaltungsratschef Harvey Jones klar, der Rat habe Huangs Rücktritt einstimmig angenommen und beabsichtige nicht, ihn wieder als CEO einzusetzen; Fragen zur laufenden internen Untersuchung wolle er nicht beantworten. Wenige Stunden zuvor hatte Huang geschrieben, er wäre geehrt, zurückzukehren, wenn der Rat das im Interesse von Aktionären, Beschäftigten, Unternehmen und den USA für richtig hält. Die Suche nach einer dauerhaften Führung läuft intern und extern weiter, Kress bleibt interimsweise im Amt. Umgerechnet entsprechen die Quartalszahlen laut ComputerBase rund 105,3 Milliarden Euro Umsatz und 59,4 Milliarden Euro Gewinn.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/nach-skandal-nvidia-uebertrifft-erwartungen-und-schliesst-huang-rueckkehr-aus.100376/"}, "weitere_links": [{"name": "Nvidia IR (Quartalsbericht)", "url": "https://investor.nvidia.com/news/press-release-details/2026/NVIDIA-Announces-Financial-Results-for-Third-Quarter-Fiscal-2027/"}, {"name": "heise online", "url": "https://www.heise.de/news/Nvidia-Fast-116-Milliarden-US-Dollar-Umsatz-Jensen-Huang-will-zurueckkommen-11528649.html"}, {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354967/jensen-huang-will-not-be-reinstated-as-ceo-says-nvidia-board-chief"}], "tags": ["Nvidia", "Jensen Huang", "Colette Kress", "Quartalszahlen", "Vera Rubin"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. A long empty glass-walled boardroom in a modern office, an unoccupied leather chair at the head of a walnut table, a closed unmarked laptop and a short stack of blank papers, warm late-morning sunlight, muted dusty-teal accent from a glass water carafe, city skyline softly blurred. No people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-18-nvidia-q3-huang-bleibt-draussen.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:27.343Z"}, "id": "2026-11-18-windows11-baseline-protection", "datum": "2026-11-18T00:17:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11 testet Baseline Protection: Apps erhalten eine Ja-nein-Auskunft über acht Sicherheitsfunktionen und dürfen warnen, Funktionen beschränken oder den Start verweigern; die allgemeine Freigabe ist für 2027 geplant", "schlagzeile": "Windows 11 testet Schutzprüfung, an der Apps den Start verweigern dürfen", "kurz": "Microsoft testet in einer Insider-Vorschau die Funktion Windows Baseline Protection. Sie fasst acht vorhandene Schutzmaßnahmen zu einer Auskunft zusammen, die Programme abfragen können. Entwickler dürfen dann warnen, Funktionen einschränken oder den Start verhindern; eine allgemeine Freigabe ist für 2027 vorgesehen.", "zusammenfassung": "Windows Latest beschreibt die Vorschau ausführlich. Zu den acht geprüften Punkten gehören unter anderem Secure Boot und die Speicherintegrität. Wer diese Funktionen abgeschaltet hat, etwa für einen parallelen Linux-Start, besteht die Prüfung nicht. Apps bekommen eine klare Ja-nein-Antwort, eine Liste fehlender Punkte oder ein schwerer zu fälschendes, hardwaregestütztes Attest, das ein Anbieter auf seinen Servern prüfen kann. Microsoft betont, das System melde nur den Zustand, die Richtlinie bleibe beim jeweiligen Entwickler. Adobe, Battle.net, 1Password und Schoolyear testen die Schnittstelle bereits. Keines dieser Unternehmen hat angekündigt, Rechner mit negativer Prüfung pauschal auszusperren; Battle.net spricht laut Bericht davon, die Sicherheit zu erhöhen und die Reibung für Spieler gering zu halten. In den Einstellungen soll eine neue Seite „Sicherheit > Baseline protection“ den Status zeigen und viele der fehlenden Funktionen mit einem Schalter samt Neustart einschalten können. Die allgemeine Bereitstellung plant Microsoft für 2027, bis dahin bleibt es ein Insider-Test, der sich noch ändern kann. Für Spieler und Schrauber ist vor allem wichtig, dass eine abschaltbare Schutzfunktion künftig nicht mehr nur eine lokale Warnung auslösen, sondern den Start einzelner Programme verhindern kann, wenn der Anbieter das so festlegt.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/18/apps-could-soon-refuse-to-run-on-your-windows-11-pc-if-it-fails-microsofts-new-security-check-and-adobe-and-battle-net-are-already-on-board/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Windows-Software-277633/News/Windows-11-Neue-Sicherheitsfunktion-App-Nutzung-einschraenken-sperren-1560427/"}], "tags": ["Windows 11", "Baseline Protection", "Insider", "Secure Boot", "Sicherheit"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. An unbranded silver Windows-style laptop on a kitchen table in warm late-morning light, the screen showing only a simple abstract green shield shape with no text, a closed notebook and an olive ceramic cup nearby, shallow depth of field, no people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-18-windows11-baseline-protection.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:27.242Z"}, "id": "2026-11-17-java4shell-rce", "datum": "2026-11-17T21:13:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit"], "kategorie": "Sicherheit", "titel": "Kritische Lücke Java4Shell in OpenJDK erlaubt über fehlerhafte Base64-Dekodierung auf manchen x86-64-Systemen mit AVX-512 das Ausführen von fremdem Code; Oracle hat Patches veröffentlicht", "schlagzeile": "Java4Shell: Gefährliche Lücke in Java, Patches von Oracle sind da", "kurz": "In OpenJDK gibt es eine als Java4Shell bezeichnete Sicherheitslücke, über die Angreifer auf verwundbaren Systemen aus der Ferne Code ausführen können. Betroffen ist eine hardwarebeschleunigte Base64-Funktion auf bestimmten x86-64-Prozessoren mit AVX-512. Oracle hat am 17. November Patches veröffentlicht, als Zwischenlösung lässt sich die Beschleunigung abschalten.", "zusammenfassung": "Die Lücke trägt die Nummer CVE-2026-114938. Das Forschungsunternehmen Calif stuft sie mit einem CVSS-4.0-Wert von 9,2 als kritisch ein, Oracle vergibt nach CVSS 3.1 die Stufe 8,1 (hoch), berichtet BleepingComputer; auch heise und PCGH greifen den Fall auf. Betroffen sind OpenJDK ab Version 17.0.6 und darauf aufbauende Pakete, darunter Oracle Java SE, Amazon Corretto, Eclipse Temurin, Microsofts OpenJDK-Build, Azul Zulu und Red Hats OpenJDK. Die fehlerhafte Stelle steckt in einer beschleunigten Base64-Dekodierung, die nur auf x86-64-Prozessoren mit bestimmten AVX-512-Befehlen greift; neuere Ryzen- und Intel-Systeme können also eher betroffen sein als ältere Rechner ohne diese Befehle. Calif konnte damit nach eigenen Angaben unter anderem bei Jenkins, Jira, Confluence, Keycloak und JFrog Artifactory eine nicht authentisierte Codeausführung zeigen, bei weiteren Diensten nur mit Anmeldung. Es gibt keinen einheitlichen Angriff für alle Programme, die präparierten Daten müssen die verwundbare Funktion jeweils erreichen. Oracle hat Korrekturen im November-Sicherheitsupdate veröffentlicht. Wer nicht sofort aktualisieren kann, kann die Beschleunigung laut Forschern vorübergehend mit den Startoptionen zur Deaktivierung der Base64-Intrinsics oder von AVX-512 abschalten. Ein allgemeiner Proof-of-Concept für die Speicherverletzung liegt vor, ausformulierte Angriffe auf die genannten Anwendungen hat Calif nicht veröffentlicht.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/critical-java4shell-flaw-allows-rce-attacks-on-major-java-applications/"}, "weitere_links": [{"name": "heise online", "url": "https://www.heise.de/news/Java4Shell-Gefaehrlicher-Bug-in-Java-11528499.html"}, {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Java-Software-256198/News/Java4Shell-Sicherheitsluecke-Darauf-muessen-Besitzer-neuerer-Ryzen-und-Intel-Systeme-achten-1560375/"}, {"name": "Phoronix", "url": "https://www.phoronix.com/news/Java4Shell-Vulnerability"}], "tags": ["Java", "Java4Shell", "OpenJDK", "CVE-2026-114938", "Sicherheit"], "img_prompt": "Documentary hardware photograph, as shot by a tech journalist for a hardware review: real camera look (full-frame mirrorless camera, 35mm or 50mm lens at f/2.8, natural shallow depth of field), warm natural daylight from a window (late-morning sun, gently golden), natural rich colors with healthy saturation, warm honey-toned wood and paper, one small muted accent color in the scene (dusty teal, terracotta or olive object), colors like a well-exposed photo straight from a good camera, not desaturated, not washed out, not grey, realistic materials with fine dust, fingerprints, small scratches and slight wear, ordinary real-world surroundings slightly out of focus, calm uncluttered composition with the subject slightly off-center, mild lens vignetting and subtle sensor noise, not retouched. No neon, no glow effects, no glossy CGI or 3D-render look, no floating objects, no impossible or nonsensical details, no visible text, letters, numbers, logos, brand names or readable labels anywhere (all stickers and screens blank or unreadably out of focus), no people's faces. 16:9 landscape. A server room aisle in warm late-morning light leaking from a side door, unbranded rack servers with small unreadable status lights, a laptop on a rolling cart showing a blurred unreadable terminal, a dusty-teal network cable coiled on the cart, no people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-17-java4shell-rce.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T20:03:09.578Z"}, "id": "2026-11-17-game-awards-2026-nominierte", "datum": "2026-11-17T19:16:01+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Events", "titel": "The Game Awards 2026: GTA 6 in acht Kategorien nominiert; GOTY-Kandidaten 007 First Light, Control Resonant, GTA 6, Phantom Blade Zero, Resident Evil Requiem und Zelda: Ocarina of Time; Show am 10. Dezember", "schlagzeile": "Game Awards 2026: GTA 6 räumt acht Nominierungen ab", "kurz": "Die Nominierten für The Game Awards 2026 stehen fest. GTA 6 ist in acht Kategorien vertreten, darunter Spiel des Jahres. Die Gewinner werden am 10. Dezember in Los Angeles verkündet.", "zusammenfassung": "Geoff Keighley hat am 17. November die Nominierten der Game Awards 2026 in allen Kategorien veröffentlicht. Grand Theft Auto 6 führt das Feld mit acht Nominierungen an, unter anderem für Spiel des Jahres, Game Direction, Erzählung, Art Direction, Musik und Audio. Um den Titel Spiel des Jahres kämpfen 007 First Light, Control Resonant, GTA 6, Phantom Blade Zero, Resident Evil Requiem und The Legend of Zelda: Ocarina of Time. Control Resonant und 007 First Light sind ebenfalls mehrfach nominiert. In der Kategorie Most Anticipated Game stehen unter anderem Fable, God of War Laufey und The Witcher 4. Bei Best Ongoing Game sind etwa Arc Raiders, Fortnite und The Witcher 3 dabei. Über die Gewinner entscheidet zu 90 % eine internationale Jury und zu 10 % das Fan-Voting, das bereits läuft. Die Kategorie Player's Voice wird komplett von Fans bestimmt. Die Show läuft am 10. Dezember aus dem Peacock Theater in Los Angeles und soll wie gewohnt auch neue Spiele-Ankündigungen bringen. Bemerkenswert: GTA 6 erscheint erst am 19. November und ist damit nur knapp für den diesjährigen Zeitraum qualifiziert. Eine vollständige Liste aller Kategorien bieten die verlinkten Quellen.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/grand-theft-auto-vi-dominates-the-game-awards-2026-with-eight-nominations/"}, "weitere_links": [{"name": "IGN Deutschland", "url": "https://de.ign.com/project-007/157337/die-nominierungen-fur-die-game-awards-2026-stehen-fest-gta-6-dominiert"}], "tags": ["The Game Awards", "GTA 6", "GOTY", "Control Resonant", "007 First Light"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Wide cinematic view of an empty grand theatre stage prepared for a video game award show: red velvet seats, warm golden spotlights with cool-blue accents, six screens with blurred colorful abstract skies, a simple original faceted golden statuette on a pedestal, no people.", "bild": {"datei": "assets/img/news/2026-11-17-game-awards-2026-nominierte.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:27.136Z"}, "id": "2026-11-17-doom-dark-ages-fsr41-vulkan", "datum": "2026-11-17T18:11:00+01:00", "label": "News", "bereich": "games", "themen": ["FSR", "Grafik"], "kategorie": "Technik", "titel": "Update 5 von Doom: The Dark Ages bringt als erstes Vulkan-Spiel offiziell AMD FSR 4.1 und Frame Generation 4; AMD aktualisiert zugleich das Unreal-Engine-Plugin", "schlagzeile": "Doom: The Dark Ages bringt als erstes Vulkan-Spiel FSR 4.1 nativ", "kurz": "Mit Update 5 unterstützt Doom: The Dark Ages als erstes Vulkan-Spiel offiziell AMDs FSR 4.1 und Frame Generation 4. Damit entfällt der bisher oft nötige Umweg über Drittanbieter-Werkzeuge. Parallel hat AMD das Unreal-Engine-Plugin auf Version 4.1.2 aktualisiert, dort bleibt es allerdings bei DirectX 12.", "zusammenfassung": "Bestätigt hat das AMD-Manager Jack Huynh auf X, berichtet ComputerBase. Ende Oktober hatte AMD im FSR SDK 2.4.0 bereits eine Vulkan-Schnittstelle bereitgestellt, Spiele mussten sie aber erst einbauen. Das maschinelle Hochskalieren von FSR 4.1 läuft auf Radeon-Karten der Serien RX 9000, RX 7000 und RX 6000 sowie auf ausgewählten Ryzen-APUs. Für die KI-gestützte Frame Generation 4 sind mindestens Radeon-Karten der RX-9000-Serie nötig. id Software gibt außerdem an, Frame Generation lasse sich auf Intel-Grafik aktivieren, wenn Hardware und Treiber mitspielen; konkrete Modelle nennt das Studio nicht. Das Unreal-Plugin 4.1.2 überträgt die SDK-Neuerungen auf die Unreal Engine 5.3 bis 5.8, erweitert das Hochskalieren auf RX 6000 und bestimmte Ryzen-Prozessoren mit integrierter Grafik und bringt Verbesserungen beim Frame Pacing auf RX 9000. Die Vulkan-Funktion aus dem SDK steckt in diesem Plugin noch nicht. Update 5 ergänzt außerdem den Slaughter-Modus für die im Juli 2026 erschienene Story-Erweiterung Revelations, mit endlos steigenden Gegnerwellen. Für den Ticker ist vor allem der erste native FSR-4.1-Einsatz unter Vulkan relevant, nicht nur ein weiteres Spiele-Update.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/gaming/doom-the-dark-ages-update-5-bringt-amd-fsr-4-1-nativ-in-ein-vulkan-spiel.100371/"}, "weitere_links": [], "tags": ["Doom", "FSR 4.1", "Vulkan", "AMD", "Unreal Engine"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. Original adult characters only if needed, coherent anatomy and hands. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Dynamic original medieval-fantasy melee in warm late-day light: an original armored warrior with a unique unbranded helmet charges through a ruined stone hall, dust and debris in the air, strong diagonal composition and low camera, rich natural colors, no recognizable game character or franchise armor, no logos, no text, no UI, not a screenshot.", "bild": {"datei": "assets/img/news/2026-11-17-doom-dark-ages-fsr41-vulkan.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T18:03:26.926Z"}, "id": "2026-11-18-firaxis-entlassungen", "datum": "2026-11-17T17:26:00+01:00", "label": "News", "bereich": "games", "themen": ["Spieleindustrie"], "kategorie": "Unternehmen", "titel": "Firaxis entlässt nach Bloomberg rund ein Drittel der Belegschaft, etwa 60 Personen; Studioleiterin Heather Hazen geht, 2K bestätigt den Umbau", "schlagzeile": "Civilization-Studio Firaxis entlässt rund ein Drittel der Belegschaft", "kurz": "Das Civilization- und XCOM-Studio Firaxis hat nach Angaben von Bloomberg rund 60 Menschen entlassen, etwa ein Drittel der Belegschaft. Studioleiterin Heather Hazen verlässt das Unternehmen, das bestätigt ein Sprecher von 2K. Über ein neues XCOM-Spiel mit Entwicklungsproblemen berichtet Bloomberg unter Berufung auf informierte Personen.", "zusammenfassung": "Die Streichungen erfolgten am 17. November, also kurz vor dem Start von GTA 6 beim gemeinsamen Mutterkonzern Take-Two. 2K bestätigt den Umbau, nicht aber die Zahl der Betroffenen. In einer Stellungnahme heißt es, Firaxis konzentriere sich wieder auf seine Stärke, erstklassige Strategiespiele zu entwickeln, verkleinere das Studio und müsse sich von talentierten Kollegen verabschieden. Diese Entscheidungen fielen nie leicht, seien aber nötig. Zu Hazens Wechsel sagt 2K, sie übergebe die Leitung bewusst jetzt, damit eine neue Führung den nächsten Abschnitt von Beginn an verantworten könne. Bloomberg berichtet unter Berufung auf mit den Vorgängen vertraute Personen zudem, ein neues XCOM-Spiel habe unter Entwicklungsproblemen gelitten und im Sommer einen wichtigen Meilenstein verfehlt; die Arbeit gehe weiter, das Projekt könne sich durch die Kürzungen aber noch einmal ändern. Diese Punkte sind nicht offiziell bestätigt. Das zuletzt erschienene Spiel des Studios, Civilization VII, war im Februar 2025 gestartet und in der Spielerschaft umstritten. Firaxis hatte in den Vorjahren bereits Personal abgebaut. Die genaue künftige Studioleitung ist noch nicht benannt.", "quelle": {"name": "IGN Deutschland", "url": "https://de.ign.com/sid-meiers-civilization-vii/157335/diese-entscheidungen-fallen-nie-leicht-civilization-entwickler-firaxis-entlasst-ein-drittel-seiner-b"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/civilization-dev-firaxis-reportedly-lays-off-a-third-of-its-staff-studio-head-departs/"}, {"name": "Eurogamer", "url": "https://www.eurogamer.net/firaxis-layoffs-civilization-xcom-heather-hazen"}], "tags": ["Firaxis", "2K", "Civilization", "XCOM", "Entlassungen"], "img_prompt": "Original thematic AI editorial gaming illustration, never a copy of a known character, costume silhouette, game map or UI. Warm natural light, natural rich colors, readable warm/cool contrast, no garish neon, no drab or washed-out palette. Strong focal subject and news-card readability. Original adult characters only if needed, coherent anatomy and hands. No recognizable protected characters, logos, text, watermarks, copied maps, trademarks or game UI. 16:9 landscape. Quiet empty strategy-game studio office in warm late-afternoon light: unoccupied desks with unmarked monitors showing only a softly blurred abstract map of generic terrain (no real game UI), packed cardboard boxes, a half-cleared corkboard with blank papers, an olive plant as muted accent, no logos, no text, no recognizable characters.", "bild": {"datei": "assets/img/news/2026-11-18-firaxis-entlassungen.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-18T20:03:09.830Z"}, "id": "2026-11-16-gta6-hacker-schuldig", "datum": "2026-11-16T19:51:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Sicherheit", "titel": "Hacker hinter dem GTA-6-Leak von 2022 bekennt sich vor britischem Gericht schuldig; Angriffe auf Rockstar, Uber und EE/BT mit geschätzt 10 Mio. Pfund Schaden", "schlagzeile": "GTA-6-Leak von 2022: Hacker bekennt sich schuldig", "kurz": "Der heute 21-Jährige, der 2022 Rockstar Games gehackt und frühe GTA-6-Videos veröffentlicht hatte, hat sich vor einem Londoner Gericht schuldig bekannt. Ein Strafmaß steht noch aus.", "zusammenfassung": "Am 16. November bekannte sich der Mann am Woolwich Crown Court im Südosten Londons schuldig, Rockstar Games und weitere Firmen gehackt zu haben, darunter Uber und EE/BT. Der geschätzte Schaden der Cyberangriffe liegt laut Bericht bei rund 10 Millionen Pfund. Zur Zeit des Rockstar-Hacks war er 16 bis 17 Jahre alt. Laut Eurogamer, das sich auf die BBC beruft, war er damals in einem Hotel unter Polizeischutz untergebracht und nutzte für den Angriff nur einen Amazon Fire Stick, den Hotelfernseher sowie Bluetooth-Tastatur und -Maus. Er drang demnach auch in Rockstars Slack-Kanäle ein und drohte, den Quellcode von GTA 6 zu veröffentlichen. Die Leaks von 2022 zeigten rund eine Stunde unfertiges Gameplay und machten Protagonistin Lucia erstmals öffentlich. Zuvor war er wegen einer schweren Autismus-Diagnose zunächst in eine Klinik eingewiesen worden, wurde inzwischen aber für verhandlungsfähig erklärt und kam Anfang des Jahres in ein reguläres Gefängnis. Das Strafmaß steht noch aus. Nicht zu verwechseln ist der Fall mit den Leaks von 2026, die einem anderen Akteur zugeschrieben werden. Rockstar hatte den Einbruch 2022 bestätigt und erklärt, die Entwicklung sei langfristig nicht beeinträchtigt.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/gta-6-leaker-pleads-guilty"}, "weitere_links": [], "tags": ["GTA 6", "Rockstar", "Hack", "Leak", "Gericht"], "img_prompt": "Documentary-style editorial photograph of an anonymous budget hotel room at night: wall-mounted TV with blurred dark screen, small generic streaming stick, wireless keyboard and mouse on a bedspread, paper coffee cup, warm lamp and cool window light, olive cushion accent, no people, no text, no logos.", "bild": {"datei": "assets/img/news/2026-11-16-gta6-hacker-schuldig.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:19.585Z"}, "id": "2026-11-16-speicherpreise-ssd-dreifach", "datum": "2026-11-16T08:30:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM", "SSD"], "kategorie": "Speicher", "titel": "ComputerBase-Preischeck November: RAM im Schnitt 446 Prozent, SSDs 162 Prozent und Festplatten 151 Prozent teurer als Mitte September 2025", "schlagzeile": "Speicherkrise: RAM kostet 446 Prozent mehr, manche SSD das Dreifache", "kurz": "ComputerBase hat die Preise für RAM, SSDs und Festplatten erneut geprüft. Arbeitsspeicher liegt im Schnitt 446 Prozent über dem Stand von Mitte September 2025, SSDs 162 Prozent. Einzelne Speicherkits kosten mehr als das Sechsfache, einzelne SSDs das Dreifache.", "zusammenfassung": "ComputerBase beobachtet seit Mitte September 2025 die Preise von jeweils zwölf damals besonders gefragten RAM-Kits, SSDs und Festplatten im Online-Handel. Im November erreichen die Preise laut der neuen Auswertung neue Höchstwerte. RAM kostet im Schnitt 446 Prozent mehr als zu Beginn der Messung, manche Kits liegen über 500 Prozent und kosten damit mehr als das Sechsfache. SSDs haben sich von plus 146 Prozent Mitte Oktober auf plus 162 Prozent verteuert, einzelne Modelle kosten das Dreifache. Festplatten liegen im Schnitt 151 Prozent über dem Ausgangswert und sind zuletzt nur leicht teurer geworden. Einige Speicherkits wurden zwar etwas günstiger, andere zogen dafür umso stärker an. Angebote kleiner eBay-Händler und von Amazon-Marketplace-Händlern fließen nicht ein, weil sie den Trend verfälschen könnten und für Käufer riskant sind. Hinter vielen dieser Angebote vermutet die Redaktion Händler, die sich in der Krise eingedeckt haben. Ein Ende ist nicht in Sicht: Laut ComputerBase soll AMD im November auch die Preise für Radeon-Grafikkarten erneut anheben.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/storage/speicherpreise-im-check-bei-ssds-muss-schon-fast-das-dreifache-bezahlt-werden.100345/"}, "weitere_links": [], "tags": ["RAM", "SSD", "HDD", "Speicherkrise", "Preise"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. Several unbranded M.2 NVMe SSD sticks and two plain desktop RAM modules with blank heat spreaders laid out on a wooden shop counter next to a small stack of coins and a crumpled blank paper receipt, a hand-held price tag gun lying beside them, muted terracotta accent from a cardboard box edge. No readable text or numbers, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-speicherpreise-ssd-dreifach.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:19.718Z"}, "id": "2026-11-16-subnautica-2-ea2-gruselbiome", "datum": "2026-11-16T08:15:00+01:00", "label": "News", "bereich": "games", "themen": ["PC-Spiele"], "kategorie": "Spiele", "titel": "Subnautica 2: Entwicklervideo zeigt die neuen, besonders unheimlichen Unterwassergebiete von Early Access 2.0, das Update soll im Dezember 2026 erscheinen", "schlagzeile": "Subnautica 2: Größtes Update bringt die bisher gruseligsten Tiefseegebiete", "kurz": "Unknown Worlds zeigt in einem neuen Entwicklervideo die Gebiete von Early Access 2.0 für Subnautica 2. Nebel, Sichtlinien und Licht sollen sie besonders bedrohlich machen. Das Update soll im Dezember 2026 erscheinen, einen genauen Termin gibt es noch nicht.", "zusammenfassung": "Early Access 2.0 ist das bisher größte Update für das Unterwasser-Survivalspiel, berichtet PC Games. Im neuen Video erklären die Entwickler, wie die Biome entstehen: Zuerst wird in einer Greybox festgelegt, wo Tiere leben und welche Bereiche geschützt sind. Danach sorgen Unterwassernebel, gezielte Sichtlinien und Lichteffekte für eine beklemmende Stimmung. Die Farben verraten, wo es sicher ist: Warme Töne stehen für sichere, kühle für gefährliche Bereiche. In versteckten Höhlen und Nischen warten Belohnungen wie neue Ressourcen, auffällige Felsen, Lichtquellen und Pflanzen weisen den Weg. Dazu kommt eine rätselhafte Seuche, die befallenen Teilen der Welt fast alle Farbe nimmt, bis sie geheilt sind. So soll die Welt ihre Geschichte selbst erzählen, ohne Tagebücher oder Zwischensequenzen. Außerdem zeigt das Video das neue FROG-Chassis für das Fahrzeug Tadpole. Early Access 2.0 ist für Dezember 2026 geplant.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/Subnautica-2-Spiel-75276/News/Early-Access-20-Video-1560042/"}, "weitere_links": [], "tags": ["Subnautica 2", "Unknown Worlds", "Early Access", "Survival", "Update"], "img_prompt": "Dynamic original underwater survival-action illustration: an original-design diver in a sleek sci-fi diving suit with a small handheld scanner kicking hard away from a vast shadowy leviathan-like sea creature emerging from a dark trench, low close camera from below, strong diagonal motion, swirling silt and bubbles, warm golden light from glowing coral and the diver's lamp against deep cool blue darkness, a patch of drained grey coral at one side, rich natural colors, muted amber accent. Original creature and character designs only, no copies of known game creatures, no gore, no text, no logos, no UI.", "bild": {"datei": "assets/img/news/2026-11-16-subnautica-2-ea2-gruselbiome.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:19.821Z"}, "id": "2026-11-16-huang-comeback-ft", "datum": "2026-11-16T08:10:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia"], "kategorie": "Unternehmen", "titel": "Bericht der Financial Times: Jensen Huang erwägt wenige Tage nach seinem Rücktritt eine Rückkehr als Nvidia-CEO, Investoren machen Druck, Washington ist dagegen", "schlagzeile": "Comeback nach dem Rücktritt? Jensen Huang soll Rückkehr zu Nvidia erwägen", "kurz": "Wenige Tage nach seinem Rücktritt soll Jensen Huang laut Financial Times über eine Rückkehr an die Nvidia-Spitze nachdenken. Investoren und Silicon-Valley-Größen machen Druck auf den Verwaltungsrat, US-Finanzminister Scott Bessent fordert dagegen einen neuen Chef von außen. Entschieden ist nichts.", "zusammenfassung": "Jensen Huang war in der vergangenen Woche als Nvidia-Chef zurückgetreten, nachdem Berichte über mehrere Affären aufgekommen waren, unter anderem mit einer Managerin des Singapurer Nvidia-Kunden Megaspeed. Laut Financial Times, auf die sich ComputerBase und heise berufen, hat Huang mit Vertrauten bereits über eine mögliche Rückkehr gesprochen und unterstützt entsprechende Bemühungen. Eine Online-Initiative mit dem Motto „Holt Jensen zurück“ meldet inzwischen mehr als 170.000 Unterstützer, darunter nach eigenen Angaben über 8.200 Nvidia-Beschäftigte; unabhängig prüfen lassen sich diese Zahlen nicht. Zu den Initiatoren gehört Uber-Gründer Travis Kalanick, auch Elon Musk unterstützt die Kampagne. Die Großinvestoren Brad Gerstner (Altimeter Capital) und Gavin Baker (Atreides Management) fordern den Verwaltungsrat in einem offenen Brief auf, eine erneute Ernennung Huangs nicht auszuschließen. Gegenwind kommt aus Washington: US-Finanzminister Scott Bessent sprach sich am Sonntag dafür aus, den nächsten CEO außerhalb des Konzerns zu suchen. Zudem verlangt er laut Bericht binnen zehn Tagen Auskunft darüber, ob Nvidia die US-Exportregeln eingehalten hat. Der Bankenausschuss des US-Senats hat Huang und Handelsminister Howard Lutnick außerdem zu einer Anhörung geladen. Eine vom Verwaltungsrat beauftragte unabhängige Untersuchung läuft noch. Huang hält keine Aktienmehrheit und kann Beschlüsse des Gremiums nicht allein kippen. Bis zur Klärung führt Finanzchefin Colette Kress den Konzern kommissarisch, am Dienstag legt Nvidia Quartalszahlen vor.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/moegliches-comeback-von-mr-nvidia-ueber-170-000-unterstuetzer-draengen-auf-huangs-rueckkehr.100347/"}, "weitere_links": [{"name": "heise online", "url": "https://www.heise.de/news/Tage-nach-dem-Ruecktritt-Jensen-Huang-will-angeblich-wieder-Nvidia-CEO-werden-11525691.html"}, {"name": "IGN", "url": "https://www.ign.com/articles/jensen-huang-reportedly-weighing-return-as-nvidia-ceo-with-allies"}, {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354866/report-jensen-huang-eyes-nvidia-comeback"}], "tags": ["Nvidia", "Jensen Huang", "CEO", "Colette Kress", "Megaspeed"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. An empty executive leather chair pushed back from a long wooden boardroom table in a glass-walled conference room, a dark leather jacket draped over the chair back, scattered unreadable papers and a closed laptop on the table, city skyline softly blurred through the windows, muted dusty-teal accent from a glass carafe. No people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-huang-comeback-ft.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:19.917Z"}, "id": "2026-11-16-phantasialand-chlor-microsoft-ausfall", "datum": "2026-11-16T08:01:00+01:00", "label": "News", "bereich": "software", "themen": ["Microsoft 365"], "kategorie": "Software", "titel": "Folgen des Microsoft-Cloud-Ausfalls: Alarm-Mails eines Pool-Systems im Phantasialand-Hotel kamen nicht an, nach Chlor-Überdosierung gab es 15 Verletzte", "schlagzeile": "Alarm-Mail kam nie an: Microsoft-Ausfall führte zu 15 Verletzten", "kurz": "Wegen des Microsoft-Cloud-Ausfalls am Donnerstag und Freitag erreichte eine Alarm-Mail im Hotel Ling Bao des Phantasialands in Brühl niemanden. Ein defektes Dosiersystem hatte zu viel Chlor in einen Pool gegeben. 15 Gäste klagten über Atemwegsbeschwerden, vier kamen ins Krankenhaus.", "zusammenfassung": "Laut WDR, auf den sich heise beruft, schlug das Wartungs- und Sicherheitssystem der Saunalandschaft per E-Mail Alarm. Wegen des lang andauernden Ausfalls von Microsofts Cloud-Diensten kamen diese Mails aber nicht an. Das automatische Dosiersystem des Pools war defekt und gab deutlich zu viel Chlor ins Wasser. Am Freitagnachmittag trat dadurch im Schwimmbadbereich des zum Phantasialand gehörenden Hotels Chlorgas aus. Zunächst klagten 13 Gäste über Atemwegsbeschwerden, später stieg die Zahl auf 15. Vier Personen kamen ins Krankenhaus, eine musste mit mittelschweren Verletzungen zur Beobachtung bleiben. Die Feuerwehr Brühl war mit 40 Einsatzkräften rund zwei Stunden vor Ort, der Pool wurde gesperrt und das Wasser ausgetauscht; inzwischen ist er wieder offen. Der Microsoft-Ausfall dauerte von Donnerstagnachmittag bis mindestens Freitagmittag. Laut heise hatte er damit reale und gefährliche Folgen, zudem nutzen Kriminelle ihn seit Freitag für Phishing-Mails.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Microsoft-Cloud-Ausfall-fuehrte-zu-15-Verletzten-im-Phantasialand-11525711.html"}, "weitere_links": [], "tags": ["Microsoft 365", "Cloud-Ausfall", "Phantasialand", "E-Mail", "Störung"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. An empty indoor hotel spa pool hall cordoned off with red-and-white barrier tape, calm turquoise water, wooden loungers along the tiled edge, a technician's open toolbox and a water-testing kit standing next to a wall-mounted unbranded dosing pump unit with blank display, warm daylight from large windows, muted terracotta accent from towels. No people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-phantasialand-chlor-microsoft-ausfall.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.113Z"}, "id": "2026-11-16-intel-sammelklage", "datum": "2026-11-16T07:50:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Intel"], "kategorie": "Unternehmen", "titel": "Aktionäre reichen in San José Sammelklage gegen Intel, CEO Lip-Bu Tan und weitere Manager ein: Der Konzern soll den PC-Absatzeinbruch zu spät offengelegt haben", "schlagzeile": "Kurssturz um 29 Prozent: Aktionäre verklagen Intel und CEO Lip-Bu Tan", "kurz": "Intel-Aktionäre haben vor einem US-Bundesgericht in San José eine Sammelklage gegen den Konzern, CEO Lip-Bu Tan und weitere Führungskräfte eingereicht. Sie werfen Intel vor, den Einbruch der PC-Verkäufe zu spät offengelegt zu haben. Nach den Quartalszahlen am 29. Oktober war die Aktie um fast 29 Prozent abgestürzt.", "zusammenfassung": "Eingereicht hat die Klage die Kanzlei Robbins Geller Rudman & Dowd, berichtet heise unter Berufung auf die BBC; auch Reuters berichtet darüber. Sie gilt für alle Aktionäre, die zwischen dem 23. Juli und dem 29. Oktober 2026 Intel-Aktien gekauft haben. Vorgeworfen werden „wesentlich falsche und/oder irreführende“ Aussagen zum Rückgang der PC-Verkäufe und zu den Folgen der Rechenzentrumsprojekte. Laut Wccftech richtet sich die Klage neben CEO Lip-Bu Tan auch gegen Finanzchef David Zinsner und verweist auf eine Kapitalerhöhung über 23 Milliarden Dollar im August. Am 29. Oktober hatte Intel eingeräumt, dass wegen der Speicherkrise noch weniger PCs verkauft wurden als erwartet, und Lieferprobleme bei Rechenzentrumschips gemeldet. Für das laufende Quartal erwartet der Konzern nur 15 bis 16 Milliarden Dollar Umsatz, Analysten hatten mit rund 17 Milliarden gerechnet. Die Aktie verlor daraufhin an einem Tag fast 29 Prozent. Intel hat die Klage bisher nicht kommentiert. Die Kläger fordern Schadenersatz in nicht genannter Höhe, über die Vorwürfe muss nun das Gericht entscheiden.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Nach-heftigem-Kursrutsch-Sammelklage-gegen-Intel-wegen-irrefuehrender-Angaben-11525703.html"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/intel-ceo-lip-bu-tan-named-defendant-class-action-lawsuit-pc-sales-slowdown/"}], "tags": ["Intel", "Sammelklage", "Lip-Bu Tan", "Aktie", "Speicherkrise"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A wooden judge's gavel resting on a stack of unmarked document folders on a dark walnut courtroom desk, next to it a bare unbranded desktop CPU chip in a small clear plastic tray, brass desk lamp, warm window light, muted olive-green accent from a leather desk pad. No readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-intel-sammelklage.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.014Z"}, "id": "2026-11-16-playstation-controller-bezahlen-patent", "datum": "2026-11-16T07:50:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen", "titel": "Sony-Patentanmeldung: PlayStation-Controller soll Zahlungsdaten per NFC, Bluetooth oder QR-Code von Smartphone und Karten lesen", "schlagzeile": "Bezahlen per Controller? Sony-Patent macht PlayStation-Pad zum Kartenleser", "kurz": "Sony hat einen PlayStation-Controller zum Patent angemeldet, der Zahlungsdaten per NFC, Bluetooth oder QR-Code von Smartphone oder Karte liest. So sollen Käufe auf der Konsole ohne lästiges Eintippen klappen. Angekündigt ist ein solches Produkt nicht.", "zusammenfassung": "Die Anmeldung „Video Game Controller-Driven Information Transfer“ (US 2026/0273403 A1) stammt vom 17. März 2025, veröffentlicht hat sie das US-Patentamt am 17. September 2026, berichten Golem und Engadget. Fordert die Konsole eine Zahlung an, hält man ein Smartphone oder eine Karte an den Controller. Der erkennt das Gerät per NFC, Bluetooth oder Berührung, eine Variante liest per Bildsensor einen QR-Code vom Handy-Display. Licht, Ton oder Vibration bestätigen die Verbindung, danach prüft die Konsole die Daten bei einem Server. Genannt werden Kredit- und Bankkonten, Geschenkkarten sowie digitale und Krypto-Wallets; das Restguthaben einer Geschenkkarte soll direkt auf dem Bildschirm erscheinen. Neben Spielekäufen nennt Sony In-App-Käufe, Merchandise, Essenslieferungen und Guthaben für Turniere, Messen und Spielhallen. Auch Spielerprofile teilen, Multiplayer-Sitzungen beitreten oder Screenshots ans Handy schicken soll per Antippen gehen. Sony begründet die Idee damit, dass heutige Abläufe oft mehrere Geräte und Tastatureingaben erfordern. Eine Patentanmeldung schützt aber nur eine Idee, ob Sony sie je umsetzt, ist offen.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/patentanmeldung-playstation-controller-koennte-bald-als-kartenleser-dienen-2611-215238.html"}, "weitere_links": [{"name": "Engadget", "url": "https://www.engadget.com/2313652/sony-patent-playstation-controller-adds-credit-card-reader/"}], "tags": ["Sony", "PlayStation", "Controller", "Patent", "NFC"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A hand holding a plain unbranded white-and-black modern game controller on a sofa while the other hand taps a blank unmarked contactless payment card against the controller's center touchpad, a television softly out of focus in the background, cozy living room in warm afternoon light, muted dusty-blue accent from a throw blanket. Natural hands with five fingers, no readable text or numbers on the card, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-playstation-controller-bezahlen-patent.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.202Z"}, "id": "2026-11-16-razor-lake-12p-bllc", "datum": "2026-11-16T02:13:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["Intel", "CPU"], "kategorie": "Prozessoren", "titel": "Leak: Intel Razor Lake soll einen Gaming-Chip mit 12 P-Kernen, 4 LP-E-Kernen und großem bLLC-Cache ohne reguläre E-Kerne bekommen, gefertigt in Intel 18A-P", "schlagzeile": "Leak: Intel soll Gaming-CPU mit 12 P-Kernen und Riesen-Cache planen", "kurz": "Der Leaker Jaykihn berichtet von einem Razor-Lake-Desktopchip mit zwölf P-Kernen, vier Low-Power-Kernen und großem Cache (bLLC), aber ohne normale E-Kerne. Er wäre Intels Antwort auf AMDs X3D-Prozessoren. Razor Lake wird erst für 2028 erwartet, offiziell ist nichts davon.", "zusammenfassung": "Laut TechPowerUp und VideoCardz hat der bekannte Intel-Leaker Jaykihn auf X eine Konfiguration namens „12+0+4“ für Razor Lake genannt. Gemeint sind zwölf P-Kerne, keine regulären E-Kerne und vier sparsame LP-E-Kerne, kombiniert mit Intels großem Last-Level-Cache (bLLC). Das bLLC-Konzept gilt als Intels Gegenstück zu AMDs X3D-Chips mit zusätzlichem Cache, die vor allem in Spielen stark sind. Der übertaktbare Chip soll ein zuvor gemunkeltes, gesperrtes 8+0+4-Modell mit bLLC ersetzen. Alle zwölf P-Kerne sollen auf einem eigenen Compute-Die sitzen, das laut Jaykihn in Intels 18A-P-Verfahren gefertigt wird, während die meisten Razor-Lake-Tiles angeblich bei TSMC entstehen. Außerdem soll ein 125-Watt-Modell mit 6+12+4 Kernen und bLLC von Nova Lake auf Razor Lake verschoben worden sein. Nova Lake-S hätte damit eine bLLC-Variante weniger als erwartet. Razor Lake-S wird für 2028 erwartet und soll denselben Sockel LGA 1954 wie Nova Lake-S nutzen. Intel hat Razor-Lake-Modellnummern zwar in einer ISA-Referenz gelistet, die Spezifikationen sind aber nicht bestätigt. Pläne so weit in der Zukunft können sich noch ändern.", "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Jaykihn gilt als gut informierter Intel-Leaker, die Angaben sind aber nicht offiziell und betreffen ein Produkt für 2028. TechPowerUp und VideoCardz geben nur den Leak wieder."}, "ursprungsquelle": "Jaykihn auf X", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354867/intel-razor-lake-gets-a-12-p-core-bllc-chip-with-no-e-cores-per-leak"}, "weitere_links": [{"name": "VideoCardz auf X", "url": "https://x.com/VideoCardz/status/2122050797189939388"}], "tags": ["Intel", "Razor Lake", "bLLC", "Nova Lake", "18A-P", "LGA 1954"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. Macro photo of an unbranded modern desktop processor with a plain brushed metal heat spreader lying on an anti-static mat on a wooden workbench, a few loose LGA socket protective covers and a pair of tweezers beside it, the underside contact pads hinted in a second chip standing on edge, muted terracotta accent from a small parts tray. No readable text, no logos, no brand markings, no engraved lettering.", "bild": {"datei": "assets/img/news/2026-11-16-razor-lake-12p-bllc.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.295Z"}, "id": "2026-11-16-pokepark-fishing-rally-gefunden", "datum": "2026-11-16T01:59:00+01:00", "label": "News", "bereich": "games", "themen": ["Pokémon", "Retro"], "kategorie": "Spiele", "titel": "Verschollenes Pokémon-Spiel gefunden: Sammler entdeckt Testkassette mit PokéPark Fishing Rally DS von 2005, PSA Video Games bestätigt die Echtheit", "schlagzeile": "Verschollenes Pokémon-Spiel nach 20 Jahren aufgetaucht – und spielbar", "kurz": "Ein Sammler hat eine Testkassette mit PokéPark Fishing Rally DS gefunden, einem Angelspiel, das es 2005 nur in einem japanischen Freizeitpark gab. PSA Video Games hat die Echtheit bestätigt. Damit ist ein lange verschollenes Stück Pokémon-Geschichte erhalten.", "zusammenfassung": "PokéPark Fishing Rally DS war 2005 nur wenige Monate im PokéPark in Nagoya erhältlich. Besucher luden das Angel-Minispiel per Download Play an Stationen im Park auf ihren Nintendo DS. Nach zwölf Stunden oder beim Ausschalten der Konsole löschte es sich wieder. Spieler fingen Pokémon und kämpften in Ranglisten um Preise. Nach der Schließung des Parks galt das Spiel als verschollen, weil es nur auf speziellen Testkassetten für das Personal lag. Eine im Juli bei eBay für 9.000 Dollar angebotene Kassette enthielt nur die Ranglisten-Software. Jetzt besitzt Sammler Daniel Quadri laut Polygon eine Kassette mit dem eigentlichen Spiel, PSA Video Games hat sie als echt bestätigt. Mit ihr kann er das Spiel wie damals per Download Play an andere DS-Konsolen schicken. Vorerst bleibt die Kassette zum Schutz in einer versiegelten Hülle.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/pokemon-pokepark-fishing-rally-ds-found/"}, "weitere_links": [], "tags": ["Pokémon", "Nintendo DS", "Lost Media", "PokéPark", "Retro"], "img_prompt": "Documentary photo of a retro game collector's desk in warm late-morning window light: a plain unbranded small grey handheld-console game cartridge sealed in a clear protective acrylic case lying on a wooden table, an old unbranded dual-screen handheld console opened beside it, a jeweller's loupe and white cotton gloves, a few colorful toy fishing lures blurred in the background, natural rich colors, muted coral accent, shallow depth of field. No readable text, no labels, no logos, no brand markings, no recognizable characters.", "bild": {"datei": "assets/img/news/2026-11-16-pokepark-fishing-rally-gefunden.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.389Z"}, "id": "2026-11-16-wireview-pro-ii-garantie", "datum": "2026-11-16T01:35:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "12V-2x6"], "kategorie": "Grafikkarten", "titel": "Thermal Grizzly veröffentlicht die Bedingungen der erweiterten GPU-Garantie für den WireView Pro II: 24 Monate Schutz bei Steckerschäden, aber nur mit aktiver Überwachung", "schlagzeile": "Stecker geschmolzen? Thermal Grizzly erklärt, wann die GPU-Garantie greift", "kurz": "Thermal Grizzly hat die Bedingungen für die erweiterte Grafikkarten-Garantie des WireView Pro II veröffentlicht. Sie deckt Schäden am 12VHPWR- bzw. 12V-2x6-Stecker und daraus folgende GPU-Schäden 24 Monate lang ab. Die Überwachung muss dafür aktiv bleiben, Shunt-Mods und Mining sind ausgeschlossen.", "zusammenfassung": "Der WireView Pro II sitzt zwischen Netzteilkabel und Grafikkarte und misst den Strom auf jeder einzelnen 12-Volt-Leitung. Thermal Grizzly verspricht Käufern eine erweiterte Garantie für Schäden am Stromstecker, laut TechPowerUp hat der Hersteller die Bedingungen nun in einer FAQ erklärt. Weder das USB-Kabel noch der Y-Splitter zum Mainboard müssen angeschlossen sein; über den Splitter kann das Gerät den PC im Notfall abschalten, das wird aber nur empfohlen. Die Überwachung muss eingeschaltet bleiben: Grenzwerte für Strom, Temperatur oder Leistung darf man senken, aber nicht über die Standardwerte anheben. Verlängerungen zwischen WireView und Grafikkarte sind erlaubt, solange jede 12-Volt-Leitung getrennt bleibt; Adapter, die Leitungen intern zusammenführen, sind nicht abgedeckt. Ein 90-Grad-Stecker ist für sich kein Problem, auf der Netzteilseite gelten Kabel, die für das jeweilige Netzteilmodell freigegeben sind. Die Garantie läuft 24 Monate ab Kauf des WireView, auch über die Garantie der Grafikkarte hinaus, gilt aber nur für den Erstkäufer mit Kaufbeleg. Ausgeschlossen sind Shunt-Mods, XOC-BIOS mit erhöhtem Power-Target und kommerzielles Mining, ebenso Schäden ohne Bezug zum Stecker. Im Schadensfall versucht Thermal Grizzly zuerst eine Reparatur, sonst gibt es eine Karte mit vergleichbarer Leistung, nicht unbedingt derselben Marke. Wer Schmelzspuren entdeckt, soll den PC ausschalten, das Netzteil vom Strom trennen, den Stecker stecken lassen, Fotos machen und den Support kontaktieren.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354864/thermal-grizzly-details-wireview-pro-ii-extended-gpu-warranty-conditions"}, "weitere_links": [], "tags": ["Thermal Grizzly", "WireView Pro II", "12V-2x6", "12VHPWR", "Garantie"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. Close-up of the power connector area of an unbranded high-end graphics card with two visible axial fans lying on a wooden workbench, a small plain black inline power-monitoring module with a tiny blank display plugged between a braided 16-pin power cable and the card, a multimeter and a flashlight nearby, muted dusty-teal accent from a silicone mat. No readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-wireview-pro-ii-garantie.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.485Z"}, "id": "2026-11-16-windows11-remote-lock-intune", "datum": "2026-11-16T01:04:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Windows 11 Insider Build 29708.1001 testet Remote Lock: IT kann verlorene Firmen-PCs über Intune sperren, ohne Daten zu löschen; nur die IT kann die Sperre aufheben", "schlagzeile": "Laptop weg? Windows 11 testet Fernsperre, die nur die IT aufheben kann", "kurz": "Microsoft testet in einer Insider-Vorschau die Funktion Remote Lock. IT-Abteilungen können damit verlorene oder gestohlene Firmen-PCs über Intune sperren, ohne Daten zu löschen. Passwort, PIN oder lokaler Admin helfen dann nicht mehr weiter.", "zusammenfassung": "Windows Latest hat die Funktion in Build 29708.1001 im experimentellen Kanal „Future Platforms“ vom 13. November entdeckt. Bei einer Sperre meldet Windows alle Sitzungen ab, blendet die Anmeldeoptionen aus und zeigt einen Sperrbildschirm mit dem Hinweis, die Organisation habe das Gerät gesperrt. Laut Microsoft wird dabei nichts gelöscht, BitLocker bleibt aktiv und das Gerät bleibt in Intune verwaltet. Neustart oder Trennen vom Internet heben die Sperre nicht auf, entsperren kann nur die IT über Intune. Das Benutzerkonto selbst bleibt aktiv, bei gestohlenen Zugangsdaten muss die IT es separat in Entra ID sperren. Voraussetzung sind Windows Pro, Enterprise oder Education und ein per Entra ID oder MDM verwaltetes Gerät; eingerichtet wird das Ganze derzeit umständlich über ein benutzerdefiniertes Intune-Profil. Der Haken: Ein Gerät, das offline ist, erhält die Sperre erst bei der nächsten Verbindung. Zudem blockiert Remote Lock weder Wiederherstellungsumgebung, abgesicherten Modus noch das Booten vom USB-Stick, weshalb Microsoft BitLocker weiter für nötig hält. Noch im März 2025 hatte ein Microsoft-Mitarbeiter gesagt, eine Fernsperre für Windows sei nicht geplant. Als Insider-Test kann sich die Funktion bis zur Veröffentlichung noch ändern.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/16/your-windows-11-work-laptop-can-now-be-locked-remotely-and-no-password-pin-or-admin-account-can-get-you-back-in-only-it-can/"}, "weitere_links": [], "tags": ["Windows 11", "Insider", "Remote Lock", "Intune", "BitLocker"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. An unbranded silver business laptop left alone on a café table near a window, its screen showing a plain blurred lock-screen image with a simple padlock-like abstract shape and no text, a forgotten scarf and an empty espresso cup beside it, warm late-morning daylight, muted olive-green accent from a chair cushion, shallow depth of field. No people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-windows11-remote-lock-intune.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.569Z"}, "id": "2026-11-16-linux-7-4-rc3-zen5", "datum": "2026-11-15T23:55:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Linux", "titel": "Linux 7.4-rc3 veröffentlicht: TSA-Mitigation für AMD Zen 5, Stromspar-Funktionen für AMD-Grafik, Workarounds für ARM-Kerne und bessere Sensorunterstützung", "schlagzeile": "Linux 7.4-rc3: Schutz für Zen-5-CPUs und Stromsparen für AMD-Grafik", "kurz": "Linus Torvalds hat den dritten Release Candidate von Linux 7.4 veröffentlicht. Er bringt laut Neowin eine Schutzmaßnahme für AMDs Zen-5-Prozessoren und Stromspar-Funktionen für bestimmte AMD-Grafikchips. Die fertige Version wird nach sieben Release Candidates erwartet.", "zusammenfassung": "Torvalds beschreibt die vergangene Woche als weitgehend normal, die meisten Änderungen betreffen Netzwerk- und Grafiktreiber und sind klein. Im Dateisystembereich fällt eine große, inhaltlich aber triviale Änderung an der Aufrufkonvention von iomap auf. Laut Neowin enthält rc3 eine als kritisch beschriebene Mitigation gegen die Mikroarchitektur-Schwachstelle TSA bei AMDs Zen-5-Prozessoren. Für AMD-Grafik mit der IP-Version 11.0.2 werden Stromspar-Funktionen wie Multi-Coarse Gate Clock und Fine-Grain Clock Gating aktiviert. Bei den ARM-Kernen Cortex-A715 und Cortex-A720 umgeht der Kernel fehlerhafte Leistungszähler, die falsche Messwerte und Kernel-Warnungen auslösen können. Für kommende Intel-Grafikplattformen gibt es Korrekturen bei der Bildschirmerkennung an USB-C-Anschlüssen. Außerdem liest der Kernel Spannungen, Lüfterdrehzahlen und Temperaturen von Mainboards mit NCT6775-Sensorchips zuverlässiger aus. Damit ist etwa die Hälfte des Entwicklungszyklus erreicht. Distributionen wie Arch und Fedora übernehmen neue Kernel meist erst nach dem ersten Punkt-Release.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/linux-74-rc3-lands-with-critical-zen-5-mitigations-and-power-saving-gpu-features/"}, "weitere_links": [{"name": "Phoronix", "url": "https://www.phoronix.com/news/Linux-7.4-rc3-Released"}], "tags": ["Linux", "Linux 7.4", "Kernel", "AMD Zen 5", "Linus Torvalds"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A small home-lab desk with an open unbranded mini-PC motherboard and CPU cooler, a laptop beside it showing a blurred unreadable terminal window with scrolling lines, a plush penguin toy softly out of focus on a shelf, warm late-morning light, muted dusty-teal accent from a cable. No readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-linux-7-4-rc3-zen5.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.658Z"}, "id": "2026-11-16-project-helix-konsole-pc-spiele", "datum": "2026-11-15T23:18:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Xbox", "Konsolen"], "kategorie": "Konsolen", "titel": "Xbox-Vizepräsident Jason Ronald: Project Helix ist eine Konsole, die auch PC-Spiele ausführt, kein PC für Konsolenspiele; Neural Rendering soll gegen hohe Bauteilkosten helfen", "schlagzeile": "Project Helix: Nächste Xbox ist eine Konsole, die auch PC-Spiele kann", "kurz": "Microsoft hat im Magazin zum 25. Xbox-Jubiläum neue Details zu Project Helix genannt. Laut Xbox-Vizepräsident Jason Ronald ist Helix eine Konsole, die auch Spiele vom PC ausführen kann, kein PC für Konsolenspiele. Gegen hohe Bauteilkosten setzt Microsoft unter anderem auf Neural Rendering.", "zusammenfassung": "Zum 25. Geburtstag der Xbox hat Microsoft überraschend ein Jubiläumsmagazin veröffentlicht, IGN und Insider Gaming haben die Aussagen zu Project Helix zusammengefasst. „Helix ist als Konsole gedacht, die auch Spiele von deinem PC abspielen kann. Es ist kein PC, der auch Konsolenspiele abspielen kann“, sagt Jason Ronald, Vizepräsident für die nächste Generation. Spieler sollen ihre Bibliothek aus vier Xbox-Generationen samt Fortschritt mitnehmen können, die Grenzen zwischen Konsolen- und PC-Spielen sollen fallen. Für Power-User soll es trotzdem tiefere Einstellungen für Grafik und Leistung geben. Ronald nennt den ROG Xbox Ally als Vorläufer, dessen Konzepte und Rückmeldungen in Helix einfließen. Die Bewahrung alter Spiele sei zentral: Kompatibilität bestimme schon heute, wie die Plattform entworfen werde. Zur Bauteilkrise sagt Ronald, man müsse neue Technik erfinden, um Konsolen bezahlbar zu halten. Neural Rendering könne Bilder erzeugen, ohne mehr Rechenleistung oder Speicher zu benötigen. Einen Termin oder Preis nennt Microsoft nicht, laut IGN wird über einen Start frühestens Ende 2027 spekuliert. Wie die Geräte der Helix-Familie aussehen, ist weiter offen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/xbox-confirms-project-helix-is-a-console-capable-of-playing-games-from-your-pc"}, "weitere_links": [{"name": "Insider Gaming (Konsole zuerst)", "url": "https://insider-gaming.com/xbox-project-helix-console-first-not-pc/"}, {"name": "Insider Gaming (Neural Rendering)", "url": "https://insider-gaming.com/xbox-project-helix-neural-rendering/"}, {"name": "Insider Gaming (Spielebewahrung)", "url": "https://insider-gaming.com/xbox-game-preservation-project-helix/"}], "tags": ["Xbox", "Project Helix", "Jason Ronald", "Neural Rendering", "Konsole"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A sleek unbranded matte-black game console prototype standing next to a compact gaming PC tower on a warm wooden living-room media shelf, a wireless gamepad and a keyboard lying side by side in front, a large TV out of focus in the background, golden afternoon window light, muted dusty-teal accent from a cushion. No readable text, no logos, no brand markings, no recognizable real products.", "bild": {"datei": "assets/img/news/2026-11-16-project-helix-konsole-pc-spiele.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.747Z"}, "id": "2026-11-16-gta6-jason-lucia-kleinkriminelle", "datum": "2026-11-15T20:41:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6: Jason und Lucia starten laut Rockstar-Interview mit The Guardian als Kleinkriminelle und müssen sich zu großen Coups hocharbeiten", "schlagzeile": "GTA 6: Jason und Lucia fangen als kleine Gauner an – große Coups erst später", "kurz": "In GTA 6 starten Jason und Lucia nicht als Profi-Räuber, sondern als Kleinkriminelle. Das berichtet The Guardian nach Gesprächen mit Rockstar. Lukrative Jobs wie Juwelierüberfälle sollen erst später möglich sein.", "zusammenfassung": "Die britische Zeitung The Guardian hat mit Rob Nelson, Co-Studiochef von Rockstar North, und Publishing-Chefin Jennifer Kolbe gesprochen, IGN fasst den Bericht zusammen. Demnach können die beiden Hauptfiguren zu Beginn nur einfache Autos kurzschließen und simple Schlösser knacken. Juweliere in Vice City ausrauben oder mit Sportwagen durch Leonida fahren können sie erst, wenn sie sich hochgearbeitet haben. Nelson beschreibt Jason und Lucia als junges Paar, das „mit dem Rücken zur Wand“ steht. Überfälle von der Tankstelle bis zur Luxusboutique sollen leichter oder ertragreicher werden, wenn man sie vorbereitet, etwa Kameras ausschaltet, Überwachungsvideos stiehlt oder unauffällige Eingänge auskundschaftet. Wer die Vorbereitung auslässt, riskiert, dass ein Raub schnell im Chaos endet. Zum ersten Mal in der Serie soll es laut Guardian zudem Mechaniken geben, die Empathie fördern. Was das konkret bedeutet und wie lange der Aufstieg dauert, sagt Rockstar noch nicht. GTA 6 erscheint am 19. November für PS5 und Xbox Series X|S.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/gta-6s-jason-and-lucia-will-start-as-small-time-criminals-who-have-to-work-up-to-high-value-jobs"}, "weitere_links": [], "tags": ["GTA 6", "Rockstar Games", "Jason", "Lucia", "The Guardian"], "img_prompt": "Dynamic original crime-action illustration at dusk in a sun-bleached subtropical coastal town: an original-design young woman and man in casual summer clothes sprinting away from a modest corner gas-station convenience store, one glancing back over the shoulder, a beat-up old compact car with an open door waiting at the curb, palm trees and pastel stucco walls, low close camera, strong diagonal motion, flying receipts-free paper bags and dust, warm golden sunset light against cool blue shadows, rich natural colors, muted coral-pink accent. Original characters only, no copies of known game characters, no weapons pointed at people, no text, no logos, no signs with lettering, no UI.", "bild": {"datei": "assets/img/news/2026-11-16-gta6-jason-lucia-kleinkriminelle.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.845Z"}, "id": "2026-11-16-xbox-boot-animationen-25", "datum": "2026-11-15T20:05:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Konsolen-Update", "titel": "Zum 25-jährigen Jubiläum: Xbox Series X|S und Xbox One bekommen die Startanimation der Original-Xbox und zwei Startanimationen der Xbox 360", "schlagzeile": "Zum 25. Geburtstag: Xbox bringt die Original-Startanimation zurück", "kurz": "Zum 25. Jubiläum der Xbox können Besitzer einer Xbox Series X|S und Xbox One wieder die Startanimation der ersten Xbox nutzen. Dazu kommen zwei Startanimationen der Xbox 360 aus den Jahren 2005 und 2010. Das Update wird laut Xbox im Laufe des Tages verteilt.", "zusammenfassung": "Microsoft feierte am 15. November 25 Jahre Xbox und kündigte auf dem offiziellen Xbox-Account auf X drei neue alte Startanimationen an. Neben der Sci-Fi-Einleitung der Original-Xbox gibt es zwei Varianten der Xbox 360, eine vom Marktstart 2005 und eine aus dem Jahr 2010. Laut IGN sind es weitgehend unveränderte Übernahmen der damaligen Videos. Die Animationen kommen auf alle Konsolen der Xbox Series X|S und der Xbox One und werden schrittweise verteilt. Wer sie noch nicht sieht, muss etwas Geduld haben. Zum Jubiläum hat Microsoft außerdem ein Magazin mit Rückblick und Ausblick veröffentlicht, darin auch neue Details zur nächsten Generation Project Helix. Eine erste neue Startsequenz hatte Microsoft bereits früher in diesem Jahr ergänzt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/xbox-reveals-original-and-360-boot-up-options-for-25th-anniversary"}, "weitere_links": [{"name": "Xbox auf X", "url": "https://x.com/XBOX/status/2122043347078672876"}], "tags": ["Xbox", "25 Jahre Xbox", "Xbox 360", "Startanimation", "Nostalgie"], "img_prompt": "Documentary photo of a cozy living room in warm evening lamp light: a person seen from behind sitting on a worn sofa holding an unbranded game controller, the TV screen in the background glowing with an abstract swirling green-and-white light pattern without any symbols, an old bulky unbranded black console from the early 2000s on the shelf beside a modern one, natural rich colors, muted moss-green accent, shallow depth of field. No readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-xbox-boot-animationen-25.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:20.938Z"}, "id": "2026-11-16-librem-5-v2-risc-v", "datum": "2026-11-15T19:39:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Linux", "RISC-V"], "kategorie": "Smartphones", "titel": "Purism startet Crowdfunding für das Linux-Smartphone Librem 5 v2 mit Achtkern-RISC-V-SoC SpacemiT K1, 8 GB RAM und 128 GB Speicher ab 1.599 US-Dollar", "schlagzeile": "Linux-Handy Librem 5 v2 setzt auf RISC-V – für stolze 1.599 Dollar", "kurz": "Purism sammelt Geld für die zweite Generation seines Linux-Smartphones Librem 5. Statt eines Arm-Chips steckt ein Achtkern-RISC-V-Prozessor von SpacemiT darin, dazu 8 GB RAM und 128 GB Speicher. Wer mitmacht, zahlt mindestens 1.599 Dollar und bekommt das Gerät nicht vor 2028.", "zusammenfassung": "Der Librem 5 v2 nutzt den SpacemiT K1 mit acht RISC-V-Kernen und ersetzt damit den Vierkern-Arm-Chip von NXP aus dem ersten Modell. Purism verspricht mehr Leistung, längere Akkulaufzeit und weniger Abwärme. Der Arbeitsspeicher steigt von 3 auf 8 GB, der interne Speicher von 32 auf 128 GB. Gehäuse, 5,7-Zoll-IPS-Display mit 720 × 1440 Pixeln und der wechselbare 4.500-mAh-Akku bleiben gleich, damit Reparaturen und Upgrades zwischen den Generationen leichter fallen. Auch die Hardware-Schalter für Kamera, Modem und GPS, USB-C und die Kopfhörerbuchse bleiben erhalten. Neu sind ein verbessertes 4G-Modem, Dual-SIM und Hardware-Kodierung, mit der erstmals 13-Megapixel-Fotos und HD-Videos möglich sein sollen; ein 5G-Modul ist als Tauschmodul geplant. Als Betriebssystem läuft das Debian-basierte PureOS mit der Oberfläche Phosh. OMG! Ubuntu erinnert daran, dass die erste Generation unter Verzögerungen, Preiserhöhungen und schwankender Verarbeitung litt. Der Wechsel auf RISC-V bringt zudem viel Arbeit bei Grafiktreibern, Energieverwaltung und Browser-Leistung mit sich. Die Crowdfunding-Kampagne läuft bis Februar 2027.", "quelle": {"name": "OMG! Ubuntu", "url": "https://www.omgubuntu.co.uk/2026/11/librem-5-risc-v-new-linux-phone"}, "weitere_links": [], "tags": ["Purism", "Librem 5", "RISC-V", "Linux-Smartphone", "PureOS"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A thick unbranded black smartphone with a plain matte back lying face down on a wooden desk, its removable back cover and battery taken out beside it, three small hardware slide switches visible on the side, a tiny screwdriver and a microSD card nearby, a blurred laptop with a terminal window in the background, muted olive-green accent from a notebook cover. No readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-librem-5-v2-risc-v.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:21.031Z"}, "id": "2026-11-16-fbi-artex-ki-angriffe", "datum": "2026-11-15T19:29:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit", "KI"], "kategorie": "Sicherheit", "titel": "FBI warnt vor ARTEX: KI-gestütztes Pentest-Framework wird seit August 2026 für automatisierte Angriffe weltweit missbraucht, unter anderem beim ConnectWise-Lieferkettenangriff", "schlagzeile": "FBI warnt: KI-Werkzeug ARTEX automatisiert weltweit Hackerangriffe", "kurz": "Das FBI warnt vor ARTEX, einem KI-gestützten Pentest-Framework, das Angreifer seit mindestens August 2026 missbrauchen. Manche Einbrüche führten in unter drei Stunden zu privilegiertem Zugriff. Auch der Lieferkettenangriff auf ConnectWise im Oktober soll damit gelaufen sein.", "zusammenfassung": "In einer FLASH-Warnung vom Freitag schreibt das FBI, mehrere Tätergruppen setzten das quelloffene Framework gegen Organisationen aus Finanzwesen, Verwaltung, Technik, Verteidigung, Gesundheitswesen und weiteren Branchen ein, berichtet BleepingComputer. ARTEX ist in Go geschrieben und lässt KI-Agenten Aufklärung, Schwachstellensuche, Angriff, Rechteausweitung und Datendiebstahl weitgehend selbstständig erledigen. Ein eigenes KI-Modell hat es nicht, es bindet externe Sprachmodelle wie Claude, GPT, DeepSeek, GLM, Grok und Kimi an. Laut FBI können so auch Angreifer mit wenig Fachwissen mehrere Ziele gleichzeitig angreifen. Besonders gut findet das Werkzeug Lücken in vernachlässigten Systemen wie Partnerportalen, Mitarbeiter-Apps, Altdiensten und Drittanbieter-Anbindungen. Der Entwickler „Autumn-27“ hatte ARTEX im Juli auf GitHub veröffentlicht und am 8. Oktober wieder entfernt, doch Forks, Archivkopien und eine kommerzielle Version namens ARTEX PRO sind weiter im Umlauf. Anfang November zählten Forscher über 1.600 offen erreichbare ARTEX-Konsolen. Zu den genannten Angriffen gehört der Lieferkettenangriff auf ConnectWise Cloud Backup im Oktober, über den Angreifer in Microsoft-365-Umgebungen von Kunden gelangten. Das FBI empfiehlt, öffentlich erreichbare Anwendungen und Cloud-Verwaltungszugänge abzusichern, Berechtigungen und Anmeldeprotokolle zu prüfen und sensible Schnittstellen zu drosseln. Der Sicherheitsforscher MalwareMustDie hat zudem ein freies Paket mit Erkennungsregeln für gängige Sicherheitswerkzeuge veröffentlicht.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/fbi-warns-artex-ai-hacking-tool-is-powering-global-cyberattacks/"}, "weitere_links": [], "tags": ["FBI", "ARTEX", "KI", "Cyberangriff", "ConnectWise"], "img_prompt": "Documentary photo, warm natural late-morning daylight, natural rich colors, shallow depth of field, 35mm f/2.8 look. A dim security operations room in warm late-afternoon light: two large monitors showing blurred unreadable network graphs and log lines, a mechanical keyboard, a half-empty coffee mug and a notepad with blank pages on a wooden desk, a server rack with small status lights softly out of focus behind, muted amber accent from a desk lamp. No people, no readable text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-16-fbi-artex-ki-angriffe.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.309Z"}, "id": "2026-11-15-cyberpunk-torrent-regen-mod", "datum": "2026-11-15T18:39:00+01:00", "label": "News", "bereich": "games", "themen": ["PC-Spiele", "Mods"], "kategorie": "Spiele", "titel": "Cyberpunk-2077-Mod „Torrent“ ersetzt den Regen in Night City durch einzelne 3D-Tropfen und bringt Gewitter mit Blitzen", "schlagzeile": "Cyberpunk 2077: Neue Mod lässt es in Night City endlich richtig regnen", "kurz": "Die Mod Torrent ersetzt die flachen Regeneffekte von Cyberpunk 2077 durch einzelne 3D-Tropfen, Gischt und Gewitter. Die Tropfen reagieren auf Wind, Licht und Fahrtempo. Die Mod ist kostenlos bei Nexus Mods erhältlich.", "zusammenfassung": "Der Modder CyanideX hat für Cyberpunk 2077 die Mod Torrent veröffentlicht, berichtet Eurogamer mit Verweis auf DSOGaming. Sie ersetzt die bisher eher flachen Regeneffekte durch einzelne 3D-Tropfen mit eigener Größe und Fallgeschwindigkeit. Die Tropfen reagieren auf die Bewegung des Spielers, bei schneller Fahrt prasseln sie auf die Windschutzscheibe zu, und starker Wind drückt sie zur Seite. Straßenlaternen, Leuchtreklamen und Autoscheinwerfer spiegeln sich in den Tropfen, durch Dächer und in Gebäude regnet es nicht mehr. Auf dem Boden spritzen Tropfen auf, bei starkem Regen liegt Dunst in der Ferne, und Autos wirbeln auf nasser Straße Gischt auf. Dazu kommt ein neues Gewittersystem mit verästelten Blitzen, deren Häufigkeit sich in zehn Stufen einstellen lässt. Mit der Mod AudioXL folgt jedem Blitz passend zur Entfernung ein Donner. Für lichtempfindliche Spieler gibt es die Option Reduce Flashes, die das Flackern durch ein langsames Aufleuchten ersetzt und die Zahl der Blitze halbiert. Torrent funktioniert mit Nova City 2 und anderen Wetter-Mods. Angaben zur Leistung auf schwächeren PCs nennen die Berichte nicht. Die Mod ist ab sofort kostenlos bei Nexus Mods erhältlich.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/cyberpunk-2077-torrent-rain-weather-mod"}, "weitere_links": [], "tags": ["Cyberpunk 2077", "Mod", "Night City", "Grafik", "Nexus Mods"], "img_prompt": "Cinematic original illustration of a rainy futuristic Asian-American megacity street at night seen from a low angle near the wet asphalt: an original-design courier in a weathered rain jacket sprinting across the street through heavy individual 3D raindrops, a car passing behind throwing tyre spray, a branching lightning bolt over the skyline, warm sodium street lamps and car headlights reflecting in puddles against cool blue storm light, rich natural colors, muted magenta accent from a distant sign (unreadable, no letters). No copies of known game characters or locations, no text, no logos, no UI.", "bild": {"datei": "assets/img/news/2026-11-15-cyberpunk-torrent-regen-mod.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.402Z"}, "id": "2026-11-15-dawn-of-war-4-systemanforderungen", "datum": "2026-11-15T18:30:00+01:00", "label": "News", "bereich": "games", "themen": ["PC-Spiele"], "kategorie": "Spiele", "titel": "Warhammer 40.000: Dawn of War 4 – Systemanforderungen veröffentlicht, empfohlen sind 32 GB RAM und 125 GB auf einer NVMe-SSD", "schlagzeile": "Dawn of War 4 will 32 GB RAM und 125 GB SSD – mitten in der RAM-Krise", "kurz": "King Art und Deep Silver haben die PC-Anforderungen für Dawn of War 4 veröffentlicht. Bei CPU und Grafikkarte ist das Strategiespiel genügsam, beim Speicher nicht: Empfohlen sind 32 GB RAM und 125 GB auf einer NVMe-SSD. Das Spiel erscheint am 3. Dezember.", "zusammenfassung": "Kurz vor dem Start von Warhammer 40.000: Dawn of War 4 haben Entwickler King Art und Publisher Deep Silver die PC-Systemanforderungen genannt, berichtet PC Games Hardware. Als Minimum reichen ein Core i5-10600K oder Ryzen 5 2600X, eine GeForce GTX 1660 oder Radeon RX 5700 und 16 GB RAM. Empfohlen werden ein Core i7-12700 oder Ryzen 5 7600X, eine GeForce RTX 3060 Ti oder Radeon RX 9060 mit 8 GB und 32 GB Arbeitsspeicher. In beiden Fällen braucht das Spiel 125 GB auf einer NVMe-SSD; laut King Art sind davon rund 25 GB Puffer für DLCs und Updates. Für welche Auflösung und Bildrate die Angaben gelten, ist nicht bekannt. Offiziell steht Windows 11 auch bei den Mindestanforderungen, in einem Steam-Beitrag stellten die Entwickler aber klar, dass das Spiel auch unter Windows 10 in 64 Bit läuft. Weil Microsoft den Support für Windows 10 beendet hat, kann King Art die Kompatibilität mit künftigen Updates dort aber nicht garantieren. Die hohen Speicherempfehlungen fallen in eine Zeit, in der Arbeitsspeicher deutlich teurer geworden ist. Wer nicht installieren will, kann Dawn of War 4 auch über GeForce Now streamen. Das Spiel kostet auf Steam 59,99 Euro, die Commander Edition mit der Year-1-Erweiterung 89,99 Euro, Vorbesteller bekommen zehn Prozent Rabatt. Nvidia hat mit dem GeForce-Treiber 621.24 bereits einen Game-Ready-Treiber für das Spiel veröffentlicht.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Warhammer-40000-Dawn-of-War-4-Spiel-78930/News/Systemanforderungen-32-GB-RAM-125-GB-SSD-1560033/"}, "weitere_links": [], "tags": ["Dawn of War 4", "Warhammer 40.000", "Systemanforderungen", "RAM", "Strategie", "King Art"], "img_prompt": "Dynamic original sci-fi battle illustration, low close camera angle on a ruined industrial plain: a squad of heavily armored original-design futuristic infantry soldiers in bulky weathered ceramic-and-steel armor advancing through smoke and flying debris, one kneeling in cover behind broken concrete while firing a plausible heavy rifle, a massive original walker-tank silhouette looming through dust behind them, strong diagonals, warm late-afternoon sunlight cutting through smoke with a cool blue shadow contrast, rich natural colors, muted brass accent on armor trims. No copies of known Warhammer designs, no skulls or iconic emblems, no text, no logos, no UI.", "bild": {"datei": "assets/img/news/2026-11-15-dawn-of-war-4-systemanforderungen.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-16T10:02:21.126Z"}, "id": "2026-11-16-madden-gta6-nicht-loeschen", "datum": "2026-11-15T18:22:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "EA blendet in Madden NFL 27 ein „Don't Delete!“-Pop-up im Vice-City-Look ein und kündigt ein Update für den 17. November an, zwei Tage vor GTA 6", "schlagzeile": "„Nicht löschen!“: Madden 27 kämpft kurz vor GTA 6 um seinen Speicherplatz", "kurz": "EA zeigt in Madden NFL 27 ein neues Pop-up mit der Botschaft „Don't Delete!“ und kündigt ein Update für den 17. November an. GTA 6 nennt EA nicht, Palmen und Pink-Lila-Farben erinnern aber stark an Vice City. GTA 6 braucht über 200 GB und erscheint zwei Tage später.", "zusammenfassung": "Spieler entdeckten die Einblendung am Wochenende, CharlieIntel machte sie bekannt, IGN berichtet. Darin heißt es sinngemäß, eine Crew bereite einen großen Coup vor und man solle das Signal eines Insiders am 17. November abwarten. An diesem Dienstag soll ein neues Update für Madden NFL 27 erscheinen. EA erwähnt GTA 6 nicht ausdrücklich, Gestaltung und Wortwahl spielen aber deutlich auf das Rockstar-Spiel an. Der offizielle Madden-Account auf X hatte schon am 10. November für ein Update am 18. November mit dem Satz geworben, 210 GB sollten nicht zwischen Spieler und ihre Liga kommen. Hintergrund: GTA 6 braucht je nach Konsole über 200 GB, viele Spieler müssen dafür andere Spiele löschen. In frühen Screenshots stand im Pop-up zudem der Tippfehler „awating signal“, der offenbar schnell behoben wurde. In sozialen Netzwerken reagieren viele Spieler belustigt. GTA 6 erscheint am 19. November für PS5 und Xbox Series X|S.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/ea-adds-dont-delete-message-to-madden-nfl-27-in-bid-to-keep-players-from-making-room-ahead-of-gta-6"}, "weitere_links": [], "tags": ["Madden NFL 27", "EA", "GTA 6", "Speicherplatz", "Update"], "img_prompt": "Dynamic original sports-action illustration: an original-design American football running back in a plain unmarked jersey and helmet bursting through a tackle on a stadium field at golden hour, low close camera, strong diagonal motion, turf and dust flying, in the background a huge sunset sky in warm pink and purple tones with silhouettes of palm trees beyond the stadium rim, rich natural colors, muted teal accent on the jersey. Original characters only, no team logos, no numbers, no text, no UI.", "bild": {"datei": "assets/img/news/2026-11-16-madden-gta6-nicht-loeschen.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.489Z"}, "id": "2026-11-15-kongress-ki-chip-exporte", "datum": "2026-11-15T17:07:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia", "GPU"], "kategorie": "Wirtschaft", "titel": "US-Kongress treibt nach dem Megaspeed-Fall parteiübergreifend strengere Exportkontrollen für KI-Chips voran, Teile könnten ins Verteidigungsgesetz NDAA wandern", "schlagzeile": "Nach Megaspeed-Affäre: US-Kongress will KI-Chip-Exporte strenger regeln", "kurz": "Demokraten und Republikaner wollen den Export leistungsfähiger KI-Chips schärfer kontrollieren, berichtet ComputerBase unter Berufung auf die Financial Times. Einige Vorhaben könnten in das jährliche US-Verteidigungsgesetz aufgenommen werden. Ob das vor Jahresende klappt, ist offen.", "zusammenfassung": "Der Fall rund um den Nvidia-Kunden Megaspeed aus Singapur bringt Bewegung in die US-Exportpolitik. Laut ComputerBase, das sich auf die Financial Times stützt, bekommen mehrere Gesetzesvorhaben zur Kontrolle von KI-Chips im Kongress Unterstützung aus beiden Parteien. Sie sollen Verkäufe ins Ausland begrenzen und dem Kongress mehr Mitsprache bei bereits genehmigten Geschäften geben. US-Behörden prüfen seit über einem Jahr, ob Megaspeed Nvidia-Chips nach China weitergeleitet hat. Ein Vorschlag, der Remote Access Security Act, soll chinesischen Firmen den Fernzugriff auf KI-Beschleuniger in ausländischen Rechenzentren erschweren, wenn sie diese Chips selbst nicht kaufen dürfen. Einige Vorhaben könnten in das jährliche Verteidigungsgesetz NDAA aufgenommen werden, das als kaum zu blockieren gilt. Abgeordnete verlangen außerdem von Handelsminister Howard Lutnick eine Erklärung, warum Nvidia an Megaspeed liefern durfte. Laut Financial Times kamen die Vorhaben schon vorher voran, der Megaspeed-Fall habe ihre Chancen aber deutlich erhöht. Unklar ist, ob dem Kongress vor Jahresende genug Zeit bleibt. Für Gaming-Grafikkarten gibt es bisher keine bekannten direkten Folgen. Die Debatte trifft Nvidia aber in einer heiklen Phase: Am 17. November legt der Konzern seine Quartalszahlen vor.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/nvidia-us-kongress-will-ki-chip-exporte-schaerfer-kontrollieren.100340/"}, "weitere_links": [], "tags": ["Nvidia", "Exportkontrollen", "KI-Chips", "USA", "China", "Megaspeed"], "img_prompt": "Documentary photo: a row of rack-mounted AI servers in a data center aisle with green status LEDs, in the foreground a closed wooden shipping crate with a metal customs seal and a blank paper shipping label on a loading cart, warm sunlight falling in from an open loading-bay door mixed with cool server-room light, natural rich colors, muted brick-red accent from the crate straps, shallow depth of field. No text, no logos, no flags, no people's faces.", "bild": {"datei": "assets/img/news/2026-11-15-kongress-ki-chip-exporte.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.576Z"}, "id": "2026-11-15-playstation-black-friday-zubehoer", "datum": "2026-11-15T16:56:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen", "titel": "PlayStation Black Friday ab 16. November: Rabatte auf DualSense, Pulse-Headsets, PS VR2 und Spiele, aber keine Preissenkung für PS5 und PS5 Pro", "schlagzeile": "PlayStation Black Friday: Rabatt auf Controller und PS VR2, nicht auf die PS5", "kurz": "Sonys Black-Friday-Aktion startet in der Nacht auf Montag um Mitternacht Ortszeit und läuft bis Ende November. Rabatte gibt es auf DualSense-Controller, Headsets, PS VR2 und Spiele, die PS5 selbst wird nicht günstiger. Die Euro-Preise nennt Sony noch nicht.", "zusammenfassung": "Sony hat die Details seiner Black-Friday-Aktion bekanntgegeben, die am 16. November um Mitternacht Ortszeit startet und bis zum 30. November läuft. Im PlayStation-Blog nennt Sony US-Rabatte: 20 Dollar auf den DualSense, 30 Dollar auf den DualSense Edge, 40 Dollar auf das Pulse-Elite-Headset, 30 Dollar auf die Pulse-Explore-Ohrhörer, 30 Dollar auf den Access-Controller und 100 Dollar auf PS VR2. Laut Polygon kostet der DualSense damit in den USA 54 Dollar und PS VR2 299 Dollar. Die PS5 und die PS5 Pro selbst bekommen keinen offiziellen Rabatt, anders als im Vorjahr mit einem vergünstigten Bundle, wie Push Square anmerkt. Reduziert werden außerdem Spiele wie Marvel's Wolverine, Saros, Ghost of Yōtei Complete Edition und Marvel Tōkon: Fighting Souls, im PlayStation Store gibt es bis zu 75 Prozent Rabatt auf PS5- und PS4-Spiele. Laut Push Square bekommen PS-Plus-Mitglieder unter anderem in Deutschland und Österreich beim Kauf über PlayStation Direct zusätzlich fünf Prozent auf den Aktionspreis. Für neue PS-Plus-Mitglieder und Upgrades auf Premium oder Deluxe gibt es ebenfalls Angebote. Die Preise in Euro und die genauen Laufzeiten einzelner Angebote veröffentlicht Sony erst zum Start auf der regionalen Black-Friday-Seite, sie können sich je nach Land und Händler unterscheiden. Der 27-Zoll-Monitor mit Ladehaken ist nur in den USA und Japan erhältlich.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/playstation-black-friday-hardware-deals/"}, "weitere_links": [{"name": "PlayStation.Blog", "url": "https://blog.playstation.com/2026/11/03/playstations-black-friday-deals-2026/"}, {"name": "Push Square", "url": "https://www.pushsquare.com/news/2026/11/playstation-black-friday-sale-knocks-up-to-usd100-off-ps5-accessories-psvr2"}, {"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2121923744369160304"}], "tags": ["PlayStation", "Black Friday", "DualSense", "PS VR2", "PS5", "Angebote"], "img_prompt": "Documentary photo of a living room in late afternoon: two unbranded white-and-black wireless game controllers and a wireless gaming headset lying on a wooden coffee table next to a plain brown shipping box with tissue paper, a white virtual-reality headset half out of its unbranded box, warm golden window light, natural rich colors, muted mustard-yellow accent from a throw pillow, shallow depth of field. No text, no logos, no price tags with numbers.", "bild": {"datei": "assets/img/news/2026-11-15-playstation-black-friday-zubehoer.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.661Z"}, "id": "2026-11-15-rtx4090ti-es-china", "datum": "2026-11-15T16:49:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Grafikkarten", "titel": "Mutmaßliches Engineering Sample der nie erschienenen GeForce RTX 4090 Ti mit 18.176 CUDA-Kernen auf chinesischem Marktplatz angeboten", "schlagzeile": "Leak: Nie erschienene RTX 4090 Ti soll in China zum Verkauf stehen", "kurz": "Auf einem chinesischen Gebrauchtmarktplatz wird laut VideoCardz ein Vorserienmodell der RTX 4090 Ti angeboten. Der Verkäufer nennt 18.176 CUDA-Kerne, rund elf Prozent mehr als bei der RTX 4090. Unabhängig geprüft sind diese Angaben nicht.", "zusammenfassung": "Nvidia hat die GeForce RTX 4090 Ti nie auf den Markt gebracht, doch immer wieder tauchen Prototypen davon auf. Jetzt ist laut VideoCardz ein weiteres mutmaßliches Engineering Sample auf einem chinesischen Gebrauchtmarktplatz gelistet. Entdeckt hat das Angebot der X-Nutzer @meiei_nowa, UNIKO's Hardware hat weitere Fotos veröffentlicht. Laut Verkäufer hat die Karte 18.176 CUDA-Kerne, 192 ROPs und 568 TMUs. Das passt zu den Gerüchten, die vor Jahren über die RTX 4090 Ti kursierten, und entspricht etwa elf Prozent mehr Shadern als bei der normalen RTX 4090 mit 16.384 Kernen. Dieselbe Kernzahl hat auch die Profikarte RTX 6000 Ada Generation. Der Vollausbau des AD102-Chips mit 18.432 Kernen steckte dagegen nur im nie erschienenen TITAN-Ada-Prototyp, den der Übertakter der8auer getestet hat. Der Verkäufer gibt an, dass die Karte einen internen Nvidia-Treiber braucht, im Test aber ohne erkennbare Probleme lief. Frühere RTX-4090-Ti-Muster fielen durch ein Vier-Slot-Design mit gedrehter Platine auf; ein von Gamers Nexus getestetes Exemplar lief allerdings nur mit normalen RTX-4090-Daten. Warum Nvidia die Karte gestrichen hat, wurde nie offiziell erklärt. Ob es sich wirklich um eine RTX 4090 Ti handelt, lässt sich aus dem Angebot allein nicht belegen.", "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Fotos und Daten stammen aus einem Verkaufsangebot; die Angaben des Verkäufers sind nicht unabhängig geprüft. Die Kernzahl deckt sich mit älteren Gerüchten zur RTX 4090 Ti. Nvidia äußert sich nicht."}, "ursprungsquelle": "Verkaufsangebot auf einem chinesischen Gebrauchtmarktplatz, entdeckt von @meiei_nowa auf X, Fotos von UNIKO's Hardware", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/nvidia-geforce-rtx-4090-ti-engineering-sample-with-18176-cuda-cores-surfaces-in-china"}, "weitere_links": [], "tags": ["RTX 4090 Ti", "Nvidia", "AD102", "Engineering Sample", "Prototyp"], "img_prompt": "Documentary photo: an unbranded oversized four-slot prototype graphics card with a plain dark metal shroud and three visible axial fans lying on a worn wooden workbench, the PCIe gold contacts only along one long bottom edge, the slot bracket on one short end, a small paper tag on a string attached (blank), a jeweller's loupe and a padded shipping envelope next to it, warm late-morning window light, natural rich colors, muted olive-green accent from a cutting mat, shallow depth of field. No text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-15-rtx4090ti-es-china.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.747Z"}, "id": "2026-11-15-game-awards-nominierungen-gta6", "datum": "2026-11-15T16:30:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "The Game Awards geben am 17. November die Nominierten bekannt, GTA 6 ist trotz Release am 19. November teilnahmeberechtigt", "schlagzeile": "Game Awards: Nominierte kommen am Dienstag – GTA 6 darf noch mitspielen", "kurz": "Die Nominierten der Game Awards 2026 werden am Dienstag um 18 Uhr unserer Zeit in einem Livestream verkündet. GTA 6 erscheint erst zwei Tage später, ist nach den offiziellen Regeln aber trotzdem zugelassen. Die Show selbst steigt am 10. Dezember in Los Angeles.", "zusammenfassung": "Geoff Keighley stellt die Nominierten der Game Awards 2026 am Dienstag in einem eigenen Livestream auf YouTube und Twitch vor. Los geht es um 18 Uhr mitteleuropäischer Zeit, in früheren Jahren dauerte die Sendung nur rund zehn Minuten. Vergeben werden Preise in mehr als 30 Kategorien, die Kandidaten für das Spiel des Jahres kommen traditionell zum Schluss. Spannend ist das wegen GTA 6, das erst zwei Tage später für PS5 und Xbox Series X|S erscheint. Laut dem offiziellen Regelwerk, das Polygon zitiert, reicht es für die Hauptkategorien, wenn ein Spiel bis Freitag um 21 Uhr pazifischer Zeit erhältlich ist. GTA 6 rutscht damit noch durch, eine Nominierung ist damit aber nicht garantiert. Für den Publikumspreis Players' Voice gilt sogar das Monatsende als Stichtag. Über die Nominierungen entscheidet eine Jury aus über 100 Medien und Creator-Organisationen, die Gewinner werden laut PC Games zu 90 Prozent von der Jury und zu 10 Prozent per Fan-Abstimmung bestimmt. Ob Rockstar der Jury vorab Spielcodes geschickt hat, ist nicht bekannt. Einen ähnlichen Fall gab es 2014, als das Wii-U-Smash-Bros kurz vor dem US-Start nominiert wurde. Die Preisverleihung findet am 10. Dezember im Peacock Theater in Los Angeles statt, nach unserer Zeit in der Nacht auf den 11. Dezember.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/GTA-6-Spiel-55239/News/game-awards-2026-nominierung-vor-release-1560030/"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/the-game-awards-2026-nominees-announcement-date/"}], "tags": ["The Game Awards", "GTA 6", "Spiel des Jahres", "Rockstar", "Geoff Keighley"], "img_prompt": "Documentary photo inside an empty theater shortly before an awards show rehearsal: a wide stage with warm golden spotlights, a single unmarked golden statuette-shaped trophy on a pedestal in sharp focus in the foreground, rows of red velvet seats softly out of focus, a technician on a ladder in the far background, natural rich colors, muted teal accent from stage curtains, cinematic but realistic. No text, no logos, no screens with content, no recognizable people.", "bild": {"datei": "assets/img/news/2026-11-15-game-awards-nominierungen-gta6.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.833Z"}, "id": "2026-11-15-phishing-microsoft-365-ausfall", "datum": "2026-11-15T14:59:00+01:00", "label": "News", "bereich": "software", "themen": ["Sicherheit", "Microsoft 365"], "kategorie": "Sicherheit", "titel": "Microsoft warnt vor Phishing-Kampagne, die gefälschte Störungsmeldungen zum Microsoft-365-Ausfall verschickt", "schlagzeile": "Phishing-Welle nutzt Microsoft-365-Ausfall – Microsoft warnt", "kurz": "Kriminelle nutzen den Microsoft-365-Ausfall dieser Woche für Phishing, warnt Microsofts Threat-Intelligence-Team. Gefälschte Störungsmeldungen behaupten, zurückgehaltene Mails würden gelöscht, wenn man nicht auf einen Link klickt. Echte Störungsinfos gibt es nur im Microsoft 365 Admin Center.", "zusammenfassung": "Nur kurz nach dem großen Ausfall von Microsofts Cloud-Diensten tauchen Phishing-Mails dazu auf, berichtet heise online. Microsofts Threat-Intelligence-Team warnt auf Bluesky vor einer Kampagne, die Statusmeldungen zu Microsoft 365 nachahmt. Die Mails beziehen sich auf den echten Exchange-Online-Vorfall mit der Kennung EX1550543. Einige der Nachrichten, die Microsoft am Freitag entdeckt hat, behaupten, während des Ausfalls seien E-Mails zurückgehalten worden und würden binnen 24 Stunden gelöscht, wenn man sie nicht per Link wiederherstellt. Die Betreffzeilen folgen oft dem Muster „Outage“ plus sechsstelliger Code, als Absendername dienen Bezeichnungen wie „Outage Notification“ oder „Service Health“. Laut Microsoft kommen die Mails von drei Domains, die Klick-Links leiten über SendGrid auf eine weitere Seite weiter. Bisher richtete sich die Kampagne an Organisationen verschiedener Branchen in den USA. Das Muster entspricht typischem Zugangsdaten-Phishing; dass tatsächlich Passwörter abgegriffen oder Schadsoftware verteilt wurde, konnte Microsoft aber noch nicht bestätigen. Microsoft Defender blockiert die genutzten Domains, Defender for Office 365 schiebt solche Mails in Quarantäne. Admins sollen ihre Safe-Links-Richtlinien prüfen und Störungsmeldungen nur im Microsoft 365 Admin Center nachlesen. Für alle gilt: Bei Mails mit Löschdrohung und Zeitdruck nicht auf Links klicken.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Phishing-Kampagne-nutzt-Microsoft-Cloud-Ausfall-11525471.html"}, "weitere_links": [], "tags": ["Phishing", "Microsoft 365", "Exchange Online", "Sicherheit", "Microsoft Defender"], "img_prompt": "Documentary photo of an office desk in warm late-afternoon light: a laptop with a blurred unreadable email inbox on screen, a hand hovering over the touchpad hesitating, a smartphone showing an unreadable notification beside it, a coffee cup and a sticky note (blank), natural rich colors, muted orange accent from a desk lamp shade, shallow depth of field. No readable text, no logos, no brand names.", "bild": {"datei": "assets/img/news/2026-11-15-phishing-microsoft-365-ausfall.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T18:43:51.921Z"}, "id": "2026-11-15-dawnwalker-1-2-new-game-plus", "datum": "2026-11-15T11:00:00+01:00", "label": "News", "bereich": "games", "themen": ["PC-Spiele"], "kategorie": "Spiele", "titel": "The Blood of Dawnwalker: Update 1.2 bringt in der Woche ab 16. November New Game Plus, Stufenobergrenze 100 und Balance-Änderungen", "schlagzeile": "Blood of Dawnwalker: New Game Plus und Stufe 100 kommen diese Woche", "kurz": "Rebel Wolves liefert mit Update 1.2 für The Blood of Dawnwalker das meistgewünschte Feature nach: New Game Plus. Dazu steigt die Stufenobergrenze auf 100. Das Update soll im Lauf dieser Woche erscheinen, einen genauen Tag gibt es noch nicht.", "zusammenfassung": "Das polnische Studio Rebel Wolves, gegründet von früheren Witcher-Entwicklern, hat Update 1.2 für sein Vampir-Rollenspiel The Blood of Dawnwalker angekündigt. Es soll in der Woche ab dem 16. November erscheinen, einen genauen Termin nennt das Studio nicht. Wichtigste Neuerung ist ein New-Game-Plus-Modus, der nach dem Epilog freigeschaltet wird. Stufe, Fähigkeiten und Inventar werden in den neuen Durchgang übernommen. Die Stufenobergrenze steigt auf 100, Gegner werden in allen Regionen einheitlich skaliert, und Gegenstände bekommen eigene New-Game-Plus-Versionen mit angepassten Werten. Auch ohne New Game Plus ändert das Update einiges: Rebel Wolves passt die Lebenspunkte der Gegner und die Häufigkeit ihrer Spezialfähigkeiten an. Außerdem wird Geländegeometrie überarbeitet, damit Bewegung im Kampf und beim Erkunden flüssiger klappt. Besitzer der Eclipse Edition bekommen zusätzliche Songs im Spiel-Soundtrack, der später auch bei Spotify und anderen Streamingdiensten erscheinen soll. Vollständige Patch Notes gibt es noch nicht, genaue Zahlen zu den Balance-Änderungen fehlen daher. Offen ist auch, ob New Game Plus mehrfach hintereinander gespielt werden kann. Bei den Golden Joystick Awards landete das Spiel diese Woche laut GamesRadar+ in zwei Kategorien auf Platz zwei.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/The-Blood-of-Dawnwalker-Spiel-75056/News/New-Game-Plus-angekuendigt-1560015/"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/blood-of-dawnwalker-update-new-game-plus-announced/"}, {"name": "GamesRadar+", "url": "https://www.gamesradar.com/games/rpg/the-blood-of-dawnwalker-is-getting-new-game-next-week-with-patch-bringing-the-level-cap-for-the-ex-witcher-devs-vampire-rpg-up-to-100/"}], "tags": ["The Blood of Dawnwalker", "Rebel Wolves", "Patch", "New Game Plus", "Rollenspiel"], "img_prompt": "Dynamic original dark-fantasy action illustration in a medieval Central European mountain village at dusk: an original-design hooded swordsman in a worn leather coat lunging forward with a plausible longsword against a pale feral vampire-like creature leaping from a broken wooden fence, low close camera, strong diagonal motion, mud and splinters flying, warm golden lantern and sunset light against cool blue mountain shadows, rich natural colors, muted crimson accent on a scarf. Original characters only, no copies of known game characters, no gore, no text, no logos, no UI.", "bild": {"datei": "assets/img/news/2026-11-15-dawnwalker-1-2-new-game-plus.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.403Z"}, "id": "2026-11-15-gta6-album-tracklist-leak", "datum": "2026-11-15T05:52:00+01:00", "label": "Leak", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Tracklist des offiziellen GTA-6-Albums vor Release per Video geleakt; Rolling Stone und Billboard halten die Liste laut eigenen Quellen für echt", "schlagzeile": "Leak: Lana Del Rey, Dua Lipa, Jennie – ist das die GTA-6-Tracklist?", "kurz": "Ein Video aus einem Laden zeigt offenbar die Vinyl-Ausgabe von „Grand Theft Auto VI: The Album“ samt kompletter Tracklist. Laut PC Gamer bestätigen Quellen von Rolling Stone und Billboard die Liste. Rockstar selbst hat sich nicht geäußert.", "zusammenfassung": "Wenige Tage vor dem Start von GTA 6 ist offenbar die Tracklist des offiziellen Albums durchgesickert. Laut IGN zeigt ein in sozialen Medien geteiltes Video aus einem Geschäft Vorder- und Rückseite der Doppel-LP „Grand Theft Auto VI: The Album“, die eigentlich erst am 19. November für rund 50 Dollar erscheinen soll. Laut Insider Gaming umfasst das Album 34 Titel. Genannt werden unter anderem Lana Del Rey mit dem bisher unveröffentlichten Song „Crazy For You“, Dua Lipa und Jennie von Blackpink; PC Gamer nennt außerdem Playboi Carti und Keith Richards. Zu den ersten Titeln gehören zwei Songs des französischen Duos Justice, eines mit Michael McDonald und eines mit Tame Impala, SZA und King Gizzard & the Lizard Wizard. Laut PC Gamer haben Quellen von Rolling Stone und Billboard die Liste als korrekt bezeichnet. Rockstar Games und Take-Two haben die Tracklist nicht bestätigt; nach unseren Regeln gilt sie daher weiter als Leak. Wichtig: Das Album ist nicht der komplette Soundtrack des Spiels. Die Radiosender im Spiel enthalten zusätzlich lizenzierte Songs, und die Filmmusik von Justice erscheint laut IGN separat am 11. Dezember. GTA 6 erscheint am 19. November für PS5 und Xbox Series X|S, einen PC-Termin gibt es weiterhin nicht.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/grand-theft-auto/gta-6-soundtrack-leak-confirmed-accurate-with-new-songs-from-lana-del-rey-playboi-carti-and-keith-richards/"}, "weitere_links": [{"name": "IGN", "url": "https://www.ign.com/articles/gta-6-leak-seemingly-reveals-full-track-list-days-before-launch"}, {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/gta-6-album-leak-lists-dua-lipa-jennie-and-lana-del-rey/"}], "ursprungsquelle": "Video eines Nutzers in sozialen Medien (Ladengeschäft mit Vorab-Exemplaren der Vinyl)", "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Video zeigt offenbar das physische Produkt; laut PC Gamer bestätigen Quellen von Rolling Stone und Billboard die Liste. Rockstar/Take-Two haben nicht bestätigt, daher nach GTA-Regel kein offizieller Stand."}, "tags": ["GTA 6", "Soundtrack", "Lana Del Rey", "Dua Lipa", "Justice", "Rockstar Games"], "img_prompt": "Cinematic photo: a vintage convertible cruising along a palm-lined coastal boulevard at golden hour, warm sunset light, a vinyl record sleeve without any print lying on the passenger seat in the foreground, natural rich colors, muted coral-pink accent, dynamic low angle with slight motion blur. Generic car, no real persons in focus, no text, no logos, no game characters.", "bild": {"datei": "assets/img/news/2026-11-15-gta6-album-tracklist-leak.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.842Z"}, "id": "2026-11-15-ubuntu-pro-ki-sicherheitspatches", "datum": "2026-11-15T02:55:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit"], "kategorie": "Betriebssysteme", "titel": "Canonical startet Edge-Archiv: Ubuntu-Pro-Nutzer können KI-erzeugte Sicherheitspatches vor der regulären Prüfung testen", "schlagzeile": "Ubuntu testet KI-Sicherheitspatches – wer will, bekommt sie früher", "kurz": "Canonical bietet Ubuntu-Pro-Nutzern ein neues, freiwilliges Paketarchiv namens Edge an. Darin landen Sicherheitskorrekturen, die ein KI-System namens Surge erstellt, bevor sie vollständig geprüft sind. Die normalen Updates bleiben laut Canonical weiterhin von Menschen geprüft.", "zusammenfassung": "Canonical lässt Sicherheitslücken in Ubuntu jetzt teilweise von KI-Agenten flicken. Laut OMG! Ubuntu hat das Unternehmen ein System aus mehreren KI-Agenten namens Surge gebaut, das Korrekturen für bekannte Lücken in Userspace-Paketen auf ältere Versionen zurückportiert. Diese maschinell erzeugten Patches landen in einem neuen Archiv namens Edge. Das Archiv ist freiwillig und standardmäßig aus; wer es nutzen will, muss es auf seinem System selbst aktivieren. Den Linux-Kernel patcht Surge nicht. Die regulären Ubuntu-Updates sollen laut Canonical weiterhin wie bisher von Menschen geprüft und getestet werden, Surge-Fixes wandern nicht automatisch in die stabilen Versionen. Als Grund nennt Canonical die stark gestiegene Zahl an Lückenmeldungen, die mit Hilfe von Sprachmodellen gefunden werden, sowie Angriffe mit KI-Agenten; das Sicherheitsteam habe schon doppelt so viele Fixes ausgeliefert wie im Vorjahr. Nutzer des Edge-Archivs sollen helfen, die KI-Patches im Alltag zu prüfen, bevor sie allgemein freigegeben werden. Ubuntu Pro ist für Privatleute auf bis zu fünf Geräten kostenlos, Edge steht für Ubuntu 18.04 bis 26.04 LTS bereit. Updates daraus werden standardmäßig nicht automatisch installiert. Ein Risiko bleibt: Ungeprüfte Patches können Fehler enthalten, deshalb ist Edge eher etwas für Tester als für Produktivsysteme.", "quelle": {"name": "OMG! Ubuntu", "url": "https://www.omgubuntu.co.uk/2026/11/ubuntu-pro-ai-security-archive"}, "weitere_links": [], "tags": ["Ubuntu", "Canonical", "Ubuntu Pro", "Sicherheit", "KI", "Linux"], "img_prompt": "Documentary photo: a laptop on a wooden desk showing a blurred unreadable terminal window, a small home server box with blinking status LEDs beside it, a cup of coffee, warm late-morning window light, natural rich colors, muted terracotta accent from a notebook cover, shallow depth of field. No readable text on screen, no logos.", "bild": {"datei": "assets/img/news/2026-11-15-ubuntu-pro-ki-sicherheitspatches.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.567Z"}, "id": "2026-11-15-lol-new-dawn-blg-weltmeister", "datum": "2026-11-14T23:05:00+01:00", "label": "News", "bereich": "games", "themen": ["League of Legends"], "kategorie": "Spiele", "titel": "Riot kündigt beim Worlds-Finale „League of Legends: New Dawn“ an, die größte Überarbeitung des Spiels seit 2009; BLG wird Weltmeister", "schlagzeile": "League of Legends wird 2027 rundum erneuert – BLG holt den WM-Titel", "kurz": "Riot Games hat beim Finale der LoL-Weltmeisterschaft „New Dawn“ vorgestellt, ein großes Update für 2027. Client, Summoner's Rift, Grafik und Gameplay sollen sich deutlich ändern. Das Finale selbst gewann Bilibili Gaming mit 3:1 gegen Gen.G.", "zusammenfassung": "Beim Finale der League-of-Legends-Weltmeisterschaft 2026 in Brooklyn hat Riot Games „League of Legends: New Dawn“ angekündigt. Laut IGN handelt es sich um ein umfassendes Update, das 2027 erscheinen und Client, Summoner's Rift, Optik und Gameplay verändern soll. Executive Producer Paul Bellezza sprach im ersten Trailer vom Beginn einer neuen Ära für League. Der Trailer zeigt unter anderem eine neu gestaltete Championauswahl, die an das Mobilspiel Wild Rift erinnert, sowie überarbeitete Vasallen, Drachen und Baron Nashor. Außerdem deuten die Szenen auf ein neues oder stark umgebautes Runensystem und größere Änderungen am Kartengelände hin. Was genau sich am Gameplay ändert, verrät Riot noch nicht; die vollständige Präsentation ist für Januar 2027 geplant. Seit dem Start 2009 gab es zwar mehrere große Umbauten, etwa die neue Karte 2014, aber nichts in dieser Größenordnung. GameStar spricht deshalb schon von einem „League of Legends 2“, Riot selbst nennt es ein Update. Ob die Spielerschaft die Änderungen annimmt, ist offen. Sportlich holte Bilibili Gaming aus China den Titel: Laut Insider Gaming schlug BLG Gen.G im Finale mit 3:1. Midlaner Knight wurde zum wertvollsten Spieler des Turniers gekürt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/league-of-legends-new-dawn-unveiled-with-debut-trailer-riot-announces-major-overhaul-coming-in-2027"}, "weitere_links": [{"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/blg-wins-lol-worlds-2026-and-first-summoners-cup/"}, {"name": "IGN Deutschland", "url": "https://de.ign.com/league-of-legends/157272/league-of-legends-new-dawn-wird-mit-einem-ersten-trailer-vorgestellt-riot-kundigt-fur-2027-eine-umfa"}], "tags": ["League of Legends", "New Dawn", "Riot Games", "Worlds 2026", "BLG", "E-Sport"], "img_prompt": "Dynamic cinematic fantasy action scene: an original armored warrior with a glowing-free steel greatsword and an original hooded mage casting a swirl of natural fire and wind charge across a misty jungle river crossing toward a huge original stone-scaled beast, low dramatic perspective, strong diagonals, flying water spray and leaves, warm golden morning sun breaking through the canopy with cool blue shadows, natural rich colors, muted violet accent. Original designs only, no known game characters, no text, no logos, no UI.", "bild": {"datei": "assets/img/news/2026-11-15-lol-new-dawn-blg-weltmeister.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.293Z"}, "id": "2026-11-15-zephyr-4070tis-ein-luefter", "datum": "2026-11-14T22:45:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU"], "kategorie": "Grafikkarten", "titel": "Zephyr bringt die RTX 4070 Ti Super Sakura Snow X mit nur einem Lüfter für 285 Watt nach Absage doch noch in China auf den Markt", "schlagzeile": "Ein Lüfter für 285 Watt: Mini-RTX 4070 Ti Super kommt doch noch", "kurz": "Der chinesische Hersteller Zephyr verkauft seine RTX 4070 Ti Super Sakura Snow X nun doch, nachdem das Modell im März wegen teurem GDDR6X-Speicher auf Eis lag. Laut Zephyr ist es die einzige Serienkarte dieses Typs, die 285 Watt mit nur einem Axiallüfter kühlt. Für leisen Betrieb empfiehlt der Hersteller ein Power-Limit von 220 Watt bei unter fünf Prozent Leistungsverlust.", "zusammenfassung": "Zephyr hat die Geforce RTX 4070 Ti Super Sakura Snow X nach mehreren Verschiebungen und einer zwischenzeitlichen Absage doch noch in den Handel gebracht, berichtet PC Games Hardware. Laut Hersteller ist sie die einzige seriengefertigte RTX 4070 Ti Super, die 285 Watt Board-Power mit einem einzigen Axiallüfter abführt. Dafür muss der Lüfter allerdings hoch drehen. Zephyr empfiehlt deshalb für leiseren Betrieb, das Power-Limit auf 220 Watt zu senken; dabei sollen weniger als fünf Prozent Spieleleistung verloren gehen. Welche Spiele der Hersteller dafür getestet hat, verrät er nicht. Im März 2026 hatte Zephyr das Modell wegen stark gestiegener GDDR6X-Preise vorerst gestoppt und stattdessen eine RTX 4070 Super mit 12 GB angekündigt. Die Karte steckt in einem aus einem Metallblock gefrästen Gehäuse und zielt auf kompakte PCs, in die keine Triple-Lüfter-Karte passt. Die kleine erste Charge lief über einen Händler auf Douyin und ist laut Techtesters bereits ausverkauft. Einen offiziellen Preis gibt es nicht; im Juli waren 6.199 bis 6.499 Yuan im Gespräch, umgerechnet etwa 795 bis 835 Euro vor Steuern und Zoll. Einen Marktstart in Deutschland hat Zephyr nicht angekündigt. Das 220-Watt-Limit lässt sich übrigens bei jeder RTX 4070 Ti Super selbst einstellen, etwa mit rund 77 Prozent Power-Limit in MSI Afterburner bei Referenz-TGP.", "quelle": {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Geforce-RTX-4070-Ti-Super-Grafikkarte-280115/News/Zephyr-Sakura-Snow-X-ein-Luefter-Power-Limit-220-Watt-1560011/"}, "weitere_links": [], "tags": ["RTX 4070 Ti Super", "Zephyr", "Mini-ITX", "Power-Limit", "Undervolting"], "img_prompt": "Documentary photo: a compact single-fan graphics card with a CNC-milled bare aluminium shroud and one visible axial fan, lying next to a small mini-ITX PC case on a wooden workbench, warm late-morning window light, natural rich colors, muted dusty-teal accent from a cable sleeve, shallow depth of field. No text, no logos, no brand markings.", "bild": {"datei": "assets/img/news/2026-11-15-zephyr-4070tis-ein-luefter.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.756Z"}, "id": "2026-11-15-inxile-buero-schuesse", "datum": "2026-11-14T22:03:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Studios", "titel": "Schüsse auf Bürogebäude von Xbox-Studio inXile in Kalifornien: niemand verletzt, Polizei nimmt Verdächtigen fest", "schlagzeile": "Schüsse auf Gebäude von Xbox-Studio inXile – Polizei fasst Verdächtigen", "kurz": "Auf das Bürogebäude in Tustin, Kalifornien, in dem das Xbox-Studio inXile sitzt, ist am Mittwoch geschossen worden. Verletzt wurde niemand. Die Polizei hat zwei Tage später einen Verdächtigen festgenommen, das Motiv ist noch unklar.", "zusammenfassung": "Das Bürogebäude des Microsoft-Studios inXile Entertainment in Tustin, Kalifornien, ist von Schüssen getroffen worden. Laut Insider Gaming meldeten lokale Medien den Vorfall am Nachmittag des 11. November, mehrere Kugeln trafen das Gebäude. Die Polizei sprach gegenüber dem Magazin Aftermath von einem Drive-by-Shooting und fand mehrere Patronenhülsen. Verletzt wurde niemand. Am Vormittag des 13. November nahm die Polizei einen Verdächtigen fest; Name und Motiv sind nicht bekannt, die Ermittlungen laufen. Ob das Studio gezielt angegriffen wurde, ist nicht geklärt. Ein Sprecher erklärte, man sei erleichtert, dass niemand verletzt wurde, kümmere sich um das Team und arbeite eng mit den Behörden zusammen. inXile ist für die Wasteland-Reihe bekannt und arbeitet an Clockwork Revolution, einem für 2027 geplanten Xbox-Exklusivspiel. Auswirkungen auf das Spiel hat Xbox nicht angekündigt.", "quelle": {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/inxile-building-shooting-no-injuries/"}, "weitere_links": [], "tags": ["inXile", "Xbox", "Clockwork Revolution", "Tustin"], "img_prompt": "Documentary photo: a modern low-rise office campus building in Southern California at golden hour, palm trees and a quiet parking lot, a police cruiser parked at a distance with no visible markings, warm sunlight with long cool shadows, natural rich colors, muted blue accent. No people in focus, no damage shown graphically, no text, no logos, no signage.", "bild": {"datei": "assets/img/news/2026-11-15-inxile-buero-schuesse.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-15T11:01:52.672Z"}, "id": "2026-11-15-inoffizielle-pc-ports-astro-bot-totk", "datum": "2026-11-14T21:45:00+01:00", "label": "News", "bereich": "games", "themen": ["PC-Port", "Rekompilierung"], "kategorie": "Spiele", "titel": "Inoffizielle native PC-Ports: Astro Bot läuft als erstes PS5-Exklusivspiel unter Windows, Zelda: Tears of the Kingdom sogar auf einer Geforce MX550", "schlagzeile": "Astro Bot und Zelda auf dem PC: Fan-Ports ohne Emulator legen los", "kurz": "Mit Astro Bot läuft erstmals ein PS5-exklusives Spiel als inoffizieller nativer PC-Port, inklusive DLSS und Frame Generation. Gleichzeitig zeigt ein Nutzer Zelda: Tears of the Kingdom per Rekompilierung auf einer Notebook-GPU mit nur 2 GB Speicher. Beide Projekte sind nicht von Sony oder Nintendo autorisiert.", "zusammenfassung": "Statt Konsolenspiele zu emulieren, übersetzen Fan-Projekte sie zunehmend direkt in nativen PC-Code. Laut ComputerBase gibt es nun einen solchen Port von Astro Bot, dem Spiel des Jahres 2024, für Windows. Der Entwickler nutzte nach eigenen Angaben eine PS5-Kopie des Spiels; die Grafik wird über eine Komponente aus dem Projekt KytyPS5 nach Vulkan übersetzt. Ein Zusatz bindet Nvidia DLSS, Frame Generation und Reflex ein. Mit Ryzen 5 5500 und RTX 5060 erreicht der Port in 1440p im anspruchsvollen Level Sky Garden laut Entwickler nur 32 bis 34 fps, sonst meist 40 bis 50 fps, also weniger als die 60 fps der PS5. Mit Frame Generation sind es etwas über 60 fps, mit Multi Frame Generation bis zu 128 fps. Parallel zeigt ein Reddit-Nutzer laut PC Games Hardware Zelda: Tears of the Kingdom über das Projekt TotK Recomp auf einem Notebook mit Geforce MX550 und 2 GB Grafikspeicher. Er spricht von rund 30 fps mit Einbrüchen; die Auflösung nennt er nicht. Version 0.4.0 des Ports braucht laut Release Notes auf einer Radeon RX 9070 nur noch 3,4 statt 4,8 GB VRAM. Beide Projekte sind inoffiziell und nicht von Sony oder Nintendo freigegeben, wie lange sie verfügbar bleiben, ist offen. Laut ComputerBase hoffen viele schon auf ähnliche Ports von GTA 6, das am 19. November zunächst nur für Konsolen erscheint.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/gaming/astro-bot-erstes-ps5-exklusives-spiel-mit-inoffiziellem-pc-port.100330/"}, "weitere_links": [{"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/The-Legend-of-Zelda-Tears-of-the-Kingdom-Spiel-67721/News/PC-Port-Recomp-2-GiB-VRAM-Geforce-MX550-Notebook-1560010/"}], "tags": ["Astro Bot", "Zelda", "Tears of the Kingdom", "PC-Port", "Rekompilierung", "DLSS"], "img_prompt": "Documentary photo: a gaming laptop and a small desktop PC side by side on a wooden desk at a sunny window, a generic white game controller in the foreground, screens showing a soft out-of-focus colorful cartoon landscape, warm late-morning daylight, natural rich colors, muted olive accent from a desk plant, shallow depth of field. No readable screens, no game characters, no text, no logos.", "bild": {"datei": "assets/img/news/2026-11-15-inoffizielle-pc-ports-astro-bot-totk.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.841Z"}, "id": "2026-11-14-huang-petition-musk", "datum": "2026-11-14T18:19:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia"], "kategorie": "Unternehmen", "titel": "Petition für Huangs Rückkehr an die Nvidia-Spitze: über 100.000 Unterschriften, Elon Musk unterstützt sie, intern über 1.600 Kommentare", "schlagzeile": "„Bring back the boss“: 100.000 wollen Jensen Huang zurück bei Nvidia", "kurz": "Eine öffentliche Petition für die Rückkehr von Jensen Huang zu Nvidia hat laut Golem mehr als 100.000 Unterschriften, darunter über 2.000 von aktuellen und ehemaligen Beschäftigten. Elon Musk hat auf X angekündigt, sie zu unterzeichnen. Auch im internen Forum fordern viele Mitarbeitende den Gründer zurück.", "zusammenfassung": "Wenige Tage nach dem Rücktritt von Jensen Huang formiert sich Widerstand gegen die Entscheidung des Verwaltungsrats. Eine Petition unter dem Motto „33 Jahre verdienen eine Antwort“ hatte laut Golem am Abend des 14. November mehr als 100.187 Unterschriften. Darunter sollen über 2.000 aktuelle und ehemalige Nvidia-Beschäftigte sein, prüfen lässt sich das von außen nicht. Elon Musk hatte am 13. November auf X auf die Petition hingewiesen und angekündigt, sie zu unterschreiben. Laut Wired gibt es zudem im internen Vorschlagsforum von Nvidia einen Beitrag für Huangs Rückkehr mit mehr als 1.600 Kommentaren, die meisten davon zustimmend. Heise berichtet, Interims-Chefin Colette Kress habe für den 18. November eine Betriebsversammlung angekündigt. Der Verwaltungsrat hatte Huangs Rücktritt nach Berichten über eine zweite Affäre mit einer direkt unterstellten Managerin bekanntgegeben; Reuters berichtete später von einer dritten Beziehung. Huang selbst hat sich seit seiner Mail an die Belegschaft vom Sonntag nicht mehr geäußert. Nvidia und Verwaltungsratschef Harvey Jones haben auf die Petition bisher nicht reagiert. Eine Petition hat keine rechtliche Wirkung, die Entscheidung liegt allein beim Verwaltungsrat.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/petition-nvidia-mitarbeiter-und-elon-musk-wollen-huang-zurueck-2611-215228.html"}, "weitere_links": [{"name": "heise online", "url": "https://www.heise.de/news/Nvidia-Angestellte-wollen-Jensen-Huang-zurueck-11525279.html"}, {"name": "PC Games Hardware (PCGH)", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/Elon-Musk-unterzeichnet-Petition-fuer-Rueckkehr-von-Huang-als-Nvidia-CEO-1559989/"}], "tags": ["Nvidia", "Jensen Huang", "Elon Musk", "Petition", "Colette Kress"], "bild": {"datei": "assets/img/news/2026-11-14-huang-petition-musk.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:02.016Z"}, "id": "2026-11-14-gta6-codes-fehlen-box", "datum": "2026-11-14T17:43:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Einige physische GTA-6-Ausgaben enthalten keinen lesbaren Download-Code, Händler reagieren unterschiedlich", "schlagzeile": "GTA 6 gekauft, aber kein Code in der Box? Erste Käufer melden Fehldrucke", "kurz": "Mehrere Käufer berichten, dass in ihrer physischen GTA-6-Ausgabe kein lesbarer Download-Code steckt. Statt des Codes gibt es nur einen grauen Streifen, der sich nicht freirubbeln lässt. Betroffen sind laut Polygon PlayStation- und Xbox-Fassungen, das Problem scheint aber nicht weit verbreitet zu sein.", "zusammenfassung": "GTA 6 erscheint komplett digital, auch die Box im Handel enthält keine Disc, sondern nur einen Code zum Herunterladen. Der Code steht auf der Rückseite des Covers und soll durch die durchsichtige Hülle sichtbar sein. Seit dem 12. November liefern Händler die Vorbestellungen aus, damit Käufer das Spiel vorab laden können. Laut Polygon melden nun mehrere Käufer, dass ihr Code fehlt: Statt der Zeichen gibt es nur einen grauen Streifen, der wie ein Rubbelfeld aussieht, sich aber nicht freirubbeln lässt. Das betrifft demnach sowohl PlayStation- als auch Xbox-Ausgaben. Händler reagieren unterschiedlich: Einige Best-Buy-Filialen sollen die Rücknahme verweigert haben, Amazon habe den Kaufpreis erstattet, GameStop verweise an Rockstar. Zwei Reddit-Nutzer berichten, Rockstars Support habe ihre Tickets ohne Lösung geschlossen. Rockstar hat sich öffentlich noch nicht geäußert. Polygon geht davon aus, dass nur wenige Exemplare betroffen sind. Wer eine Box gekauft hat, sollte den Code also schon vor dem Start am 19. November prüfen.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/gta-6-grand-theft-auto-no-code-physical-edition/"}, "weitere_links": [], "tags": ["GTA 6", "Rockstar", "Download-Code", "Handel"], "bild": {"datei": "assets/img/news/2026-11-14-gta6-codes-fehlen-box.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:02.184Z"}, "id": "2026-11-14-xbox-25-spiele-pc-kauf", "datum": "2026-11-14T15:45:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox", "Windows"], "kategorie": "Spiele", "titel": "Zum Xbox-Jubiläum: 25 Spiele gratis beim Kauf eines neuen Windows-PCs, aber nur in den USA", "schlagzeile": "25 Xbox-Spiele gratis – aber nur zum neuen PC und nur in den USA", "kurz": "Microsoft feiert 25 Jahre Xbox mit einem Paket aus 25 PC-Spielen, darunter Skyrim, Halo: Combat Evolved Anniversary und Gears of War: Reloaded. Es gibt sie nur beim Kauf eines qualifizierten neuen Windows-PCs bis Ende 2026, gezählt wird ab Anfang November. Die Aktion gilt ausschließlich in den USA.", "zusammenfassung": "Xbox-Chefin Asha Sharma hat auf X das „25 Years of Xbox Bundle“ vorgestellt. Wer einen qualifizierten neuen Windows-PC kauft und aktiviert, bekommt laut Microsofts Aktionsbedingungen 25 digitale PC-Spiele dazu. Dazu zählen unter anderem Skyrim Special Edition, Oblivion, Halo: Combat Evolved Anniversary, Gears of War: Reloaded, Age of Empires 2, Doom, Quake, Fallout 76 und Call of Duty: WWII. Berechtigt sind ausgewählte Windows-Home-Geräte teilnehmender Händler und Hersteller, auch einige Handhelds; Windows-Pro-Geräte sind bis auf eine Ausnahme ausgeschlossen. Refurbished-, Open-Box-, Rückläufer- und Vorführgeräte zählen nicht. Der Kauf muss zwischen dem 2. November und dem 31. Dezember 2026 erfolgen. Das Paket erscheint spätestens am 30. November im Microsoft Store unter „Im Lieferumfang des Geräts enthalten“ und muss bis 12. Februar 2027 eingelöst werden. Die Lizenzen sind an das Microsoft-Konto gebunden und nicht übertragbar. Laut PC Games gilt die Aktion nur in den USA, in Deutschland und Österreich also nicht. Ob sie ausgeweitet wird, ist nicht bekannt. In der Community kommt die Aktion eher kritisch an, auch weil neue PC-Hardware derzeit besonders teuer ist.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/Microsoft-Xbox-Konsolen-18125/News/25-Gratis-Spiele-bei-Kauf-eines-neuen-PCs-1559998/"}, "weitere_links": [{"name": "Microsoft (Aktionsbedingungen)", "url": "https://www.microsoft.com/en-us/windows/xbox-bundle-terms-and-conditions"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120999976927220138"}], "tags": ["Xbox", "25 Jahre Xbox", "Windows", "Microsoft Store", "Asha Sharma"], "bild": {"datei": "assets/img/news/2026-11-14-xbox-25-spiele-pc-kauf.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.758Z"}, "id": "2026-11-14-12v2x6-pinprotect-november", "datum": "2026-11-14T15:34:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Netzteil"], "kategorie": "Grafikkarten", "titel": "Über zehn neue Fälle geschmolzener GeForce-Stromstecker im November; Corsairs Spezialkabel zeigt, wann PinProtect abschaltet", "schlagzeile": "Schon wieder geschmolzen: Über zehn Stecker-Fälle allein im November", "kurz": "VideoCardz hat allein für November mehr als zehn gemeldete Fälle beschädigter 16-Pin-Stromstecker bei GeForce-Karten gezählt, bis hinunter zur RTX 5070. Gleichzeitig zeigt ein Test mit einem Corsair-Spezialkabel, dass dessen Schutzfunktion PinProtect bei Überlast tatsächlich abschaltet.", "zusammenfassung": "Die Probleme mit dem 12V-2×6-Stecker reißen nicht ab. VideoCardz hat Meldungen gesammelt, die der Kanal UNIKO's Hardware aus Reddit, chinesischen Foren und anderen Communitys zusammengetragen hat, und kommt allein im November auf mehr als zehn Fälle. Betroffen sind unter anderem RTX 5090 D, mehrere RTX 4090, eine RTX 5080, eine RTX 5070 Ti und zwei RTX 5070. Auffällig ist die RTX 5070, die Nvidia nur mit 250 Watt angibt, gegenüber 575 Watt bei der RTX 5090. Manche Schäden lagen an der Grafikkarte, andere an Adaptern oder auf der Netzteilseite. Wie häufig solche Fehler insgesamt sind, lässt sich aus den Einzelmeldungen nicht ableiten, und die Ursachen sind nicht einzeln geprüft. Passend dazu hat Professional Review ein bisher unbekanntes Corsair-Testkabel gezeigt, bei dem sich jede der sechs 12-Volt-Leitungen per Schalter abtrennen lässt. An einer RTX 5080 mit rund 250 Watt Last wurden die Leitungen nacheinander abgeschaltet. Erst als nur noch wenige Pins Strom führten und ein Pin über die Schwelle von rund 9,5 Ampere kam, schaltete Corsairs PinProtect im Netzteil RM1200e die Karte ab. Das Kabel ist laut Wccftech nicht im Handel erhältlich und dient offenbar internen Tests.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/here-are-all-the-melted-geforce-power-connector-and-cable-cases-reported-in-november-alone"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/corsairs-special-12v-2x6-cable-with-six-switches-gets-tested/"}], "tags": ["12V-2×6", "12VHPWR", "RTX 5070", "RTX 4090", "Corsair", "PinProtect"], "bild": {"datei": "assets/img/news/2026-11-14-12v2x6-pinprotect-november.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.664Z"}, "id": "2026-11-14-geforce-freeman-nope", "datum": "2026-11-14T14:00:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Grafikkarten", "titel": "Nvidias GeForce-Evangelist Jacob Freeman weist Spekulationen über ein Ende von GeForce nach Huangs Rücktritt zurück", "schlagzeile": "Aus für GeForce nach Huangs Abgang? Nvidia-Mann sagt: „Nope“", "kurz": "Nach dem Rücktritt von Jensen Huang fragen sich viele Gamer, ob Nvidia GeForce aufgibt. GeForce-Evangelist Jacob Freeman antwortete auf X auf genau diese Frage mit einem knappen „Nope“. Eine offizielle Roadmap gibt es dazu aber nicht.", "zusammenfassung": "Seit Jensen Huang als Nvidia-Chef zurückgetreten ist, wird spekuliert, ob sich der Konzern noch stärker auf KI-Hardware konzentriert und das Gaming-Geschäft zurückfährt. Jacob Freeman, bei Nvidia als GeForce-Evangelist tätig und früher Produktmanager bei EVGA, hat sich dazu auf X geäußert. Er war auf der LAN-Party PDXLAN in den USA und schrieb, es sei viel passiert diese Woche, die Arbeit mit Kollegen, die PC-Gaming lieben, gehe aber weiter. Auf die direkte Frage eines Nutzers, ob das nun das Ende von GeForce sei, antwortete er mit „Nope“ und einem Smiley. Das ist eine persönliche Antwort auf X und keine offizielle Ankündigung von Nvidia. Eine neue Gaming-Roadmap hat Nvidia nicht vorgelegt. Laut VideoCardz soll Nvidia zuvor mehrere bereits mit Boardpartnern besprochene Produkte gestrichen haben, darunter eine SUPER-Serie mit 3-GB-Speicherchips; bestätigt ist das nicht. Günstiger werden Grafikkarten durch Freemans Aussage ebenfalls nicht, die RTX 5090 kostet in den USA derzeit mehr als das Dreifache ihrer UVP.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/nvidias-jacob-freeman-says-the-end-of-geforce-is-not-happening"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/geforce-evangelist-jacob-freeman-assures-gaming-gpus-safe-prices/"}], "tags": ["Nvidia", "GeForce", "Jacob Freeman", "Jensen Huang"], "bild": {"datei": "assets/img/news/2026-11-14-geforce-freeman-nope.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:02.098Z"}, "id": "2026-11-14-tarkov-konsole-mobile", "datum": "2026-11-14T12:00:00+01:00", "label": "News", "bereich": "games", "themen": ["Escape from Tarkov"], "kategorie": "Spiele", "titel": "Escape from Tarkov: Konsolenversion soll 2027 angekündigt werden, erscheint aber frühestens 2028; Mobile-Ableger wird ein Top-down-Extraction-Shooter", "schlagzeile": "Tarkov: Konsolenfassung erst ab 2028, Handy-Ableger von oben", "kurz": "Battlestate-Chef Nikita Buyanov will die Konsolenfassung von Escape from Tarkov im kommenden Jahr vorstellen, erscheinen soll sie aber nicht vor 2028. Das geplante Handyspiel wird laut Insider Gaming kein Port, sondern ein Extraction-Shooter aus der Top-down-Perspektive. Auch dieses Spiel soll 2027 angekündigt werden.", "zusammenfassung": "Battlestate Games hat in einem Interview mit Insider Gaming neue Details zu seinen Tarkov-Plänen verraten. Laut PC Games steht Studio-Chef Nikita Buyanov kurz davor, einen Partner für die Konsolenumsetzung zu finden. Er rechnet fest damit, die Konsolenfassung 2027 offiziell vorzustellen, womöglich schon Anfang des Jahres. Eine Veröffentlichung im Jahr 2027 schloss er aus, frühestens 2028 ist also realistisch. Für welche Konsolen die Fassung kommt, hat Battlestate weiterhin nicht verbindlich gesagt. Schon früher hatte Buyanov angekündigt, dass die Konsolenversion nicht vereinfacht werden und sogar ohne Zielhilfe auskommen soll; ob das so bleibt, ist offen. Außerdem arbeitet das Studio an einem Tarkov-Spiel für Smartphones. Laut Buyanov ist es ein Extraction-Spiel im Look von Tarkov, aber aus der Third-Person-Perspektive von oben, ähnlich wie Escape from Duckov oder Zero Sievert. Es gebe bereits spielbare Prototypen, eine Ankündigung sei für nächstes Jahr geplant. Im Dezember startet zudem die zweite PvP-Season von Escape from Tarkov.", "quelle": {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/tarkov-new-mobile-game-top-down-extraction-shooter/"}, "weitere_links": [{"name": "PC Games", "url": "https://www.pcgames.de/Escape-from-Tarkov-Spiel-56471/News/konsolenversion-release-2028-1559994/"}], "tags": ["Escape from Tarkov", "Battlestate Games", "Konsole", "Mobile", "Extraction-Shooter"], "bild": {"datei": "assets/img/news/2026-11-14-tarkov-konsole-mobile.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.581Z"}, "id": "2026-11-14-rtx5090-usa-dreifach-uvp", "datum": "2026-11-14T11:15:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU"], "kategorie": "Grafikkarten", "titel": "RTX 5090 bei Newegg wieder lieferbar, aber zum mehr als dreifachen UVP; in Japan sinken die Preise für RTX 5090 und RTX 5080", "schlagzeile": "RTX 5090 wieder lieferbar – für das Dreifache der UVP", "kurz": "Die GeForce RTX 5090 ist bei Newegg in den USA wieder direkt lieferbar. Das günstigste Modell kostet aber 6.249,99 Dollar, mehr als dreimal so viel wie die UVP von 1.999 Dollar. In Japan sind die Preise für RTX 5090 und RTX 5080 dagegen zuletzt deutlich gefallen.", "zusammenfassung": "Nach Wochen mit kaum verfügbarer Ware listet der US-Händler Newegg laut VideoCardz wieder mehrere RTX-5090-Modelle zum direkten Kauf. Am günstigsten ist eine ASUS ROG Astral RTX 5090 OC für 6.249,99 Dollar. Modelle von GIGABYTE und MSI liegen zwischen rund 6.600 und 7.000 Dollar, eine MSI SUPRIM SOC kostet 7.349,99 Dollar. Nvidias offizielle UVP liegt weiterhin bei 1.999 Dollar, selbst das billigste Angebot kostet also gut das 3,1-Fache. Im September gab es bei Newegg selbst kaum noch Lagerware, Käufer waren meist auf Marktplatz-Händler angewiesen. In Japan geht es dagegen nach unten: Laut Wccftech mit Verweis auf ITmedia und Gazlog fiel eine Palit RTX 5090 GameRock bei Dospara von 1.288.000 auf 1.048.000 Yen, im Laden in Akihabara sogar auf 999.800 Yen. Die RTX 5080 sank von bis zu 359.800 auf 299.800 Yen. Zeitlich fällt das mit dem Rücktritt von Jensen Huang zusammen, einen direkten Zusammenhang sehen die Berichte aber nicht. Die Preise hatten demnach schon Ende Oktober ihren Höhepunkt erreicht, danach stiegen die Lagerbestände. Ob daraus ein breiter Preisrückgang wird, ist offen.", "quelle": {"name": "VideoCardz", "url": "https://videocardz.com/newz/nvidia-geforce-rtx-5090-returns-to-stock-at-us-retailers-now-available-for-just-3x-msrp"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/geforce-rtx-5090-and-rtx-5080-witness-a-sudden-price-drop-of-up-to-22-in-japan-but-its-unlikely-due-to-jensens-resignation/"}], "tags": ["RTX 5090", "RTX 5080", "Grafikkartenpreise", "Newegg", "Japan"], "bild": {"datei": "assets/img/news/2026-11-14-rtx5090-usa-dreifach-uvp.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:02.272Z"}, "id": "2026-11-14-steamos-3-10-hdmi21-amd", "datum": "2026-11-14T10:08:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "SteamOS"], "kategorie": "Software", "titel": "SteamOS 3.10.0 Preview: HDMI 2.1 mit VRR, FRL und ALLM für AMD-Grafik, Mesh Shader für Nvidia ab Turing", "schlagzeile": "SteamOS 3.10 Preview: AMD-Grafik bekommt endlich HDMI 2.1 mit VRR", "kurz": "Valve hat SteamOS 3.10.0 als öffentliche Vorschau veröffentlicht. Mit AMD-Grafik unterstützt das System jetzt HDMI 2.1 mit VRR, FRL und ALLM. Nvidia-Karten ab Turing bekommen Mesh Shader, dazu kommt ein Kernel auf Basis von Linux 7.3.", "zusammenfassung": "Valve hat laut GamingOnLinux die Preview von SteamOS 3.10.0 veröffentlicht. Für Nutzer mit AMD-Grafik ist die wichtigste Neuerung die Unterstützung von HDMI 2.1 mit variabler Bildrate (VRR), Fixed Rate Link (FRL) für hohe Bandbreiten und dem automatischen Spielemodus ALLM. Als bekanntes Problem nennt Valve, dass der Monitor Dell G3223Q schwarz bleiben kann. Für Nvidia-Grafik gibt es Stabilitäts- und Leistungsverbesserungen, Mesh Shader ab der Turing-Generation und Korrekturen für Grafikfehler in Shadow of the Tomb Raider und The Surge 2. Im Spielmodus kommt die Vulkan-Erweiterung VK_EXT_present_timing dazu. Außerdem verbessert Valve das Frame-Timing mit Bildratenbegrenzer unter VRR und reduziert Flackern in der Steam-Oberfläche. Für den ASUS ROG Xbox Ally X20 gibt es HDR- und Helligkeitseinstellungen. Der Desktop-Modus springt auf KDE Plasma 6.8.2, der Kernel auf Linux 7.3. Es handelt sich um eine frühe Testversion; Valve rät nur zum Wechsel, wer mit möglichen Fehlern leben kann.", "quelle": {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/steamos-3-10-0-preview-brings-hdmi-2-1-vrr-frl-and-allm-for-amd-and-improvements-for-nvidia/"}, "weitere_links": [], "tags": ["SteamOS", "Valve", "HDMI 2.1", "VRR", "AMD", "Nvidia", "Linux"], "bild": {"datei": "assets/img/news/2026-11-14-steamos-3-10-hdmi21-amd.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.934Z"}, "id": "2026-11-14-gta6-fake-pc-download-malware", "datum": "2026-11-14T08:36:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6", "Sicherheit"], "kategorie": "Spiele", "titel": "Gefälschter GTA-6-PC-Download verteilt Infostealer, der Steam-Logins und Krypto-Wallets abgreift", "schlagzeile": "Vorsicht: „GTA 6 für PC“ ist Malware – sie klaut Steam-Logins", "kurz": "Sicherheitsforscher von Cynet warnen vor einem angeblichen GTA-6-PC-Download, der in Wahrheit Schadsoftware ist. Sie stiehlt unter anderem Passwörter, Steam- und Roblox-Zugänge sowie Daten von Krypto-Wallets. Eine PC-Version von GTA 6 gibt es nicht, das Spiel erscheint am 19. November nur für PS5 und Xbox Series X|S.", "zusammenfassung": "Kurz vor dem Start von GTA 6 versuchen Betrüger, die Vorfreude auszunutzen. Laut Neowin hat die Sicherheitsfirma Cynet einen angeblichen „GTA 6 EXE FILE DOWNLOAD“ untersucht, der über ein Google-Colab-Notebook verbreitet wurde. Der Link führt auf eine Seite, die sich als Software-Portal ausgibt und mit Versionsnummer, Download-Zähler und Siegeln wie „Virus-free“ und „Verified“ seriös wirken soll. Angeboten werden nur 72 MB, im Archiv stecken eine winzige EXE-Datei und eine Textdatei. Diese fordert dazu auf, die EXE als Administrator zu starten, Sicherheitswarnungen zu ignorieren und eine Ausnahme im Virenscanner einzurichten. Wer das tut, installiert einen Infostealer, der virtuelle Maschinen und Sandboxes erkennt und sich in Browser-Prozesse einklinkt. Er stiehlt Passwörter, Cookies, Browserdaten, Geheimnisse aus Browser-Erweiterungen, Steam- und Roblox-Zugangsdaten sowie Krypto-Wallet-Daten. Außerdem kann er kopierte Krypto-Adressen austauschen und weitere Schadsoftware nachladen. Wichtig: Eine PC-Version von GTA 6 ist nicht angekündigt. Zum Start am 19. November erscheint das Spiel nur für PlayStation 5 und Xbox Series X|S, jeder Windows- oder Mac-Download ist daher mit hoher Wahrscheinlichkeit Betrug.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/fake-gta-vi-download-for-pc-steals-steam-logins-crypto-wallet-data/"}, "weitere_links": [], "tags": ["GTA 6", "Malware", "Infostealer", "Steam", "Sicherheit"], "bild": {"datei": "assets/img/news/2026-11-14-gta6-fake-pc-download-malware.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.417Z"}, "id": "2026-11-14-wine-11-22-avx-arm", "datum": "2026-11-14T02:35:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux"], "kategorie": "Software", "titel": "Wine 11.22 emuliert AVX auf ARM64 und behebt 34 Fehler, unter anderem in Guild Wars 2 und Star Citizen", "schlagzeile": "Wine 11.22: Windows-Programme mit AVX laufen jetzt auch auf ARM", "kurz": "Die Entwicklerversion Wine 11.22 kann AVX-Befehle in der x86-Emulation auf ARM64 nachbilden. Damit laufen mehr moderne Windows-Programme auf ARM-Rechnern unter Linux. Dazu kommen 34 Fehlerkorrekturen, auch für Spiele.", "zusammenfassung": "Das Wine-Projekt hat die Entwicklerversion 11.22 veröffentlicht. Wichtigste Neuerung ist laut Phoronix die Unterstützung von AVX-Befehlen in der x86-Emulation unter ARM64. Viele moderne Windows-Programme setzen AVX voraus und liefen bisher auf ARM-Systemen mit Wine nicht oder nur eingeschränkt. Mit ARM64EC-Builds lassen sich diese Befehle jetzt emulieren. Das ist vor allem für Linux auf ARM-Rechnern interessant. Außerdem aktualisiert Wine 11.22 die Sprachdaten auf Unicode CLDR 49, führt eine Zufallsverteilung des Adressraums ein und verbessert die Darstellung der Schrift Tahoma. Insgesamt behebt die Version 34 bekannte Fehler, unter anderem in Guild Wars 2, Star Citizen und der Logos Bible Software. Wine ist die Grundlage von Valves Proton, mit dem Windows-Spiele unter Linux und auf dem Steam Deck laufen. Neuerungen aus Wine landen aber erst mit der Zeit in Proton. Es handelt sich um eine Entwicklerversion; die stabile Version Wine 12.0 wird für Anfang 2027 vorbereitet.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Wine-11.22-Released"}, "weitere_links": [], "tags": ["Wine", "Linux", "ARM64", "AVX", "Proton"], "bild": {"datei": "assets/img/news/2026-11-14-wine-11-22-avx-arm.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.290Z"}, "id": "2026-11-14-windows11-neuer-ausfuehren", "datum": "2026-11-14T02:30:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Windows 11 bekommt im Dezember den neuen Ausführen-Dialog, der Durchsuchen-Knopf fällt weg", "schlagzeile": "Win+R wird modern: Neuer Ausführen-Dialog kommt im Dezember für alle", "kurz": "Der neu gestaltete Ausführen-Dialog von Windows 11 ist im Release-Preview-Kanal angekommen. Er soll mit dem Patchday am 8. Dezember auf alle PCs mit 25H2 und 26H2 kommen. Der alte Dialog bleibt per Schalter verfügbar.", "zusammenfassung": "Microsoft bringt den modernisierten Ausführen-Dialog (Win+R) zu allen Windows-11-Nutzern. Laut Windows Latest steckt er jetzt in den Release-Preview-Builds 26200.10066 (25H2) und 26300.10066 (26H2). Normalerweise folgt darauf Ende des Monats ein optionales Update und am 8. Dezember die Verteilung an alle per Patchday. Die Einführung erfolgt schrittweise, nicht jeder PC bekommt den Dialog sofort. Der neue Dialog basiert auf WinUI 3, unterstützt den Dark Mode und öffnet laut Microsoft im Mittel in 94 Millisekunden statt 103 Millisekunden beim alten. Der Knopf „Durchsuchen“ fällt weg: Laut Microsoft hat ihn in einer Stichprobe von 35 Millionen Nutzern nur 0,0038 Prozent je angeklickt. Pfade lassen sich weiter eintippen, und die neue Abkürzung ~\\ springt in den Benutzerordner. Frühere Befehle erscheinen über dem Eingabefeld und lassen sich mit den Pfeiltasten durchblättern. Wer den alten Dialog lieber mag, schaltet unter Einstellungen > System > Erweitert zurück. Microsoft will nach und nach weitere alte Dialoge auf WinUI 3 umstellen, etwa die Eigenschaften im Datei-Explorer.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/14/windows-11s-modern-run-box-arrives-for-everyone-in-december-and-microsoft-found-almost-nobody-ever-clicked-browse-in-the-old-one/"}, "weitere_links": [{"name": "Windows Insider Blog", "url": "https://blogs.windows.com/windows-insider/2026/11/13/announcing-new-builds-for-13-november-2026/"}], "tags": ["Windows 11", "Ausführen", "WinUI 3", "Release Preview"], "bild": {"datei": "assets/img/news/2026-11-14-windows11-neuer-ausfuehren.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.938Z"}, "id": "2026-11-14-blade-runner-aaa-spiel", "datum": "2026-11-14T00:49:00+01:00", "label": "News", "bereich": "games", "themen": ["Blade Runner"], "kategorie": "Spiele", "titel": "Blade-Runner-Rechteinhaber Alcon spricht über ein AAA-Videospiel zur Filmreihe", "schlagzeile": "Blade Runner als AAA-Spiel? Rechteinhaber bestätigt Gespräche", "kurz": "Alcon Entertainment, Besitzer der Blade-Runner-Marke, führt Gespräche über ein großes AAA-Spiel. Das bestätigten die beiden Alcon-Chefs im Gespräch mit IGN. Details wie Studio, Plattformen oder Termin gibt es noch nicht.", "zusammenfassung": "Die Filmreihe Blade Runner könnte ein großes Videospiel bekommen. Andrew Kosove und Broderick Johnson, die Chefs des Rechteinhabers Alcon Entertainment, haben laut IGN bestätigt, dass es Gespräche über ein AAA-Spiel gibt. Die Aussage fiel in einem Interview zur neuen Serie Blade Runner 2099, die am 25. November bei Prime Video startet. Auf die Frage, warum es nach dem Erfolg von Cyberpunk 2077 kein großes Blade-Runner-Spiel gibt, antwortete Kosove mit „Ja“ und betonte ausdrücklich das „AAA“. Spieler sollen mit der Welt von Blade Runner interagieren können. Mehr wollte er nicht verraten. Ein Entwicklerstudio, Plattformen oder ein Zeitraum sind damit nicht bekannt, und Gespräche bedeuten noch kein angekündigtes Spiel. Die Marke hat bisher wenig Glück mit Spielen: Als Klassiker gilt nur das Adventure von Westwood aus dem Jahr 1997, das 2022 ein Remaster bekam. Das 2023 angekündigte Blade Runner 2033: Labyrinth von Annapurna gilt als eingestellt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/blade-runner-2099-executive-producers-confirm-franchise-owners-are-in-talks-for-aaa-video-game-adaptation"}, "weitere_links": [], "tags": ["Blade Runner", "Alcon Entertainment", "AAA", "Cyberpunk"], "bild": {"datei": "assets/img/news/2026-11-14-blade-runner-aaa-spiel.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.843Z"}, "id": "2026-11-14-pearl-abyss-ki-pipeline", "datum": "2026-11-13T23:17:00+01:00", "label": "News", "bereich": "games", "themen": ["Crimson Desert"], "kategorie": "Spiele", "titel": "Crimson-Desert-Studio Pearl Abyss will KI in seiner gesamten Entwicklung ausbauen, DokeV soll 2028 erscheinen", "schlagzeile": "Trotz Ärger um Crimson Desert: Pearl Abyss setzt noch stärker auf KI", "kurz": "Pearl Abyss, das Studio hinter Crimson Desert, will KI künftig in der gesamten Spieleentwicklung einsetzen. Das steht im Brief zu den Quartalszahlen. Zugleich nennt das Studio ein Ziel für DokeV: zweite Jahreshälfte 2028.", "zusammenfassung": "Pearl Abyss baut den Einsatz von KI in der Spieleentwicklung aus. Das geht laut PC Gamer und Eurogamer aus dem Brief des Studios zu den Zahlen des dritten Quartals 2026 hervor. Demnach prüft das Team neue Spielsysteme inzwischen mit KI, bevor sie aufwendig von Hand umgesetzt werden. KI soll außerdem wiederkehrende Aufgaben automatisieren, bei der Erstellung von Inhalten helfen und Tests optimieren, und zwar in der gesamten Entwicklungs-Pipeline. Pearl Abyss betont, KI sei nur ein Werkzeug und kein Ersatz für Entwickler; Gameplay und Inhalte würden weiterhin vom Team gestaltet. Das Thema ist heikel: Anfang des Jahres musste sich das Studio entschuldigen, weil in Crimson Desert KI-generierte 2D-Grafiken entdeckt wurden. Damals hieß es, diese hätten eigentlich vor dem Release ersetzt werden sollen, und man habe den KI-Einsatz nicht klar genug offengelegt. Welche Spiele genau betroffen sind und wie viel KI-Inhalt am Ende im fertigen Spiel landet, sagt der Brief nicht. Außerdem nennt Pearl Abyss ein Ziel für DokeV: Das bunte Actionspiel soll in der zweiten Jahreshälfte 2028 erscheinen.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/ai/dont-like-ai-in-games-crimson-desert-studio-pearl-abyss-aint-care-its-expanding-ai-use-throughout-our-entire-development-pipeline/"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/crimson-desert-devs-proudly-using-ai/"}], "tags": ["Pearl Abyss", "Crimson Desert", "DokeV", "KI", "Spieleentwicklung"], "bild": {"datei": "assets/img/news/2026-11-14-pearl-abyss-ki-pipeline.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.547Z"}, "id": "2026-11-14-nvidia-ceo-suche-haas", "datum": "2026-11-13T22:03:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "Nvidia-Chefsuche: Verwaltungsrat soll Arm-Chef Rene Haas angesprochen haben, Nvidia nennt Spekulationen verfrüht", "schlagzeile": "Wird der Arm-Chef neuer Nvidia-Boss? Verwaltungsrat bremst", "kurz": "Laut Financial Times hat Nvidias Verwaltungsrat Arm-Chef Rene Haas als möglichen Nachfolger von Jensen Huang angesprochen. Nvidia selbst sagt, man suche erst eine Personalberatung und habe noch keine Kandidaten offiziell kontaktiert. Gleichzeitig kursiert ein angeblicher Mitarbeiterbrief für Huangs Rückkehr, den ein Nvidia-Manager als Fälschung bezeichnet.", "zusammenfassung": "Nach dem Rücktritt von Jensen Huang sucht Nvidia einen neuen Chef. Laut einem Bericht der Financial Times, zusammengefasst von Tom's Hardware, hat der Verwaltungsrat Arm-Chef Rene Haas als möglichen Nachfolger angesprochen. Haas soll einer von mehreren Kandidaten sein; ob er ein Angebot bekommt oder annehmen würde, ist offen. Er arbeitete bis 2013 rund sieben Jahre bei Nvidia, unter anderem an Notebook-GPUs und Tegra-Chips, und führt Arm seit 2022. Nvidia hat auf den Bericht reagiert: Gegenüber CNBC erklärte der Verwaltungsrat, man wähle gerade erst eine Personalberatung aus und habe noch keine Kandidaten offiziell kontaktiert. Spekulationen über einzelne Namen seien verfrüht. Bis auf Weiteres führt Finanzchefin Colette Kress das Unternehmen kommissarisch. Intern ist die Stimmung laut WIRED, zitiert von PCGH, gespalten: Ein Beitrag in Nvidias interner Ideenbox sammelte über 1.600 Kommentare, überwiegend für eine Rückkehr Huangs. Ein im Netz verbreiteter Brief, angeblich von Nvidia-Führungskräften unterschrieben, ist dagegen laut dem Nvidia-Forschungschef Bryan Catanzaro eine Fälschung; er habe ihn nicht unterschrieben und stehe hinter dem Verwaltungsrat. Elon Musk kündigte laut Wccftech an, eine Petition für Huangs Rückkehr zu unterschreiben. Eine Wiedereinsetzung Huangs ist von Nvidia nicht angekündigt. Für GeForce-Kunden gibt es laut PCGH bisher keine bekannten Auswirkungen auf Produkte oder Preise. Am 17. November legt Nvidia erstmals ohne Huang Quartalszahlen vor.", "quelle": {"name": "Tom's Hardware", "url": "https://www.tomshardware.com/pc-components/gpus/nvidia-board-reportedly-approached-arm-ceo-rene-haas-during-replacement-search-jensen-huangs-transgressions-leave-nvidia-scrambling-to-fill-a-massive-void"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/Jensen-Huang-Ruecktritt-Mitarbeiter-fordern-Rueckkehr-1559985/"}, {"name": "Wccftech", "url": "https://wccftech.com/letter-seeking-ex-ceo-jensen-huangs-return-is-obviously-fake-says-nvidia-vp-after-he-is-made-a-named-signatory-alongside-top-leadership-at-firm/"}, {"name": "CNBC", "url": "https://www.cnbc.com/2026/11/13/nvidia-huang-ceo-replacement-search.html"}], "tags": ["NVIDIA", "Rene Haas", "Arm", "Jensen Huang", "Colette Kress"], "bild": {"datei": "assets/img/news/2026-11-14-nvidia-ceo-suche-haas.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.024Z"}, "id": "2026-11-14-pioner-eingestellt", "datum": "2026-11-13T21:37:00+01:00", "label": "News", "bereich": "games", "themen": ["Survival-Shooter"], "kategorie": "Spiele", "titel": "Survival-Shooter Pioner wird eingestellt, das Studio hat kein Geld mehr für Entwicklung und Server", "schlagzeile": "Aus nach elf Monaten: Survival-Shooter Pioner macht dicht", "kurz": "Der Survival-Shooter Pioner wird weniger als ein Jahr nach dem Start im Early Access eingestellt. Entwickler GFAGames hat keine Finanzierung für Weiterentwicklung und Server gefunden. Wann die Server abgeschaltet werden, ist noch offen.", "zusammenfassung": "Der Survival-Shooter Pioner ist am Ende. Laut PC Gamer hat Entwickler GFAGames auf Steam angekündigt, die Entwicklung einzustellen und das Spiel zu schließen. Gespräche mit bestehenden und neuen Partnern über eine Finanzierung seien gescheitert. Das Studio habe nicht mehr genug eigenes Geld, um weiterzuentwickeln und die Server zu betreiben. Pioner galt seit seiner Vorstellung 2021 als Mischung aus Stalker, Metro und Escape from Tarkov, mit Einzelspieler-Kampagne sowie Koop- und PvP-Modus in einer spätsowjetischen Welt. Seit Dezember 2025 war es im Early Access und erreichte auf Steam in der Spitze 1.686 gleichzeitige Spieler. Nach technischen Problemen und langsamen Updates brachen die Zahlen im Sommer ein, Mitte September spielten nur noch ein paar Dutzend Menschen. Viele Käufer fordern unter der Ankündigung eine Rückerstattung. Dazu hat sich GFAGames noch nicht geäußert. Auch ein Termin für die Abschaltung der Server fehlt noch.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/fps/a-survival-game-we-once-called-stalker-and-tarkovs-alien-baby-is-closing-down-less-than-a-year-after-launch/"}, "weitere_links": [], "tags": ["Pioner", "GFAGames", "Early Access", "Survival-Shooter"], "bild": {"datei": "assets/img/news/2026-11-14-pioner-eingestellt.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.499Z"}, "id": "2026-11-14-euro-office-desktop", "datum": "2026-11-13T21:14:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Office"], "kategorie": "Software", "titel": "Europäische Office-Alternative Euro-Office gibt es jetzt als Desktop-App für Windows, macOS und Linux", "schlagzeile": "Europas Office-Alternative gibt es jetzt auch offline auf dem Desktop", "kurz": "Euro-Office, die europäische Alternative zu Microsoft 365, gibt es jetzt als kostenlose Desktop-App namens Nextcloud Office Desktop. Sie läuft offline unter Windows, macOS und Linux. Technisch ist sie ein Ableger von ONLYOFFICE.", "zusammenfassung": "Euro-Office ist jetzt auch als klassische Desktop-Anwendung verfügbar. Laut OMG! Ubuntu heißt die App Nextcloud Office Desktop und ist kostenlos sowie quelloffen. Euro-Office wurde im März 2026 als europäische Alternative zu Microsoft 365 angekündigt und lief bisher nur über einen Server im Browser oder per Mobil-App. Die Desktop-Version funktioniert dagegen ohne eigenen Server und offline. Sie bietet Textverarbeitung, Tabellenkalkulation, Präsentationen und PDF-Werkzeuge. Microsoft-Formate wie DOCX, XLSX und PPTX werden ebenso unterstützt wie offene Formate wie ODT. Zusätzlich lässt sich die App mit Nextcloud oder anderen Servern für gemeinsames Bearbeiten verbinden. Installer gibt es für Windows und macOS auf x86 und ARM64 sowie für Linux auf x86 als DEB- und RPM-Paket. Technisch basiert Euro-Office auf ONLYOFFICE, dessen Hersteller den Ableger kritisch sieht. Auch aus dem LibreOffice-Lager gibt es Kritik. OMG! Ubuntu merkt an, dass die App derzeit vor allem wie ein umbenanntes ONLYOFFICE wirkt.", "quelle": {"name": "OMG! Ubuntu", "url": "https://www.omgubuntu.co.uk/2026/11/euro-office-desktop-apps-nextcloud"}, "weitere_links": [{"name": "Dr. Windows", "url": "https://www.drwindows.de/news/euro-office-offizielle-desktop-app-wurde-veroeffentlicht"}], "tags": ["Euro-Office", "Nextcloud", "ONLYOFFICE", "Open Source", "Digitale Souveränität"], "bild": {"datei": "assets/img/news/2026-11-14-euro-office-desktop.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.200Z"}, "id": "2026-11-14-m365-stoerung-ursache", "datum": "2026-11-13T20:54:00+01:00", "label": "News", "bereich": "software", "themen": ["Microsoft 365"], "kategorie": "Software", "titel": "Microsoft entschuldigt sich für die Microsoft-365-Großstörung und nennt ein Netzwerk-Upgrade als Ursache", "schlagzeile": "Microsoft-365-Ausfall: Kein Hack, keine KI – ein Netzwerk-Upgrade war schuld", "kurz": "Microsoft hat sich für die weltweite Störung von Outlook, Teams und Co. entschuldigt. Ursache war laut Microsoft ein Fehler aus einem früheren Netzwerk-Upgrade, nicht ein Angriff oder KI. Ein ausführlicher Bericht soll folgen.", "zusammenfassung": "Microsoft hat die Ursache der großen Microsoft-365-Störung vom 12. November genannt. Laut PC Gamer entschuldigte sich das Unternehmen in einer Stellungnahme ausdrücklich bei Kunden und Partnern. Der Fehler sei bei einem früheren Ausbau der Netzwerkkapazität entstanden und erst nach einer späteren Netzwerkänderung zum Problem geworden. Ein Cyberangriff oder KI-Agenten seien nicht beteiligt gewesen. Im Netz war zuvor spekuliert worden, ob KI-generierter Code den Ausfall verursacht hat. Microsoft gibt an, die eigentliche Ursache behoben zu haben, und meldet eine breite Erholung der Dienste. Die Wiederherstellung sei bewusst schrittweise erfolgt, um die Stabilität zu prüfen, und habe deshalb länger gedauert. Am Samstag teilte Microsoft mit, dass die Dienste für die zuletzt betroffenen Kunden und Regionen vollständig wiederhergestellt sind. Betroffen waren unter anderem Outlook, Teams, SharePoint und Copilot. Einen ausführlichen Bericht will Microsoft nach Abschluss der internen Prüfung veröffentlichen. Firmenkunden können je nach Vertrag eine SLA-Gutschrift prüfen.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/microsoft-deeply-apologizes-for-global-service-outage-says-no-ai-or-hackers-are-to-blame/"}, "weitere_links": [{"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/14/microsoft-is-begging-you-not-to-blame-ai-for-the-microsoft-365-outage-insisting-it-was-a-botched-network-upgrade/"}, {"name": "Associated Press", "url": "https://apnews.com/article/microsoft-outage-outlook-email-365-recover-ca395c0f1e51af784b6d70afb6554f6a"}], "tags": ["Microsoft 365", "Outlook", "Teams", "Störung"], "bild": {"datei": "assets/img/news/2026-11-14-m365-stoerung-ursache.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:01.116Z"}, "id": "2026-11-14-windows-oob-aktivierung", "datum": "2026-11-13T20:32:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Microsoft veröffentlicht Notfall-Update gegen Aktivierungsfehler nach dem November-Patchday", "schlagzeile": "Notfall-Update: Microsoft repariert Windows-Aktivierung nach Patchday", "kurz": "Microsoft hat außerplanmäßige Updates veröffentlicht, die den Aktivierungsfehler 0x80041008 nach dem November-Patchday beheben. Betroffen waren vor allem Firmen, die Windows über slmgr.vbs aktivieren. Die Updates gibt es für Windows 11 23H2, Windows 10 und Windows Server.", "zusammenfassung": "Microsoft hat den Aktivierungsfehler nach dem November-Patchday mit einem Notfall-Update behoben. Das berichtet Neowin. Nach den Sicherheitsupdates scheiterten Aktivierungs- und Lizenzbefehle über das Tool slmgr.vbs mit dem Fehler 0x80041008. Betroffen waren vor allem Firmen, die Aktivierung und Produktschlüssel per Skript verwalten. Die außerplanmäßigen Updates gibt es für Windows Server 2025 (KB5136489), Windows Server 2022 (KB5136487), Windows Server 2019 und Windows 10 Enterprise LTSC 2019 (KB5136490), Windows 11 23H2 (KB5136483) sowie Windows 10 22H2 mit ESU und Windows 10 Enterprise LTSC 2021 (KB5136493). Es sind kumulative Updates, die auch alle bisherigen Korrekturen enthalten. Windows Server und Windows 10 erhalten sie über den Microsoft Update Catalog, Windows 11 23H2 zusätzlich über die optionalen Updates in Windows Update. Für die neueren Versionen 24H2, 25H2 und 26H2 nennt der Bericht kein eigenes Update. Das ebenfalls bestätigte Druckproblem nach dem Patchday behebt dieses Update laut Bericht nicht. Microsoft empfiehlt ohnehin, für die Automatisierung künftig PowerShell statt slmgr.vbs zu nutzen.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-releases-emergency-oob-windows-update-to-fix-licensing-and-activation-issues/"}, "weitere_links": [], "tags": ["Windows 11", "Windows 10", "Windows Server", "Out-of-Band-Update", "Aktivierung"], "bild": {"datei": "assets/img/news/2026-11-14-windows-oob-aktivierung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.660Z"}, "id": "2026-11-14-nvidia-wsj-knappheit", "datum": "2026-11-13T20:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA", "GPU"], "kategorie": "Unternehmen", "titel": "WSJ-Bericht: Huang soll KI-Startups finanziert haben, damit sie Nvidias überschüssige GPUs abnehmen", "schlagzeile": "Bericht: Hat Nvidia KI-Startups bezahlt, damit sie GPUs kaufen?", "kurz": "Laut Wall Street Journal hat Jensen Huang mit Nvidias Geld KI-Startups und Rechenzentren finanziert, die dann Nvidia-GPUs kauften. Hintergrund soll ein Überangebot an bestellten TSMC-Chips gewesen sein. Finanzchefin Colette Kress soll dagegen gehalten haben.", "zusammenfassung": "Ein neuer Bericht des Wall Street Journal wirft ein Schlaglicht auf Nvidias Finanzpraktiken unter Jensen Huang. TechPowerUp und Wccftech fassen ihn zusammen. Demnach hat Nvidia KI-Startups und kleinere Cloud-Anbieter finanziell unterstützt, die mit dem Geld wiederum Nvidia-GPUs kauften und Rechenzentren bauten. Grund soll gewesen sein, dass große Cloud-Konzerne verstärkt eigene Chips einsetzen und Nvidia bei TSMC mehr Chips bestellt hatte, als direkt Abnehmer da waren. Huang soll intern von einer „Lawine“ gesprochen haben, die auf ihn zukomme. Laut dem Bericht kam es im August zu einem Streit mit Finanzchefin und heutiger Interimschefin Colette Kress, die solche Kreisfinanzierungen zurückfahren wollte, unter anderem den milliardenschweren Deal mit OpenAI. Laut Wccftech setzte Kress durch, dass die Garantien für OpenAI-Rechenleistung von bis zu 250 auf bis zu 125 Milliarden US-Dollar sinken. Huang soll sie daraufhin herabsetzend kritisiert haben. Kress soll auch gewarnt haben, dass sich viele der kleinen Cloud-Anbieter die GPUs eigentlich nicht leisten können. Ob diese Praxis die GPU- und Speicherpreise für Spieler direkt nach oben getrieben hat, belegt der Bericht nicht; das ist eine Einordnung von Wccftech. Nvidia hat sich laut den vorliegenden Berichten nicht dazu geäußert. Die Vorwürfe stammen aus anonymen Quellen und sind nicht offiziell bestätigt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354814/nvidia-allegedly-engineered-scarcity-by-funding-ai-startups-to-buy-its-gpus"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/jensen-huang-financed-ai-startups-absorb-excess-silicon/"}], "tags": ["NVIDIA", "Wall Street Journal", "TSMC", "OpenAI", "GPU-Preise"], "bild": {"datei": "assets/img/news/2026-11-14-nvidia-wsj-knappheit.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-14T18:51:00.753Z"}, "id": "2026-11-14-core-ultra-7-260k", "datum": "2026-11-13T19:44:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Intel", "CPU"], "kategorie": "Prozessoren", "titel": "Intel Core Ultra 7 260K erscheint ohne Ankündigung, vorerst nur in zwei Newegg-Komplett-PCs", "schlagzeile": "Heimlich gestartet: Intels Core Ultra 7 260K gibt es nur im Fertig-PC", "kurz": "Intel hat mit dem Core Ultra 7 260K still und leise eine neue Desktop-CPU gestartet. Sie steckt bisher nur in zwei Gaming-PCs von Newegg und wird nicht einzeln verkauft. Technisch ist sie ein leicht gedrosselter Core Ultra 7 265K.", "zusammenfassung": "Intel hat eine neue Desktop-CPU auf den Markt gebracht, ohne sie anzukündigen. Der Core Ultra 7 260K ist laut TechPowerUp nur in zwei Gaming-PCs der Newegg-Eigenmarke ABS erhältlich. Das Modell Kaze II Aqua kombiniert sie mit einer RTX 5060 für 1.699,99 US-Dollar, der Flux II Aqua mit einer RTX 5070 für 1.999,99 US-Dollar. Newegg bestätigt, dass der Prozessor exklusiv bleibt und nicht einzeln verkauft wird. Intel spricht laut Tom's Hardware von einem Modell mit begrenzter Verfügbarkeit ohne Boxed-Version. Technisch entspricht der Chip weitgehend dem Core Ultra 7 265K: 8 Performance- und 12 Effizienzkerne, 30 MB L3-Cache und 125 Watt Basisleistung. Der maximale Takt der P-Kerne liegt mit 5,4 GHz aber 100 MHz niedriger. Da er nur DDR5-6400 unterstützt, gehört er zur ursprünglichen Arrow-Lake-Familie und nicht zum Refresh mit DDR5-7200. Die ersten Newegg-Einträge waren widersprüchlich, teils stand dort 260KF oder ein Boost von 5,2 GHz. Benchmarks gibt es noch nicht. Für Selbstbauer ist die CPU damit uninteressant, und Preise oder Verfügbarkeit in Europa sind nicht bekannt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354821/intel-core-ultra-7-260k-arrives-without-an-announcement-limited-to-two-prebuilt-desktops"}, "weitere_links": [{"name": "VideoCardz", "url": "https://videocardz.com/newz/intel-core-ultra-7-260k-launches-as-newegg-exclusive-cpu-now-available-in-prebuilt-gaming-pcs"}, {"name": "Wccftech", "url": "https://wccftech.com/intel-core-ultra-7-260k-quietly-launches-as-newegg-exclusive-cpu/"}], "tags": ["Intel", "Core Ultra 7 260K", "Arrow Lake", "Newegg"], "bild": {"datei": "assets/img/news/2026-11-14-core-ultra-7-260k.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.966Z"}, "id": "2026-11-13-rainbow-six-vegas-leak", "datum": "2026-11-13T18:10:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Ubisoft"], "kategorie": "Spiele", "titel": "Bericht: Ubisoft Montreal arbeitet an neuem Rainbow Six: Vegas mit dem Codenamen Spades", "schlagzeile": "Leak: Kehrt Rainbow Six: Vegas nach 18 Jahren zurück?", "kurz": "Laut Insider Gaming hat Ubisoft ein neues Rainbow Six: Vegas freigegeben, Codename Spades. Das Spiel soll sich bei Ubisoft Montreal in einer frühen Entwicklungsphase befinden. Ubisoft hat das nicht bestätigt, eine Ankündigung dürfte noch Jahre entfernt sein.", "zusammenfassung": "Die Rainbow-Six-Vegas-Reihe könnte nach fast zwei Jahrzehnten zurückkehren. Insider Gaming berichtet unter Berufung auf anonyme Quellen, dass Ubisoft ein neues Vegas-Spiel mit dem Codenamen Spades freigegeben hat. Es soll bei Ubisoft Montreal in einer frühen Entwicklungsphase sein. Insgesamt seien dort drei neue Projekte gestartet worden, ein weiteres davon soll ebenfalls im Rainbow-Six-Universum spielen. Laut den Quellen handelt es sich eher um ein Vegas 3 als um ein Remake, sicher ist das aber nicht. Der letzte Teil, Rainbow Six: Vegas 2, erschien 2008. Seitdem lag der Fokus vor allem auf Rainbow Six Siege. Die Marke gehört inzwischen zu Vantage Studios, einer Ubisoft-Tochter, an der Tencent 26,32 Prozent hält. Ubisoft hat sich nicht geäußert, das Projekt ist also unbestätigt. Insider Gaming selbst rechnet damit, dass eine offizielle Ankündigung noch einige Jahre dauert.", "quelle": {"name": "Insider Gaming (Tom Henderson)", "url": "https://insider-gaming.com/rainbow-six-vegas-3/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354797/leak-tips-rainbow-six-vegas-series-slated-to-return-from-18-year-hiatus"}], "ursprungsquelle": "Insider Gaming (Tom Henderson), anonyme Quellen", "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Exklusivbericht von Insider Gaming mit anonymen Quellen; Tom Henderson hat eine gute Trefferquote bei Ubisoft-Projekten. TechPowerUp gibt nur den Bericht wieder, keine unabhängige Zweitquelle. Ubisoft hat nicht bestätigt."}, "tags": ["Rainbow Six", "Rainbow Six Vegas", "Ubisoft", "Tom Clancy"], "bild": {"datei": "assets/img/news/2026-11-13-rainbow-six-vegas-leak.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.066Z"}, "id": "2026-11-13-ps5-qssr-sechs-spiele", "datum": "2026-11-13T17:35:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Konsolen-Update", "titel": "Sonys KI-Upscaling QSSR kommt für sechs weitere Spiele auf die normale PS5, darunter Spider-Man 2 und Arc Raiders", "schlagzeile": "KI-Upscaling für die normale PS5: Sechs Spiele werden schärfer", "kurz": "Sonys KI-Upscaler QSSR kommt in sechs weitere PS5-Spiele, darunter Marvel's Spider-Man 2, Control Resonant und Arc Raiders. QSSR basiert auf PSSR der PS5 Pro, läuft aber auf der normalen PS5. Spider-Man 2 hat das Update bereits erhalten.", "zusammenfassung": "Sony bringt seine KI-Hochskalierung Quick Spectral Super Resolution, kurz QSSR, in weitere Spiele auf der Standard-PS5. Bestätigt sind Marvel's Spider-Man 2, Control Resonant, The Finals, ARC Raiders, No Man's Sky und Hell Let Loose: Vietnam. Laut PlayStation auf X startet Spider-Man 2 heute, VGC meldet die übrigen als aktualisiert oder in Kürze. QSSR baut auf der gleichen Grundlage wie PSSR der PS5 Pro auf. Die ersten Spiele mit QSSR waren Marvel's Wolverine und Ghost of Yōtei. Insomniac verspricht für Spider-Man 2 stabileres und schärferes Bild im Qualitäts- und im Performance-Modus. Remedy spricht bei Control Resonant von spürbar besserer Bildstabilität und feineren Details. Auch für Arc Raiders, No Man's Sky und Hell Let Loose: Vietnam nennen die Studios ein schärferes, saubereres Bild. Digital Foundry hatte das Potenzial der Technik als bemerkenswert bezeichnet, gerade weil viele Spiele dieser Generation mit niedriger Auflösung und schwachem Upscaling kämpfen. Messwerte zu Bildrate oder Auflösung nennen die Studios nicht. Ob QSSR Leistung kostet, ist daher noch offen.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/6-more-games-receive-ps5-performance-updates-via-qssr-including-arc-raiders-and-control-resonant/"}, "weitere_links": [{"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2121241936681976081"}, {"name": "Insider Gaming", "url": "https://insider-gaming.com/5-big-ps5-games-will-receive-qssr-update/"}], "tags": ["PS5", "QSSR", "PSSR", "Upscaling", "Spider-Man 2", "Arc Raiders"], "bild": {"datei": "assets/img/news/2026-11-13-ps5-qssr-sechs-spiele.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.560Z"}, "id": "2026-11-13-word-kompatibilitaet-layout", "datum": "2026-11-13T17:35:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Microsoft entfernt alte Kompatibilitätsoptionen aus Word, ältere Dokumente können ab Dezember ihr Layout verlieren", "schlagzeile": "Word bricht ab Dezember das Layout alter Dokumente – so sicherst du sie", "kurz": "Microsoft streicht einige alte Kompatibilitätseinstellungen aus Word. Dokumente, die mit Word 2010 oder älter gespeichert wurden, können danach anders umbrechen. Unter Windows startet die Umstellung im Dezember 2026, auf dem Mac Anfang 2027.", "zusammenfassung": "Microsoft räumt in Word auf und entfernt einige ältere Kompatibilitätsoptionen. Das berichtet heise unter Berufung auf die Message-Center-Mitteilung MC1551147. Betroffen sind Dokumente, die in Word 2010 oder früher erstellt oder zuletzt gespeichert wurden und diese Einstellungen nutzen. In solchen Dateien kann der Text künftig anders umbrechen. Abstände und Seitenzahlen können sich ändern, Bilder und Formen auf eine andere Seite rutschen. Welche Optionen genau wegfallen, sagt Microsoft nicht. Der Kompatibilitätsmodus selbst bleibt erhalten. Unter Windows läuft die Umstellung im Lauf des Dezembers 2026, auf dem Mac Anfang 2027. Eine Möglichkeit zum Aufschieben nennt Microsoft nicht. Wer auf das exakte Layout angewiesen ist, sollte wichtige alte Dokumente vorher prüfen und als PDF exportieren. Eine Umwandlung ins neue Word-Format hilft laut heise nicht, weil dabei die alten Kompatibilitätseinstellungen ebenfalls verloren gehen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Vorsicht-Umbruch-Word-zerschiesst-bald-das-Layout-alter-Dokumente-11524878.html"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-is-retiring-some-compatibility-mode-options-in-word-and-old-documents-may-break/"}], "tags": ["Microsoft Word", "Office", "Microsoft 365", "Kompatibilität"], "bild": {"datei": "assets/img/news/2026-11-13-word-kompatibilitaet-layout.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.162Z"}, "id": "2026-11-13-gta6-day-one-patch-macca", "datum": "2026-11-13T17:32:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6 eine Woche vor Release: erstes Update 1.002 wird verteilt, erster Teaser zur In-Game-Zeichentrickserie Macca & Friends", "schlagzeile": "GTA 6: Erstes Update vor Release – und eine eigene Zeichentrickserie", "kurz": "Rockstar verteilt eine Woche vor dem Start ein erstes, rund 1 GB großes Update für GTA 6, ohne Patch-Notes. Außerdem gibt es einen ersten Blick auf Macca & Friends, eine Zeichentrickserie, die im Spiel läuft. Laut Guardian waren fast 5.000 Menschen an GTA 6 beteiligt.", "zusammenfassung": "Kurz vor dem Release am 19. November bekommt GTA 6 bereits sein erstes Update. Laut Polygon erhielten einige Spieler am Freitag eine Benachrichtigung über Version 1.002, die rund ein Gigabyte groß ist. Rockstar hat keine Patch-Notes veröffentlicht, vermutlich auch, um nichts zu spoilern. Das Update wird offenbar gestaffelt verteilt, nicht alle sehen es sofort. Weitere Updates bis zum Start sind laut Polygon möglich. Außerdem hat der X-Account DiscussingFilm einen ersten Teaser zu Macca & Friends veröffentlicht, einer von Rockstar für das Spiel produzierten Serie, berichtet IGN. Die Zeichentrickserie über den Alligator Macca und seine Freunde läuft im Spiel auf dem Sender Weazel. Rob Nelson, einer der Studioleiter von Rockstar North, brauchte laut New York Times rund 80 Stunden für einen Durchgang. Laut einem Guardian-Bericht, zusammengefasst von Golem, waren fast 5.000 Menschen an der Entwicklung beteiligt. Wie viele davon externe Dienstleister waren, ist nicht bekannt. Laut Bloomberg hat Rockstar heute 4.711 Beschäftigte an zwölf Standorten. GTA 6 erscheint für PS5 und Xbox Series X/S, eine PC-Version ist nicht angekündigt.", "quelle": {"name": "Polygon", "url": "https://www.polygon.com/gta-6-nov-13-patch-102-what-is-download-size-ps5-xbox/"}, "weitere_links": [{"name": "IGN", "url": "https://www.ign.com/articles/gta-6-has-a-whole-animated-tv-series-you-can-watch-in-game"}, {"name": "Golem.de", "url": "https://www.golem.de/news/rockstar-games-fast-5-000-menschen-haben-an-gta-6-gearbeitet-2611-215191.html"}], "tags": ["GTA 6", "Rockstar Games", "Patch", "Day-One-Patch"], "bild": {"datei": "assets/img/news/2026-11-13-gta6-day-one-patch-macca.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.263Z"}, "id": "2026-11-13-gow-sons-of-sparta-ps4", "datum": "2026-11-13T17:17:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation"], "kategorie": "Spiele", "titel": "God of War: Sons of Sparta erscheint am 16. November für PS4 und bekommt zwei neue Spielmodi", "schlagzeile": "God of War: Sons of Sparta kommt auf die PS4 – mit zwei neuen Modi", "kurz": "Der 2D-Ableger God of War: Sons of Sparta erscheint am 16. November auch für die PS4. Gleichzeitig bekommen PS4 und PS5 per Gratis-Update zwei neue Modi: einen Speedrun-Modus und einen Modus, in dem jeder Treffer tödlich ist.", "zusammenfassung": "Sony bringt God of War: Sons of Sparta auf eine weitere Plattform. Der 2D-Action-Plattformer erscheint am 16. November um Mitternacht Ortszeit für die PlayStation 4, das hat PlayStation auf X bestätigt. Zeitgleich kommt ein kostenloses Update mit zwei neuen Modi für die PS4- und die PS5-Version. Der Hermes-Modus ist ein Speedrun-Modus mit Split-Timer und dauerhafter Bestenliste. Er wird nach dem Durchspielen freigeschaltet oder über einen Code im Startmenü, berichtet VGC. Im Erebus-Modus reicht für Kratos und die Gegner jeweils ein einziger Treffer. Diesen Modus wählt man beim Start eines neuen Spiels. Sons of Sparta wurde von Mega Cat Studios zusammen mit Santa Monica Studio entwickelt und erschien im Februar für die PS5. Das Spiel erzählt eine kanonische Geschichte aus Kratos' Jugend während seiner Ausbildung in Sparta mit seinem Bruder Deimos. Einen Preis für die PS4-Version nennt der Bericht nicht.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/playstations-god-of-war-spin-off-is-coming-to-ps4-and-getting-new-modes/"}, "weitere_links": [{"name": "PlayStation auf X", "url": "https://x.com/PlayStation/status/2121257001262969225"}, {"name": "Polygon", "url": "https://www.polygon.com/god-of-war-sons-of-sparta-new-update-ps4-release/"}], "tags": ["God of War", "PS4", "PS5", "Santa Monica Studio", "Update"], "bild": {"datei": "assets/img/news/2026-11-13-gow-sons-of-sparta-ps4.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.646Z"}, "id": "2026-11-13-tsmc-mitarbeiterdaten-leak", "datum": "2026-11-13T16:48:00+01:00", "label": "News", "bereich": "hardware", "themen": ["TSMC"], "kategorie": "Unternehmen", "titel": "TSMC bestätigt Datenleck: Daten von Mitarbeitern tauchen im Netz auf, angeblich für drei Bitcoin angeboten", "schlagzeile": "TSMC-Datenleck: Mitarbeiterdaten angeblich für drei Bitcoin im Angebot", "kurz": "TSMC hat in einer Pflichtmitteilung an die US-Börsenaufsicht bestätigt, dass Daten aktueller und ehemaliger Mitarbeiter unerlaubt auf einer externen Website aufgetaucht sind. Die Daten stammen laut TSMC aus Diensten eines Cloud-Anbieters, die eigenen Systeme seien nicht kompromittiert. Kundendaten sind laut TSMC nicht betroffen.", "zusammenfassung": "Der weltgrößte Auftragsfertiger für Chips hat ein Datenleck bestätigt. In einer Form-6-K-Mitteilung an die US-Börsenaufsicht SEC schreibt TSMC, dass Daten aktueller und ehemaliger Mitarbeiter ohne Erlaubnis auf einer externen Website verfügbar gemacht wurden. Laut Seeking Alpha, zitiert von PC Gamer, geht es um mehr als 46.000 Datensätze. TSMC zufolge stimmen die Daten mit Informationen überein, die bei einem nicht genannten Cloud-Dienstleister gespeichert waren. Hinweise auf einen Einbruch in die eigenen Systeme gebe es nicht. Betroffene seien informiert, außerdem arbeite man mit dem Cloud-Anbieter, Ermittlungsbehörden und einer externen Sicherheitsfirma zusammen. Die taiwanische United Daily News berichtet, Hacker hätten 6,9 GB an Daten in einem Untergrundforum für drei Bitcoin angeboten. Eine veröffentlichte Stichprobe soll unter anderem Ausweisnummern, Adressen und Bankdaten enthalten; das ist von TSMC nicht bestätigt. Laut TSMC haben die Daten nichts mit dem Geschäftsbetrieb oder Kundeninformationen zu tun. Chipdesigns oder Kundendaten von Firmen wie Nvidia, AMD oder Apple sind nach jetzigem Stand also nicht betroffen. Bereits 2023 war TSMC über einen gehackten Zulieferer in die Schlagzeilen geraten.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/chipmaking-giant-tsmc-discovers-major-employee-data-leak-reports-say-info-was-up-for-sale-for-three-bitcoin-on-shady-forums/"}, "weitere_links": [], "tags": ["TSMC", "Datenleck", "Sicherheit", "Chipfertigung"], "bild": {"datei": "assets/img/news/2026-11-13-tsmc-mitarbeiterdaten-leak.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.756Z"}, "id": "2026-11-13-intel-desktop-marktanteil", "datum": "2026-11-13T16:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["CPU"], "kategorie": "Prozessoren", "titel": "Mercury Research: Intel gewinnt im dritten Quartal 2026 rund fünf Prozentpunkte Desktop-Marktanteil von AMD zurück", "schlagzeile": "Überraschung: Intel nimmt AMD bei Desktop-CPUs Marktanteile ab", "kurz": "Laut Mercury Research ist AMDs Anteil bei Desktop-Prozessoren im dritten Quartal 2026 von rund 35 auf 29,9 Prozent gefallen. Die Marktforscher vermuten, dass Intel mehr Chips in den Desktop-Markt umgeleitet hat. AMD könnte zudem darunter leiden, dass der Gaming-PC-Markt schwächelt.", "zusammenfassung": "Bei Desktop-Prozessoren hat Intel im dritten Quartal 2026 deutlich Boden gutgemacht. Laut den neuen Zahlen von Mercury Research, über die PC Gamer berichtet, sank AMDs Desktop-Anteil von rund 35 Prozent im zweiten Quartal auf 29,9 Prozent. Das ist ein Rückschritt um etwa fünf Prozentpunkte innerhalb von drei Monaten. Mercury Research ist sich selbst nicht ganz sicher, woran das liegt. Die Marktforscher vermuten, dass Intel wegen schwacher Notebook-Nachfrage mehr Chips in den Desktop-Markt lenken konnte, der im dritten Quartal saisonal stärker ist. AMD habe dagegen kein saisonales Wachstum gezeigt. Als zweiten Grund nennt Mercury AMDs stärkere Abhängigkeit vom Gaming-Markt, der unter knappen und teuren Grafikkarten leidet. Dazu kommen hohe Preise für RAM und SSDs, die viele vom Kauf eines neuen PCs abhalten. Intel ist bei Komplett-PC-Herstellern stark vertreten, die auch günstige Systeme mit älteren DDR4-Plattformen bauen. PC Gamer betont, dass das kein Zeichen für einen gesunden Markt ist: Beide Hersteller sollen im dritten Quartal mehr als zehn Prozent weniger Notebook-Chips ausgeliefert haben. Bei der Gaming-Leistung liegt AMD mit den X3D-Modellen weiterhin vorne.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/processors/intel-takes-massive-chunk-out-of-amds-desktop-cpu-market-share-in-unexpected-turnaround-may-be-due-to-the-red-teams-dominance-in-gaming-chips-weirdly/"}, "weitere_links": [], "tags": ["Intel", "AMD", "Ryzen", "Marktanteil", "Mercury Research"], "bild": {"datei": "assets/img/news/2026-11-13-intel-desktop-marktanteil.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.522Z"}, "id": "2026-11-13-huang-kongress-anhoerung", "datum": "2026-11-13T14:09:00+01:00", "label": "News", "bereich": "hardware", "themen": ["NVIDIA"], "kategorie": "Unternehmen", "titel": "US-Kongress lädt Ex-Nvidia-Chef Jensen Huang mit Subpoena-Drohung vor, Trump schlägt Tim Cook als Nachfolger vor", "schlagzeile": "Kongress droht Huang mit Vorladung – Trump will Tim Cook als Nvidia-Chef", "kurz": "Drei Ausschüsse des US-Repräsentantenhauses wollen Jensen Huang Anfang Dezember befragen und drohen bei Nichterscheinen mit einer Vorladung. Zusätzlich soll er öffentlich vor dem Bankenausschuss des Senats aussagen. US-Präsident Trump empfiehlt unterdessen Apples Tim Cook als neuen Nvidia-Chef.", "zusammenfassung": "Der Druck auf den zurückgetretenen Nvidia-Gründer Jensen Huang wächst weiter. Laut PC Gamer haben die Vorsitzenden dreier Ausschüsse des US-Repräsentantenhauses Huang und Nvidias Chefjuristen Tim Teter zu nichtöffentlichen, protokollierten Befragungen am 1. und 2. Dezember geladen. Kommen die beiden nicht, droht eine Vorladung per Subpoena. Themen sind der mutmaßliche Schmuggel von KI-Chips, die Nutzung von Nvidia-Produkten durch gegnerische Militärs und Berichte über eine Einflussnahme auf US-Exportkontrollen, unter anderem rund um die Firma MegaSpeed aus Singapur. Ein früheres Schreiben vor Huangs Rücktritt war noch deutlich freundlicher formuliert. Zusätzlich hat Senator Tim Scott Huang für den 3. Dezember zu einer öffentlichen Anhörung im Bankenausschuss des Senats geladen, ebenso Handelsminister Howard Lutnick. Laut BBC, zitiert von PC Gamer, ist Huang bereit, vor dem Kongress zu erscheinen. Parallel dazu hat US-Präsident Donald Trump auf Truth Social einen Wunschnachfolger genannt: Tim Cook, der Apple-Chef bis September war und jetzt Executive Chairman ist, berichtet Golem. Entscheiden wird darüber aber der Nvidia-Verwaltungsrat, der interne und externe Kandidaten prüfen will. Bis dahin führt Finanzchefin Colette Kress das Unternehmen kommissarisch. Ob Cook überhaupt Interesse hat, ist nicht bekannt.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/clear-national-security-concerns-that-need-to-be-addressed-immediately-new-letters-to-jensen-huang-from-congress-strike-a-tougher-tone-for-the-ex-nvidia-ceo/"}, "weitere_links": [{"name": "Golem.de", "url": "https://www.golem.de/news/nvidia-chefposten-trump-empfiehlt-tim-cook-als-nachfolger-von-jensen-huang-2611-215166.html"}], "tags": ["NVIDIA", "Jensen Huang", "US-Kongress", "Exportkontrollen", "Tim Cook"], "bild": {"datei": "assets/img/news/2026-11-13-huang-kongress-anhoerung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.470Z"}, "id": "2026-11-13-november-patch-druck-aktivierung", "datum": "2026-11-13T13:27:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "Microsoft bestätigt: November-Updates für Windows verursachen Druckfehler und Aktivierungsprobleme", "schlagzeile": "Windows-Patch im November: Drucken und Aktivierung machen Ärger", "kurz": "Microsoft hat zwei neue Probleme mit den November-Sicherheitsupdates bestätigt. Dokumente mit unsichtbaren Bildern lassen sich teils nicht drucken, und bestimmte Aktivierungsbefehle scheitern mit Fehler 0x80041008. Ein Fix für die Aktivierung soll in den nächsten Tagen kommen.", "zusammenfassung": "Der November-Patchday sorgt für weitere Probleme. Laut BleepingComputer hat Microsoft bestätigt, dass Drucken nach den Updates fehlschlagen kann. Betroffen sind Dokumente mit Bildern, die bei der gewählten Druckauflösung eine Höhe oder Breite von null haben. Solche unsichtbaren Bilder stecken etwa in Wasserzeichen oder Layout-Ankern von Word-Dokumenten. Das Problem betrifft vor allem den Druck über die Windows-Grafikschnittstelle GDI, ab Windows 10 und Windows Server 2016. Zusätzlich scheitern Aktivierungsbefehle über das Tool slmgr.vbs mit dem Fehler 0x80041008. Das betrifft vor allem Firmen, die Aktivierung und KMS-Server automatisieren. Bereits aktivierte Geräte bleiben laut Microsoft aktiviert. Ein Fix soll in den kommenden Tagen erscheinen, bis dahin hilft nur der Business-Support. Für das Druckproblem nennt der Bericht noch keinen Termin. Diese Woche hatte Microsoft außerdem bestätigt, dass die November-Updates auf Systemen mit dem Oktober-Vorschauupdate nicht installiert werden. Privatnutzer sind vor allem vom Druckfehler betroffen.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-says-november-security-updates-cause-printing-issues/"}, "weitere_links": [{"name": "BleepingComputer (Aktivierung)", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-confirms-windows-activation-failures-after-november-updates/"}], "tags": ["Windows 11", "Windows 10", "Patchday", "Drucken", "Aktivierung"], "bild": {"datei": "assets/img/news/2026-11-13-november-patch-druck-aktivierung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:37.866Z"}, "id": "2026-11-13-xbox-25-konsole-ausverkauft", "datum": "2026-11-13T13:23:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Xbox"], "kategorie": "Konsolen", "titel": "Xbox Series X zum 25. Jubiläum in Sekunden ausverkauft, Scalper verlangen bis zu 2.500 Dollar", "schlagzeile": "Jubiläums-Xbox in Sekunden weg – Scalper verlangen bis zu 2.500 Dollar", "kurz": "Die transparent-grüne Xbox Series X zum 25. Jubiläum war im Microsoft Store innerhalb von Sekunden ausverkauft. Fans sind wütend über die knappe Stückzahl und fehlende Schutzmaßnahmen gegen Bots. Auf eBay wurden Konsolen laut IGN schon für 1.500 bis 2.500 Dollar verkauft.", "zusammenfassung": "Der Verkaufsstart der limitierten Xbox Series X zum 25. Geburtstag der Marke ist für viele Fans schiefgegangen. Laut IGN war die Konsole im Microsoft Store innerhalb von Sekunden vergriffen. Microsoft hatte vorab nur eine begrenzte Stückzahl angekündigt, die je nach Markt und Händler unterschiedlich ausfällt. Die Konsole kostet regulär 999 Dollar. GameStop bot sein Kontingent laut IGN zeitweise für 4.950 Dollar an, auch das ist inzwischen ausverkauft. Auf eBay hat IGN Dutzende bereits verkaufte Exemplare für 1.500 bis 2.500 Dollar gefunden. Fans kritisieren vor allem, dass Microsoft keine Warteschlange und keine Beschränkung auf echte Xbox-Konten eingeführt hat. Manche berichten, der Warenkorb sei während des Kaufs einfach verschwunden. Xbox-Chefin Asha Sharma hatte im Oktober gesagt, die Nachfrage nach Konsolen sei größer als das Angebot. Ob Microsoft nachliefert, ist nicht bekannt. Preise und Verfügbarkeit in Europa nennt der Bericht nicht.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/xbox-25th-anniversary-console-stock-sells-out-in-seconds-sparking-fan-fury-over-scalping-and-limited-supply"}, "weitere_links": [], "tags": ["Xbox", "Xbox Series X", "25 Jahre Xbox", "Scalper"], "bild": {"datei": "assets/img/news/2026-11-13-xbox-25-konsole-ausverkauft.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T21:54:38.378Z"}, "id": "2026-11-13-gdc-ps6-helix-ki", "datum": "2026-11-13T11:20:00+01:00", "label": "News", "bereich": "games", "themen": ["PlayStation", "Xbox"], "kategorie": "Spielebranche", "titel": "GDC-Umfrage: 10 Prozent der Entwickler arbeiten schon an PS6-Spielen, 8 Prozent an Project Helix, 40 Prozent nutzen generative KI", "schlagzeile": "Schon in Arbeit: Jeder zehnte Entwickler baut ein Spiel für die PS6", "kurz": "In der GDC-Umfrage sagen 10 Prozent der Entwickler mit laufendem Projekt, dass ihr Spiel für die nächste PlayStation geplant ist. 8 Prozent nennen Microsofts Project Helix. Außerdem nutzen 40 Prozent generative KI, aber 55 Prozent halten sie für schädlich.", "zusammenfassung": "Der neue State of the Game Industry Report der Game Developers Conference zeigt, dass die nächste Konsolengeneration schon in Arbeit ist. Laut Golem geben 10 Prozent der Befragten mit einem laufenden Projekt an, dass ihr Spiel für Sonys kommende PlayStation vorgesehen ist. 8 Prozent nennen Microsofts nächste Xbox mit dem Codenamen Project Helix. Mehrfachnennungen waren möglich, wie viele verschiedene Spiele das sind, ist also unklar. Wichtigste Plattform bleibt der PC mit 81 Prozent, gefolgt von PS5 mit 45 und Xbox Series X/S mit 37 Prozent. Das Steam Deck kommt auf 32, die Switch 2 auf 29 und Valves Steam Machine auf 21 Prozent. Zweites großes Thema ist KI: Laut Eurogamer nutzen 40 Prozent der Befragten generative KI bei der Arbeit, vier Prozentpunkte mehr als im Vorjahr. Gleichzeitig sagen 55 Prozent, dass KI der Spielebranche schadet. In AAA-Studios fühlen sich 27 Prozent zur KI-Nutzung gedrängt oder ermutigt, bei Indie-Entwicklern nur 9 Prozent. Zur Zahl der Befragten nennt Golem mehr als 2.600, Eurogamer mehr als 2.300. Die Entlassungszahlen aus derselben Umfrage standen bereits gestern im Ticker.", "quelle": {"name": "Golem.de", "url": "https://www.golem.de/news/next-gen-jeder-zehnte-entwickler-arbeitet-an-spiel-fuer-playstation-6-2611-215177.html"}, "weitere_links": [{"name": "Eurogamer", "url": "https://www.eurogamer.net/gdc-report-40-percent-developers-generative-ai"}], "tags": ["GDC", "PS6", "Project Helix", "Xbox", "Generative KI", "Spielebranche"], "bild": {"datei": "assets/img/news/2026-11-13-gdc-ps6-helix-ki.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.343Z"}, "id": "2026-11-13-microsoft-365-grossstoerung", "datum": "2026-11-13T05:50:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Software", "titel": "Großstörung bei Microsoft 365: Outlook, Exchange, Teams und Copilot stundenlang gestört, Erholung nur schrittweise", "schlagzeile": "Outlook und Teams down: Microsoft 365 kämpft mit Großstörung", "kurz": "Seit Donnerstagabend ist Microsoft 365 weltweit massiv gestört, betroffen sind unter anderem Outlook, Exchange Online, Teams und Copilot. Laut Microsoft sind zahlreiche Server unerwartet ausgefallen, ein Cyberangriff sei es nicht. Am Freitagmorgen zeigt Microsofts Statusseite weiter eine Dienstbeeinträchtigung; eine durchgehende Erholung ist noch nicht erreicht.", "zusammenfassung": "Am Donnerstag, dem 12. November, kam es zu einer der größten Microsoft-365-Störungen der letzten Zeit. Laut BleepingComputer begann der Vorfall mit der Kennung MO1550821 um 13:26 Uhr US-Ostküstenzeit, in Mitteleuropa also am Abend. Betroffen waren unter anderem Exchange Online und Outlook, Teams, SharePoint Online, Microsoft 365 Copilot und Defender XDR, und zwar in allen Regionen. Microsoft nennt als Ursache eine Reihe von Servern, die unerwartet nicht mehr verfügbar waren und so die übrige Infrastruktur überlasteten. Das Unternehmen stoppte alle Deployments, verteilte den Datenverkehr um und startete Server neu. Laut Neowin wirkten erste Gegenmaßnahmen nicht wie erhofft, ein Kernprozess auf den betroffenen Servern sei überlastet gewesen. Microsoft-Manager Charles Lamanna entschuldigte sich und erklärte, es gebe keine Hinweise auf einen Angriff. In der Nacht meldete Microsoft eine langsame Erholung, am Freitagmorgen zeigt die offizielle Statusseite aber weiter eine Dienstbeeinträchtigung; Microsoft spricht nur von teilweisem Erfolg, eine durchgehende Erholung ist noch nicht erreicht. Firmenkunden können laut Windows Latest über das Microsoft-365-Admin-Center eine SLA-Gutschrift beantragen. Ob und in welcher Höhe es Geld zurückgibt, hängt von der tatsächlich betroffenen Nutzerzahl und Dauer ab. Privatnutzer von Outlook.com haben in der Regel keinen Anspruch.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/microsoft/massive-microsoft-365-outage-disrupts-outlook-teams-copilot-worldwide/"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/microsoft-regrets-outlook-exchange-sharepoint-outage-after-admitting-it-still-cant-fix/"}, {"name": "heise online", "url": "https://www.heise.de/news/Microsoft-365-Stoerung-Serverausfaelle-legen-Teams-Exchange-und-Copilot-lahm-11523565.html"}, {"name": "Golem.de", "url": "https://www.golem.de/news/cloud-serverausfaelle-stoeren-outlook-und-microsoft-365-2611-215165.html"}, {"name": "Windows Latest (SLA-Gutschrift)", "url": "https://www.windowslatest.com/2026/11/13/microsoft-365-outage-you-may-get-money-off-your-bill-if-you-use-it-for-work-but-youll-have-to-ask-microsoft-for-it-as-a-server-failure-takes-down-outlook-teams-and-exchange/"}], "tags": ["Microsoft 365", "Outlook", "Teams", "Exchange", "Störung"], "bild": {"datei": "assets/img/news/2026-11-13-microsoft-365-grossstoerung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.568Z"}, "id": "2026-11-13-nvidia-doj-ermittlungen", "datum": "2026-11-13T05:03:00+01:00", "label": "News", "bereich": "hardware", "themen": ["Nvidia"], "kategorie": "Unternehmen", "titel": "Berichte: US-Justizministerium ermittelt nach Huang-Rücktritt gegen Nvidia, Supermicro und Megaspeed", "schlagzeile": "Nach Huangs Rücktritt: US-Justiz soll Ermittlungen gegen Nvidia starten", "kurz": "Laut Semafor haben mehrere Abteilungen des US-Justizministeriums Untersuchungen eingeleitet, die Nvidia, Supermicro und Megaspeed betreffen. Im Kern geht es um mutmaßlich nach China gelieferte KI-Beschleuniger. Anzeichen für eine Anklage gegen Nvidia oder Ex-CEO Jensen Huang gibt es bisher nicht.", "zusammenfassung": "Einen Tag nach dem Rücktritt von Jensen Huang wird es für Nvidia nicht ruhiger. Laut heise berichtet Semafor unter Berufung auf zwei Regierungsvertreter, dass verschiedene Abteilungen des US-Justizministeriums Untersuchungen eingeleitet haben. Betroffen sind demnach Nvidia, der Serverhersteller Supermicro und das in Singapur ansässige Unternehmen Megaspeed. Megaspeed wird vorgeworfen, Nvidia-KI-Beschleuniger trotz US-Exportbeschränkungen nach China geliefert zu haben. Im Mittelpunkt soll die Rolle einer früheren leitenden Megaspeed-Mitarbeiterin stehen, mit der Huang eine Beziehung gehabt haben soll. Laut heise gibt es bislang keine Anzeichen, dass das Ministerium Anklage gegen Nvidia oder Huang erheben wird. Nvidia und das Justizministerium wollten sich nicht äußern. Supermicro erklärte, Megaspeed sei nie Kunde gewesen, und sagte Kooperation mit den Behörden zu. Zusätzlich berichtet Reuters von einer weiteren Beziehung Huangs zu einer Nvidia-Mitarbeiterin. Für Käufer von GeForce-Karten hat das vorerst keine bekannten Folgen. Am 17. November legt Nvidia seine Quartalszahlen vor, dort dürfte das Thema zur Sprache kommen.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Berichte-ueber-kartellrechtliche-Pruefung-Nvidias-und-weitere-Affaere-des-Ex-Chefs-11523636.html"}, "weitere_links": [{"name": "PC Games Hardware (Quartalszahlen am 17.11.)", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Geforce-62124-Dawn-of-War-4-Huang-Ruecktritt-1559859/"}], "tags": ["Nvidia", "Jensen Huang", "Justizministerium", "Megaspeed", "Export"], "bild": {"datei": "assets/img/news/2026-11-13-nvidia-doj-ermittlungen.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.608Z"}, "id": "2026-11-13-codex-radeon-r600-fix", "datum": "2026-11-13T02:41:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "AMD", "Treiber"], "kategorie": "Linux", "titel": "Mit Hilfe von OpenAI Codex: Fast 20 Jahre alter Videodekoder-Fehler bei Radeon-HD-2000/3000-Karten unter Linux behoben", "schlagzeile": "KI findet uralten Radeon-Bug: Fix für HD 2000/3000 kommt in Linux 7.5", "kurz": "Ein Hobby-Entwickler hat mit Hilfe von OpenAI Codex einen Videofehler bei fast 20 Jahre alten Radeon-GPUs der R600-Ära gefunden und behoben. Der Patch hält Videodaten im VRAM und landet in Linux 7.5. AMD pflegt diese Karten seit Jahren nicht mehr.", "zusammenfassung": "Unter den AMD-Grafiktreiber-Patches für Linux 7.5 steckt laut Phoronix eine ungewöhnliche Korrektur. Sie betrifft den Videodekoder UVD von Radeon-Karten der R600-Generation, also der Radeon HD 2000 und 3000 von vor fast 20 Jahren. Der Entwickler Ted Bullock bemerkte auf einem alten iMac mit RV610-Chip beschädigte Videobilder. Die Fehler traten auf, wenn der Dekoder komprimierte Videodaten aus dem Arbeitsspeicher las, während die GPU gleichzeitig zeichnete. Lagen die Daten im Grafikspeicher, liefen die Videos sauber. Sein Patch hält die UVD-Puffer deshalb für die Chips RV610, RV620, RV630, RV635 und RV670 im VRAM. Getestet hat er nur auf seiner eigenen Hardware, für die anderen Chips fehlt noch eine Bestätigung. Bullock schreibt offen, dass er OpenAI Codex bei Analyse, Tests und Patch genutzt hat. Der Patch wurde angenommen und kommt mit Linux 7.5. Die Merge-Phase dafür beginnt um den Jahreswechsel.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/Codex-R600-UVD-FIx-Linux-7.5"}, "weitere_links": [], "tags": ["Linux", "Radeon", "AMD", "Treiber", "KI", "Retro"], "bild": {"datei": "assets/img/news/2026-11-13-codex-radeon-r600-fix.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.516Z"}, "id": "2026-11-13-windhawk-patchday-fix", "datum": "2026-11-13T01:44:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "November-Patchday legt Windhawk-Mods lahm, Entwickler liefert Workaround", "schlagzeile": "Patchday legt Windhawk-Mods lahm – so laufen sie wieder", "kurz": "Nach dem November-Update KB5132061 funktionieren viele Mods des Anpassungs-Tools Windhawk nicht mehr, vor allem für Taskleiste und Explorer. Grund sind fehlende Debug-Symbole von Microsoft. Der Entwickler hat einen Workaround veröffentlicht, Mods einfach aus- und wieder einschalten.", "zusammenfassung": "Windhawk ist ein beliebtes Tool, mit dem sich Windows per Mods anpassen lässt, etwa die Taskleiste oder der Datei-Explorer. Seit dem November-Patchday melden Nutzer laut Neowin, dass ihre Mods nicht mehr laden. Das Problem tauchte am 10. November kurz nach dem Update KB5132061 in einem GitHub-Eintrag auf, betroffen sind Windows 11 und Windows 10. Windhawk-Entwickler Michael Maltsev bestätigte den Fehler. Ursache ist, dass Microsoft einige Debug-Symbole für die neuen Windows-Versionen nicht veröffentlicht hat. Windhawk braucht diese Symbole, um die Stellen im System zu finden, die eine Mod verändert. Laut Maltsev ist das nicht das erste Mal, dass Microsoft Symbole verspätet oder gar nicht bereitstellt. Als Lösung gibt es eine manuelle Zuordnung über den Symbol-Cache von Windhawk, die die meisten betroffenen Mods wieder zum Laufen bringt. Sie ist bereits im Online-Cache enthalten. Wer noch Probleme hat, sollte die betroffenen Mods in Windhawk deaktivieren und wieder aktivieren.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/patch-tuesday-updates-break-popular-windows-customization-tool-windhawk-but-theres-a-fix/"}, "weitere_links": [], "tags": ["Windows 11", "Windows 10", "Windhawk", "KB5132061", "Patchday"], "bild": {"datei": "assets/img/news/2026-11-13-windhawk-patchday-fix.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.684Z"}, "id": "2026-11-13-wolfenstein-3-offiziell", "datum": "2026-11-13T01:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Xbox bestätigt: Wolfenstein 3 ist bei MachineGames offiziell in Produktion", "schlagzeile": "Endlich offiziell: Wolfenstein 3 ist bei MachineGames in Arbeit", "kurz": "Xbox hat bei der FanFest zum 25-jährigen Jubiläum bestätigt, dass Wolfenstein 3 bei MachineGames in Produktion ist. Die Sprecher von B.J. Blazkowicz und Grace Walker sind wieder dabei. Einen Termin oder Plattformen gibt es noch nicht.", "zusammenfassung": "Lange wurde spekuliert, jetzt ist es offiziell: Wolfenstein 3 ist in Produktion. Xbox-Chefin Asha Sharma bestätigte das Projekt auf X im Rahmen der Xbox FanFest in Seattle. Entwickelt wird es erneut vom schwedischen Studio MachineGames, das zuletzt Indiana Jones und der Große Kreis gemacht hat. MachineGames zeigte dazu eine Seite aus dem Drehbuch mit dem Satz „His reputation precedes him“. Auf einem Foto aus dem Motion-Capture-Studio sind Brian Bloom und Debra Wilson zu sehen, die erneut B.J. Blazkowicz und Grace Walker spielen. Der Vorgänger Wolfenstein 2: The New Colossus erschien 2017. Studiochef Jerk Gustafsson hatte schon früher erklärt, B.J.s Geschichte sei immer als Trilogie geplant gewesen. Einen Trailer, Termin oder Plattformen hat Xbox noch nicht genannt. Parallel entsteht bei Amazon eine Wolfenstein-Serie.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/wolfenstein-3-confirmed-to-be-in-development-at-machinegames"}, "weitere_links": [{"name": "IGN Deutschland", "url": "https://de.ign.com/wolfenstein-iii/157214/es-ist-offiziell-wolfenstein-3-ist-gerade-bei-machinegames-in-entwicklung"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2121030203439010175"}], "tags": ["Wolfenstein 3", "MachineGames", "Xbox", "Bethesda", "Shooter"], "bild": {"datei": "assets/img/news/2026-11-13-wolfenstein-3-offiziell.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.251Z"}, "id": "2026-11-13-pocketpair-gta6-urlaub", "datum": "2026-11-12T23:08:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "Palworld-Studio Pocketpair schickt seine Belegschaft zum GTA-6-Start auf „Dienstreise nach Vice City“", "schlagzeile": "GTA-6-Fieber: Palworld-Studio gibt allen zum Launch frei", "kurz": "Das Palworld-Studio Pocketpair stellt alle Mitarbeitenden, die GTA 6 spielen wollen, in der Launch-Woche frei. Offiziell heißt das „dringende Dienstreise nach Vice City“. Auch Logitech und weitere Firmen geben zum Launch frei.", "zusammenfassung": "GTA 6 erscheint am 19. November für Konsolen, und manche Firmen planen schon um. Das japanische Studio Pocketpair, bekannt für Palworld, hat auf X eine augenzwinkernde Mitteilung veröffentlicht. Alle Mitarbeitenden, die GTA 6 spielen wollen, werden vom 19. bis 23. November von ihren Aufgaben befreit und zu einer „Dienstreise nach Vice City“ ermutigt. Da in den Zeitraum ein Wochenende fällt, sind es effektiv drei freie Arbeitstage. Pocketpair betont, dass die Updates für Palworld und Craftopia trotzdem wie geplant kommen sollen. Laut PC Gamer ist das Studio nicht allein: Logitech gibt seinen rund 7.000 Beschäftigten am 19. November mit dem „Logi Game Day“ frei, wobei jedes Spiel erlaubt ist. Auch der US-Tuningteilehersteller Burger Motorsports und der kanadische Lkw-Hersteller Edison Motors haben freie Tage zum Launch angekündigt. Eine PC-Version von GTA 6 hat Rockstar weiterhin nicht terminiert.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/grand-theft-auto/palworld-developer-pocketpair-gives-employees-time-off-for-a-5-day-business-trip-in-vice-city-when-gta-6-launches/"}, "weitere_links": [], "tags": ["GTA 6", "Pocketpair", "Palworld", "Logitech"], "bild": {"datei": "assets/img/news/2026-11-13-pocketpair-gta6-urlaub.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.975Z"}, "id": "2026-11-13-og-xbox-pc-21-spiele", "datum": "2026-11-12T23:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox", "PC"], "kategorie": "Spiele", "titel": "Xbox bringt 21 weitere Spiele der ersten Xbox auf den PC, vier Klassiker erhalten erstmals Erfolge", "schlagzeile": "KOTOR, Morrowind & Co.: 21 Ur-Xbox-Klassiker laufen jetzt am PC", "kurz": "Über die Abwärtskompatibilität auf dem PC laufen jetzt 21 weitere Spiele der ersten Xbox, insgesamt sind es 25. Dabei sind unter anderem Morrowind, beide KOTOR-Teile und TimeSplitters 2. Vier Spiele bekommen erstmals Erfolge.", "zusammenfassung": "Vier Monate nach dem Start der Abwärtskompatibilität für Spiele der ersten Xbox auf dem PC legt Microsoft nach. 21 weitere Titel sind hinzugekommen, damit umfasst der PC-Katalog nun 25 Spiele. Dazu gehören laut VGC und Thurrott unter anderem The Elder Scrolls III: Morrowind, Star Wars: Knights of the Old Republic I und II, Jedi Academy, Jedi Outcast, TimeSplitters 2 und Crimson Skies. Morrowind und Grabbed by the Ghoulies sind auch im Game Pass enthalten. Erstmals gibt es Erfolge für vier Klassiker: beide KOTOR-Teile, Blinx: The Time Sweeper und Conker: Live and Reloaded. Laut Xbox lassen sie sich am PC und auf der Konsole freischalten. Xbox-Vizepräsident Jason Ronald schreibt außerdem, die ersten vier Spiele liefen jetzt stabiler und schneller, und alle Titel unterstützten Maus und Tastatur. Weitere Spiele sollen folgen. Die Ankündigung gehört zur Xbox FanFest rund um das 25-jährige Jubiläum am 15. November.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/uncategorised/21-original-xbox-games-are-now-on-pc-via-backward-compatibility/"}, "weitere_links": [{"name": "Thurrott.com", "url": "https://www.thurrott.com/games/xbox/343819/microsoft-brings-21-more-og-xbox-games-to-pc-via-backward-compatibility"}, {"name": "Xbox auf X", "url": "https://x.com/XBOX/status/2120986769974083713"}], "tags": ["Xbox", "Abwärtskompatibilität", "PC", "KOTOR", "Morrowind", "Retro"], "bild": {"datei": "assets/img/news/2026-11-13-og-xbox-pc-21-spiele.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.431Z"}, "id": "2026-11-13-geforce-621-24", "datum": "2026-11-12T23:00:00+01:00", "label": "News", "bereich": "software", "themen": ["GPU", "Nvidia", "Treiber"], "kategorie": "Treiber", "titel": "Nvidia GeForce 621.24 WHQL: Game Ready für Dawn of War 4 und Assetto Corsa Rally, Vorbereitung auf DLSS 5 in Where Winds Meet", "schlagzeile": "GeForce 621.24: Neuer Treiber für Dawn of War 4 und DLSS 5", "kurz": "Nvidia hat den GeForce-Treiber 621.24 WHQL veröffentlicht, nur acht Tage nach 621.14. Er ist Game Ready für Dawn of War 4 und Assetto Corsa Rally und bereitet DLSS 5 in Where Winds Meet vor. Behoben werden nur zwei Fehler, die vor allem Profi- und Videoanwendungen betreffen.", "zusammenfassung": "Mit GeForce 621.24 WHQL liefert Nvidia den vierten Treiber innerhalb von 22 Tagen. Im Mittelpunkt steht laut PCGH Warhammer 40.000: Dawn of War 4, das am 3. Dezember erscheint, Käufer der Commander Edition dürfen schon am 30. November spielen. Auch Assetto Corsa Rally ist optimiert, die Rallye-Simulation soll am 19. November ein Update mit DLSS 4.5 und Dynamic Multi Frame Generation erhalten. Diese Bildgenerierung setzt eine GeForce RTX 5000 voraus. Am 23. November soll Where Winds Meet DLSS 5 mit neuem Neural Rendering bekommen, laut PCGH nur für Blackwell-Karten und RTX-Spark-Systeme. Behoben wurden zwei Fehler: Der OptiX-Denoiser in Chaos Vantage konnte bei hohen Auflösungen versagen, und H.265-Videos von DJI im D-Log-Profil wurden in Windows-Apps mit falschen Farben gezeigt. Offene Fehler nennen die Release Notes zum Start nicht. Neu ist außerdem CUDA 13.5. Unterstützt werden Desktop-Karten von der GTX 1630 bis zur RTX 5090, Pascal und Maxwell sind nicht mehr dabei. Wer keines der genannten Spiele spielt, muss nicht sofort aktualisieren.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Geforce-62124-Dawn-of-War-4-Huang-Ruecktritt-1559859/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354746/nvidia-geforce-621-24-whql-game-ready-drivers-released"}], "tags": ["Nvidia", "GeForce", "Treiber", "DLSS 5", "Dawn of War 4"], "bild": {"datei": "assets/img/news/2026-11-13-geforce-621-24.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.458Z"}, "id": "2026-11-13-amd-china-gpu-kuerzung", "datum": "2026-11-12T22:14:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["GPU", "AMD"], "kategorie": "Grafikkarten", "titel": "Bericht: AMD soll die Lieferungen von Gaming-GPUs in China seit Oktober um 20 bis 50 Prozent gekürzt haben", "schlagzeile": "Leak: Kürzt AMD die Radeon-Lieferungen in China um bis zu 50 %?", "kurz": "AMD soll seine Gaming-GPU-Lieferungen an Boardpartner in China seit Oktober um 20 bis 50 Prozent gekürzt haben. Das berichtet das chinesische Forum Board Channels, die Knappheit soll bis Januar anhalten. AMD hat sich dazu nicht geäußert.", "zusammenfassung": "Laut einem Beitrag im chinesischen Branchenforum Board Channels vom 12. November hat AMD die Menge an Gaming-Grafikchips für seine Boardpartner in China seit Beginn des vierten Quartals deutlich reduziert. Die Rede ist von mindestens 20 bis 50 Prozent weniger, die monatlichen Zuteilungen sollen weiter sinken. Die Lage sei damit inzwischen ähnlich knapp wie bei Nvidia. Die Quelle erwartet, dass das Angebot bis Januar sehr knapp bleibt. Radeon-Preise in China sollen jedes Quartal steigen, begründet wird das mit höheren Kosten für Speicher und GPUs. AMD soll den Preis seiner Pakete aus GPU und GDDR6 in diesem Monat erneut anheben, nach einer Erhöhung im Oktober. TechPowerUp weist darauf hin, dass der Bericht keine konkreten Stückzahlen, betroffenen Modelle oder Gründe nennt. Er betrifft zudem nur China, ob Europa oder die USA ähnliche Kürzungen sehen, ist offen. AMD hat den Bericht nicht kommentiert. Die Angaben sind unbestätigt und sollten als Hinweis auf die Marktlage verstanden werden, nicht als Fakt.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354757/amd-reportedly-cuts-gaming-gpu-supply-in-china-by-up-to-50"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Ursprung ist ein Beitrag im chinesischen Branchenforum Board Channels (via VideoCardz, TechPowerUp); keine Zahlen zu Modellen oder Stückzahlen, von AMD nicht bestätigt. Board Channels lag bei Liefer- und Preisthemen schon öfter richtig."}, "tags": ["AMD", "Radeon", "China", "Preise", "Lieferengpass"], "bild": {"datei": "assets/img/news/2026-11-13-amd-china-gpu-kuerzung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.881Z"}, "id": "2026-11-13-fable-gameplay-4-minuten", "datum": "2026-11-12T21:16:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Xbox zeigt vier Minuten neues Gameplay aus Fable, Release am 23. Februar 2027", "schlagzeile": "Vier Minuten neues Fable: Kämpfe, Magie und ein düsterer Wald", "kurz": "Xbox hat vier Minuten neues Gameplay aus dem Fable-Reboot von Playground Games veröffentlicht. Zu sehen sind Nahkampf, Fernkampf und Magie, aufgenommen auf dem PC in Ultra-Einstellungen. Fable erscheint am 23. Februar 2027 für Xbox Series X|S, PS5 und PC.", "zusammenfassung": "Zum 25-jährigen Xbox-Jubiläum hat Xbox-Chefin Asha Sharma ein neues Gameplay-Video zu Fable geteilt. Die vier Minuten zeigen laut IGN vor allem Kämpfe mit Schwert, Fernkampfwaffen und Magie. Aufgenommen wurde auf dem PC mit Ultra-Grafikeinstellungen. Inhaltlich geht es um den Helden von Briar Hill, der mit einer einheimischen Heldin im Wald Deepwood seltsamen magischen Vorfällen nachgeht. Entwickelt wird das Spiel von Playground Games, bekannt für die Forza-Horizon-Reihe. Fable war ursprünglich für diesen Herbst geplant und wurde auf den 23. Februar 2027 verschoben. Es erscheint für Xbox Series X|S, PS5 und PC, auf Steam ist es bereits vorbestellbar. Die Reaktionen sind gemischt: PC Gamer findet, das Video wirke düster und eher gewöhnlich und erinnere wenig an die bunte, schräge Fable-Reihe. In den YouTube-Kommentaren fiel das Echo dagegen überwiegend positiv aus. Ein kurzer Clip zeigt naturgemäß nur einen kleinen Ausschnitt des Spiels.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/fable-drops-four-minutes-of-new-gameplay"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/rpg/new-4-minute-fable-gameplay-trailer-shows-a-game-that-doesnt-look-much-like-fable/"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120955243790057796"}], "tags": ["Fable", "Playground Games", "Xbox", "PS5", "Rollenspiel"], "bild": {"datei": "assets/img/news/2026-11-13-fable-gameplay-4-minuten.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.789Z"}, "id": "2026-11-13-id-software-neues-spiel", "datum": "2026-11-12T21:00:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "id Software bestätigt neues Spiel unter Regie von Hugo Martin, Doom: The Dark Ages bekommt Slaughter Mode", "schlagzeile": "Doom-Macher id Software arbeitet schon am nächsten Spiel", "kurz": "id Software arbeitet an einem neuen Spiel, das wieder Hugo Martin als Game Director leitet. Welche Marke es wird, ist offen. Zuvor bekommt Doom: The Dark Ages am 16. November einen kostenlosen Slaughter Mode für Besitzer der Revelations-Erweiterung.", "zusammenfassung": "Xbox-Chefin Asha Sharma hat während der Xbox FanFest bestätigt, dass id Software bereits am nächsten Spiel arbeitet. Das Studio selbst schrieb auf X, das Projekt entstehe in den Teams in Texas und Frankfurt, Game Director sei erneut Hugo Martin. Martin war Creative Director bei Doom (2016) und Doom Eternal sowie Game Director von Doom: The Dark Ages. Ob es ein neues Doom, ein Quake oder etwas ganz anderes wird, verrät id nicht. Laut id wird es noch einige Zeit dauern, bis es mehr zu zeigen gibt, das Projekt steht also wohl noch am Anfang. VGC erinnert daran, dass id Software zuletzt stark von den Xbox-Entlassungen betroffen war, insgesamt verloren dort 136 Menschen ihre Jobs. Zuvor kommt am 16. November der Slaughter Mode für Doom: The Dark Ages. Der endlose Einzelspieler-Modus ist ein kostenloses Update für alle, die die Erweiterung Revelations besitzen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/doom-developer-id-software-confirms-work-on-new-game-will-be-directed-by-hugo-martin"}, "weitere_links": [{"name": "VGC", "url": "https://www.videogameschronicle.com/news/id-software-confirms-its-working-on-a-new-game-after-layoffs/"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/fps/doom-studio-id-software-confirms-its-working-on-a-new-game/"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120969774062817747"}], "tags": ["id Software", "Doom", "Hugo Martin", "Xbox", "Shooter"], "bild": {"datei": "assets/img/news/2026-11-13-id-software-neues-spiel.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:16.320Z"}, "id": "2026-11-13-cmp170hx-80gb-hack", "datum": "2026-11-12T20:52:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia", "KI"], "kategorie": "Grafikkarten", "titel": "Hardware-Hack: Nvidias Mining-Karte CMP 170HX lässt sich auf 80 GB HBM2e und bis zu 126 SMs freischalten", "schlagzeile": "Aus 8 werden 80 GB: Hack macht Nvidias Mining-Karte zur KI-Karte", "kurz": "Eine Entwicklerin hat bei Nvidias alter Mining-Karte CMP 170HX per Spannungs-Trick die vollen 80 GB HBM2e statt 8 GB freigeschaltet. Auch bis zu 126 statt 70 Recheneinheiten ließen sich aktivieren. Der Umbau erfordert Löten, ist dauerhaft und kann die Karte zerstören.", "zusammenfassung": "Die CMP 170HX hat Nvidia 2021 als reinen Ethereum-Beschleuniger verkauft, im Inneren steckt aber derselbe GA100-Chip wie in der Rechenzentrumskarte A100. Ab Werk sind nur 8 GB der eigentlich verbauten 80 GB HBM2e nutzbar, dazu 70 von 128 Streaming-Multiprozessoren. Mit dem Software-Tool cmpunlocker ließen sich schon seit dem Sommer bis zu 64 GB freischalten. Eine Entwicklerin namens Kate geht mit einem am 10. November veröffentlichten Hardware-Hack weiter: Eine kleine Zusatzplatine mit STM32-Mikrocontroller erzeugt gezielte Spannungseinbrüche und bringt so den eFuse-Controller dazu, gesperrte Einstellungen wieder anzunehmen. Laut ComputerBase lieferten neun von zehn getesteten Karten danach die vollen 80 GB, eine kam auf 64 GB. Je nach Exemplar wurden außerdem 120 bis 126 SMs aktiv. In einem OpenCL-FP16-Test erreichte die umgebaute Karte 85,9 TFLOPS und lag damit vor einer regulären A100 mit 72,5 TFLOPS. Dieser Wert lässt sich laut ComputerBase aber nicht direkt auf echte KI-Anwendungen übertragen. Auch PCIe 4.0 x16 und NVLink sollen sich mit zusätzlichen Anpassungen freischalten lassen. Der Haken: Der Eingriff braucht Lötarbeiten und laut der Entwicklerin zwischen einer und 48 Stunden Versuche. Die Änderungen an den eFuses sind dauerhaft, ein Fehler kann die Karte unbrauchbar machen. Dass auch andere Exemplare so viel funktionsfähige Hardware haben, ist nicht garantiert.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/nvidia-mining-gpu-80-gb-statt-8-gb-vram-und-80-prozent-mehr-kerne-per-hack.100309/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Nvidia-CMP-170HX-A100-Hack-80-GiB-VRAM-Voltage-Glitching-1559861/"}], "tags": ["Nvidia", "CMP 170HX", "GA100", "HBM2e", "Mod", "KI"], "bild": {"datei": "assets/img/news/2026-11-13-cmp170hx-80gb-hack.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.158Z"}, "id": "2026-11-13-game-awards-disney-plus", "datum": "2026-11-12T20:17:00+01:00", "label": "News", "bereich": "games", "themen": [], "kategorie": "Spiele", "titel": "The Game Awards 2026 laufen erstmals auch auf Disney+", "schlagzeile": "The Game Awards 2026 laufen erstmals auch auf Disney+", "kurz": "Die Game Awards 2026 werden erstmals auch auf Disney+ übertragen. Twitch, YouTube und weitere Plattformen bleiben dabei, die Show steigt am 10. Dezember in Los Angeles.", "zusammenfassung": "Die Game Awards bekommen in diesem Jahr einen neuen Partner: Laut IGN wird die Show erstmals auch auf Disney+ gestreamt. Daneben läuft sie wie gewohnt auf Twitch und YouTube sowie unter anderem auf Steam, TikTok, X, Facebook und Kick. Die Verleihung findet am Donnerstag, 10. Dezember, im Peacock Theater in Los Angeles statt. Los geht es um 19:30 Uhr Ostküstenzeit, in Mitteleuropa ist das in der Nacht auf den 11. Dezember um 1:30 Uhr. Moderiert wird wieder von Geoff Keighley. Laut Variety will Disney die Partnerschaft nutzen, um eigene Spiele- und Animationsprojekte zu bewerben. Zu den Favoriten zählt IGN unter anderem Resident Evil Requiem, 007 First Light und das Ocarina-of-Time-Remake. GTA 6 erscheint am 19. November und ist damit gerade noch für die diesjährigen Awards zugelassen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/the-game-awards-2026-are-coming-to-disney"}, "weitere_links": [], "tags": ["The Game Awards", "Disney+", "Geoff Keighley", "GTA 6"], "bild": {"datei": "assets/img/news/2026-11-13-game-awards-disney-plus.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-13T08:06:17.063Z"}, "id": "2026-11-13-halo-ce-firefight", "datum": "2026-11-12T19:46:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox"], "kategorie": "Spiele", "titel": "Halo: Campaign Evolved bekommt diesen Winter Firefight als kostenloses Update", "schlagzeile": "Halo: Campaign Evolved bekommt gratis Firefight-Modus", "kurz": "Das Halo-Remake Campaign Evolved erhält diesen Winter den Firefight-Modus als kostenloses Update. Bis zu vier Spieler kämpfen darin gemeinsam gegen Gegnerwellen. Mehr Details soll es beim Halo Fest Mitte Dezember geben.", "zusammenfassung": "Xbox hat bei der FanFest angekündigt, dass Halo: Campaign Evolved einen Firefight-Modus bekommt. Firefight ist ein kooperativer PvE-Modus für bis zu vier Spieler, der schon in mehreren Halo-Teilen enthalten war. Das Update kommt kostenlos irgendwann in diesem Winter, ein genaues Datum gibt es noch nicht. Besucher der FanFest sollten den Modus laut VGC bereits vor Ort anspielen können. Weitere Details will Xbox beim Halo Fest am 12. und 13. Dezember nennen. Halo: Campaign Evolved ist ein Remake der Kampagne des ersten Halo und erschien im Juli. VGC weist darauf hin, dass das kleiner gewordene Halo Studios nach den Xbox-Entlassungen nur noch bestehende Halo-Spiele betreut. Ein neues Halo entsteht laut VGC bei Activision.", "quelle": {"name": "VGC", "url": "https://www.videogameschronicle.com/news/halo-campaign-evolved-is-getting-firefight-in-a-free-update/"}, "weitere_links": [{"name": "Thurrott.com", "url": "https://www.thurrott.com/games/343808/halo-campaign-evolved-to-get-firefight-mode"}, {"name": "Asha Sharma auf X", "url": "https://x.com/asha_shar/status/2120925412788498530"}], "tags": ["Halo", "Halo Studios", "Xbox", "Koop", "Update"], "bild": {"datei": "assets/img/news/2026-11-13-halo-ce-firefight.webp", "ki_generiert": true}}, {"id": "2026-11-12-amd-26-11-1-ssd-fix", "datum": "2026-11-12T18:42:00+01:00", "label": "News", "bereich": "software", "themen": ["Treiber", "AMD"], "kategorie": "Treiber", "titel": "AMD Adrenalin 26.11.1 behebt das dauerhafte Schreiben auf SSDs", "schlagzeile": "Radeon-Treiber 26.11.1: AMD stoppt endlich das SSD-Dauerschreiben", "kurz": "AMD hat den optionalen Treiber Adrenalin 26.11.1 veröffentlicht. Er behebt offiziell den Fehler, durch den der Treiber im Hintergrund ständig Daten auf die SSD schrieb. Die Liste der bekannten Probleme ist allerdings länger geworden.", "zusammenfassung": "Radeon-Nutzer hatten entdeckt, dass der Adrenalin-Treiber im Hintergrund dauerhaft Daten auf das Laufwerk schreibt, selbst im Leerlauf. Heise warnte, dass das die Lebensdauer von SSDs gefährden kann, zuletzt half nur ein Gratis-Tool aus der Community. Jetzt hat AMD laut Wccftech und Neowin den optionalen Treiber 26.11.1 veröffentlicht, der das Problem offiziell beheben soll. Betroffen waren laut den Versionshinweisen Besitzer von Radeon RX 7000 und RX 9000, auch beim Verschieben oder Vergrößern von Fenstern trat der Fehler auf. Die Liste der bekannten Probleme umfasst neun neue Einträge, vor allem Abstürze und Treiber-Timeouts in einzelnen Spielen wie Cyberpunk 2077 und War Thunder. Auf RX-9000-Karten nennt AMD zudem Bildfehler in Phantom Blade Zero. Wer vom SSD-Problem betroffen ist, sollte das Update installieren und kann das Community-Tool danach entfernen.", "quelle": {"name": "Wccftech", "url": "https://wccftech.com/amd-pushes-excessive-ssd-writes-fix-via-latest-adrenalin-edition-26-11-1-optional-driver/"}, "weitere_links": [{"name": "Neowin", "url": "https://www.neowin.net/news/amd-outs-must-install-26111-emergency-driver-to-fix-drive-bug-that-kept-writing-non-stop/"}, {"name": "heise online", "url": "https://www.heise.de/news/SSD-Lebensdauer-gefaehrdet-AMD-Treiber-verursacht-hohe-Schreiblast-11522544.html"}], "tags": ["AMD", "Adrenalin", "Treiber", "SSD", "Radeon"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.674Z"}, "bild": {"datei": "assets/img/news/2026-11-12-amd-26-11-1-ssd-fix.webp", "ki_generiert": true}}, {"id": "2026-11-12-gdc-umfrage-entlassungen", "datum": "2026-11-12T18:04:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spiele", "titel": "GDC-Umfrage: Jede dritte befragte Person in der Spielebranche wurde in zwei Jahren entlassen", "schlagzeile": "GDC-Umfrage: Jeder dritte Befragte aus der Spielebranche wurde entlassen", "kurz": "In der neuen GDC-Umfrage unter über 2.600 Branchenleuten gaben 34 Prozent an, in den letzten zwei Jahren entlassen worden zu sein. Mehr als die Hälfte davon ist noch ohne Job. Die Stimmung in der Branche ist laut Umfrage schlecht.", "zusammenfassung": "Die 15. Ausgabe der Umfrage „State of the Game Industry“ der GDC hat über 2.600 Branchenleute weltweit befragt, berichtet VGC. 34 Prozent gaben an, in den letzten zwei Jahren entlassen worden zu sein, in den USA sogar 39 Prozent. In der Umfrage vom Januar lag der Wert noch bei 28 Prozent. Von den Entlassenen sind 54 Prozent weiterhin arbeitslos, 27 Prozent haben mindestens 100 Bewerbungen geschrieben. 17 Prozent wurden in zwei Jahren sogar zweimal entlassen. Nur 45 Prozent der Beschäftigten halten ihren Job für die nächsten zwölf Monate zumindest etwas für sicher. 81 Prozent machen sich Sorgen um ihre Zukunft in der Branche.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/one-in-three-games-industry-professionals-surveyed-by-gdc-were-laid-off-in-the-past-two-years-more-than-in-its-last-report/"}, "weitere_links": [], "tags": ["GDC", "Entlassungen", "Spielebranche", "Umfrage"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.482Z"}, "bild": {"datei": "assets/img/news/2026-11-12-gdc-umfrage-entlassungen.webp", "ki_generiert": true}}, {"id": "2026-11-12-steam-pruefstau-ki", "datum": "2026-11-12T17:06:00+01:00", "label": "News", "bereich": "games", "themen": ["Steam", "KI"], "kategorie": "Spiele", "titel": "Steam-Prüfstau durch KI-Spieleflut: Weitere Indie-Spiele müssen verschoben werden", "schlagzeile": "KI-Spieleflut auf Steam: Indie-Games hängen in Valves Prüfschlange", "kurz": "Valves Prüfung neuer Spiele auf Steam dauert derzeit bis zu zwölf Tage, laut Entwicklern wegen einer Flut minderwertiger KI-Spiele. Mehrere Indie-Titel mussten ihren Release verschieben. Valve hat die Einreichregeln verschärft, Kritiker halten das für zu wenig.", "zusammenfassung": "Seit Anfang November klagen Entwickler über lange Wartezeiten bei Valves Freigabe neuer Spiele und Builds auf Steam. Valve erklärte laut Eurogamer, dass Prüfungen wegen der Menge an erneut zu prüfenden Einreichungen bis zu zwölf Tage dauern können. Als Ursache gilt eine Flut von Billigspielen, die mit generativer KI erstellt wurden. Das Tower-Defense-Spiel Australia Did It von Rami Ismail und Aesthetician Labs sollte am 10. November erscheinen und wartet weiterhin auf die Freigabe. Auch Amazing Slot Survivor musste seinen Termin am 13. November zurückziehen, weitere Indie-Spiele sind betroffen. Valve hat strengere Einreichregeln eingeführt, um komplett KI-generierte Spiele früher auszusortieren. Ismail meint, Valve könne beim Thema KI nicht neutral bleiben, ohne echten Entwicklern zu schaden.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/steam-game-submission-review-backlog-ai-slop-approval-delays"}, "weitere_links": [], "tags": ["Steam", "Valve", "KI", "Indie"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.379Z"}, "bild": {"datei": "assets/img/news/2026-11-12-steam-pruefstau-ki.webp", "ki_generiert": true}}, {"id": "2026-11-12-windows-signdrop-zero-day", "datum": "2026-11-12T17:04:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows", "Sicherheit"], "kategorie": "Sicherheit", "titel": "SignDrop: Neue Windows-Zero-Day-Lücke verschafft SYSTEM-Rechte, noch kein Patch", "schlagzeile": "Windows-Zero-Day SignDrop: SYSTEM-Rechte und noch kein Patch", "kurz": "Ein Sicherheitsforscher hat mit SignDrop eine neue, ungepatchte Windows-Lücke samt Exploit veröffentlicht. Sie soll Angreifern SYSTEM-Rechte verschaffen und den Selbstschutz von Virenscannern aushebeln. Laut dem Forscher sind rund 80 Prozent der Windows-Installationen betroffen.", "zusammenfassung": "Der Forscher Abdelhamid Naceri, bekannt als Nightmare Eclipse, hat laut BleepingComputer einen neuen Zero-Day-Exploit für Windows veröffentlicht. SignDrop nutzt ausgerechnet eine Schutzmaßnahme aus, die Microsoft im Oktober 2025 für den Common Log File System-Treiber (CLFS) eingeführt hat. Über einen Umweg können privilegierte Prozesse wie Windows Defender dazu gebracht werden, Dateien mit SYSTEM-Rechten anzulegen. Laut Naceri lässt sich so auch der Manipulationsschutz von Antiviren- und EDR-Software umgehen. Getestet hat er Windows 11 26H2 und Windows Server 2025, er schätzt, dass rund 80 Prozent der Installationen verwundbar sind. Anfällig sind Systeme, bei denen der Registry-Wert für den CLFS-Authentifizierungsmodus auf 0 oder 1 steht. Einen Workaround gibt es laut Naceri nicht, Nutzer müssen auf einen Patch von Microsoft warten. Eine Stellungnahme von Microsoft nennt der Bericht nicht.", "quelle": {"name": "BleepingComputer", "url": "https://www.bleepingcomputer.com/news/security/new-windows-signdrop-zero-day-gives-hackers-system-privileges/"}, "weitere_links": [], "tags": ["Windows 11", "Zero-Day", "Sicherheitslücke", "CLFS"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:23.019Z"}, "bild": {"datei": "assets/img/news/2026-11-12-windows-signdrop-zero-day.webp", "ki_generiert": true}}, {"id": "2026-11-12-gta6-karte-leak", "datum": "2026-11-12T16:40:00+01:00", "label": "Leak", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6: Gedruckte Karte aus der Collector's Edition soll über ein Merch-Event geleakt sein", "schlagzeile": "Leak: Ist die GTA-6-Karte schon eine Woche vor Release im Netz?", "kurz": "Im Netz kursieren Fotos einer gedruckten, stilisierten Karte von Leonida, die aus der GTA-6-Collector's-Edition stammen soll. Die Bilder sollen von einer Merch-Aktion bei Selfridges in Großbritannien stammen. Rockstar hat sich nicht geäußert, und die Karte ist wohl keine exakte Kopie der Spielwelt.", "zusammenfassung": "Eine Woche vor dem Release von GTA 6 am 19. November tauchen laut VGC und Insider Gaming Fotos einer Karte auf. Sie sollen die gedruckte Karte aus der Collector's Edition zeigen und von einer GTA-6-Aktion der Kaufhauskette Selfridges stammen. Das deutlichste Bild kam laut VGC von einem inzwischen gelöschten Instagram-Konto, ein weiteres Foto zeigt die Karte gefaltet in einer Vitrine in Manchester. Laut Insider Gaming soll ein Selfridges-Mitarbeiter die Quelle sein, das ist aber nicht belegt. Die Karte zeigt Leonida stilisiert mit Bezirken und Clipart-artigen Motiven, wie Monstertrucks, ein UFO und Flugzeuge. Insider Gaming geht davon aus, dass sie die Spielwelt nicht exakt wiedergibt. Rockstar hat die Bilder nicht bestätigt. Wer sich nicht spoilern lassen will, sollte in sozialen Netzwerken vorsichtig sein.", "quelle": {"name": "Video Games Chronicle", "url": "https://www.videogameschronicle.com/news/gta-6-map-seemingly-leaks-at-selfridges-merch-drop/"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/gta-6-full-map-leak-online-from-collectors-box/"}, {"name": "Polygon", "url": "https://www.polygon.com/gta-6-map-leonidas-leak-merch-drop/"}], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Fotos eines physischen Merch-Artikels, von VGC, Insider Gaming und Polygon aufgegriffen; Herkunft und Echtheit nicht bestätigt, Rockstar/Take-Two schweigen. Nach Ticker-Regel gilt bei GTA 6 nur Rockstar/Take-Two als bestätigt."}, "tags": ["GTA 6", "Rockstar", "Karte", "Leonida", "Collector's Edition"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.022Z"}, "bild": {"datei": "assets/img/news/2026-11-12-gta6-karte-leak.webp", "ki_generiert": true}}, {"id": "2026-11-12-xbox-25-sharma-memo", "datum": "2026-11-12T16:15:00+01:00", "label": "News", "bereich": "games", "themen": ["Xbox", "KI"], "kategorie": "Spiele", "titel": "25 Jahre Xbox: Asha Sharma deutet in Memo KI-Entwicklung an, dazu Halo-Firefight und Xbox Playback", "schlagzeile": "25 Jahre Xbox: Chefin will mit kleinen Teams riesige Welten bauen", "kurz": "Zum 25. Geburtstag der Xbox hat Chefin Asha Sharma ein Memo veröffentlicht, das stark nach generativer KI klingt. Kleine Teams sollen künftig Welten bauen, für die heute Hunderte Entwickler nötig sind. Dazu kündigte Xbox einen Firefight-Modus für Halo: Campaign Evolved und den Jahresrückblick Xbox Playback an.", "zusammenfassung": "Xbox-Chefin Asha Sharma hat zum 25-jährigen Jubiläum ein Memo mit dem Titel „25 Years of Xbox“ veröffentlicht. Am Ende schreibt sie, zu viele Ideen würden nie zu Spielen, und das müsse sich ändern. Bald werde ein einzelner Mensch Fähigkeiten haben, für die früher ganze Nationen nötig waren, und kleine Teams könnten Welten bauen, die heute Hunderte Entwickler erfordern. Das Wort generative KI fällt laut Eurogamer nicht, die Formulierungen deuten aber stark darauf hin. Sharma kommt aus dem KI-Bereich von Microsoft, hatte zum Start als Xbox-Chefin aber gesagt, sie habe „keine Toleranz für schlechte KI“. Zum Jubiläum kündigte sie außerdem auf X einen Firefight-Modus für Halo: Campaign Evolved an, der als kostenloses Update im Winter kommt; laut Insider Gaming ist es ein PvE-Modus für vier Spieler. Zusätzlich rollt Xbox Playback aus, ein Rückblick auf die eigenen Spiele und Erfolge auf Xbox. Konkrete KI-Projekte hat Xbox in dem Memo nicht genannt.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/microsoft-xbox-gen-ai-asha-sharma-memo"}, "weitere_links": [{"name": "IGN", "url": "https://www.ign.com/articles/as-xbox-turns-25-ceo-asha-sharma-says-a-single-person-will-soon-be-able-to-wield-capabilities-that-once-required-entire-nations"}, {"name": "Insider Gaming", "url": "https://insider-gaming.com/xbox-ceo-asha-sharmas-full-memo-on-25-years-of-xbox/"}, {"name": "Asha Sharma auf X (Halo Firefight)", "url": "https://x.com/asha_shar/status/2120925412788498530"}], "tags": ["Xbox", "Asha Sharma", "KI", "Halo", "Xbox Playback"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.190Z"}, "bild": {"datei": "assets/img/news/2026-11-12-xbox-25-sharma-memo.webp", "ki_generiert": true}}, {"id": "2026-11-12-gta6-suedkorea-freigabe", "datum": "2026-11-12T15:26:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6 hätte in Südkorea wegen Nacktszenen beinahe keine Altersfreigabe bekommen", "schlagzeile": "GTA 6 fast verboten? Südkorea stritt wochenlang über Nacktszenen", "kurz": "Die südkoreanische Prüfstelle GCRB konnte sich bei GTA 6 lange nicht auf eine Einstufung einigen. Knackpunkt war Nacktheit ohne sexuellen Kontext. Am Ende gab es mit acht zu eins Stimmen die Freigabe „nur für Erwachsene“.", "zusammenfassung": "Rockstar hat laut IGN Deutschland am 1. September eine Altersfreigabe in Südkorea beantragt. Die erste Abstimmung der Prüfstelle GCRB am 10. September endete unentschieden, drei Mitglieder wollten die Einstufung verweigern, drei waren für „nur für Erwachsene“. Laut den Sitzungsprotokollen, die InvenGlobal erhalten hat, störten sich einige Mitglieder an Nacktszenen ohne sexuellen Zusammenhang. Die Entscheidung wurde vertagt, bis eine spielbare Version vorlag, mehrere Termine wurden verschoben. Am 18. Oktober beschloss der Ausschuss dann mit acht zu einer Stimme die Einstufung „nur für Erwachsene“. Eine Verweigerung hätte den Verkauf in Südkorea komplett verhindert. GTA 6 erscheint am 19. November für PS5 und Xbox Series X und S.", "quelle": {"name": "IGN Deutschland", "url": "https://de.ign.com/grand-theft-auto-vi/157197/gta-6-ware-in-sudkorea-wegen-nackter-genitalien-beinahe-keine-altersfreigabe-erteilt-worden"}, "weitere_links": [{"name": "Polygon", "url": "https://www.polygon.com/gta-6-south-korea-rating-male-nudity/"}], "tags": ["GTA 6", "Altersfreigabe", "Südkorea", "Rockstar"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.107Z"}, "bild": {"datei": "assets/img/news/2026-11-12-gta6-suedkorea-freigabe.webp", "ki_generiert": true}}, {"id": "2026-11-12-nvidia-linux-nvroot-forgeptr", "datum": "2026-11-12T15:17:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit", "Treiber"], "kategorie": "Sicherheit", "titel": "NvRoot und ForgePtr: Zwei Sicherheitslücken im Nvidia-Linux-Treiber veröffentlicht, 25 weitere angekündigt", "schlagzeile": "Nvidia-Linux-Treiber: Lücke macht Container-Prozesse zu Root", "kurz": "Die Sicherheitsfirma Stealthium hat zwei Lücken in Nvidias offenen Linux-Kernelmodulen veröffentlicht. Über ForgePtr kann ein Prozess in einem GPU-Container Root auf dem Host werden. Patches gibt es bereits, weitere 25 Meldungen sollen folgen.", "zusammenfassung": "Laut Phoronix sind die ersten zwei von insgesamt 27 angekündigten Sicherheitslücken in Nvidias Treiber-Stack öffentlich. ForgePtr (CVE-2026-47501) erlaubt einem nicht privilegierten Prozess in einem GPU-Container, Root-Rechte auf dem Host zu erlangen. Mit NvRoot (CVE-2026-47591) kann die GPU Dateien überschreiben, die das Betriebssystem als schreibgeschützt markiert hat. Beide Lücken stecken seit rund vier Jahren in Nvidias offenen Kernelmodulen und sind als hoch (CVSS 7,8) eingestuft. Besonders betroffen sind Cloud-Anbieter, die GPUs an mehrere Kunden vermieten. NvRoot ist mit den Treibern 610.57.04, 595.91.07 und 580.178.04 behoben, ForgePtr mit 615.71.09. Stealthium hat laut Phoronix 25 weitere Meldungen zum KI-Software-Stack von Nvidia angekündigt. Wer Nvidia-GPUs unter Linux nutzt, vor allem in Containern, sollte den Treiber aktualisieren.", "quelle": {"name": "Phoronix", "url": "https://www.phoronix.com/news/NVIDIA-NvRoot-ForgePtr"}, "weitere_links": [], "tags": ["Nvidia", "Linux", "Sicherheitslücke", "Treiber", "Cloud"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.892Z"}, "bild": {"datei": "assets/img/news/2026-11-12-nvidia-linux-nvroot-forgeptr.webp", "ki_generiert": true}}, {"id": "2026-11-12-huang-ruecktritt-kress", "datum": "2026-11-12T15:04:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Unternehmen", "titel": "Jensen Huang tritt nach 33 Jahren als Nvidia-CEO zurück, CFO Colette Kress übernimmt vorübergehend", "schlagzeile": "Ende einer Ära: Jensen Huang tritt bei Nvidia zurück", "kurz": "Nvidia hat den Rücktritt von Mitgründer und CEO Jensen Huang bekanntgegeben, er legt alle Ämter mit sofortiger Wirkung nieder. Finanzchefin Colette Kress führt das Unternehmen vorerst als Interims-CEO. Den Vorsitz im Verwaltungsrat übernimmt Harvey C. Jones.", "zusammenfassung": "Nach Tagen der Krise ist es offiziell: Jensen Huang tritt nach 33 Jahren an der Spitze von Nvidia zurück. Laut ComputerBase legt er seine Ämter als Präsident, CEO und Mitglied des Verwaltungsrats nieder, laut PC Gamer mit sofortiger Wirkung. Huang wurde nicht entlassen, er hat laut TechPowerUp ein Rücktrittsschreiben unterzeichnet. Auslöser waren Berichte über zwei außereheliche Beziehungen, darunter eine zu einer Managerin, die ihm direkt unterstellt war. Zuvor hatte der Verwaltungsrat in einer außerplanmäßigen Sitzung beraten, laut Bloomberg wurde bereits eine externe Firma für die Nachfolgesuche eingeschaltet. Finanzchefin Colette Kress leitet die Geschäfte vorübergehend als CEO und bleibt parallel CFO. Den Vorsitz im Verwaltungsrat übernimmt Harvey C. Jones. Kress kündigte an, auf dem Fundament aufzubauen, das Huang in 33 Jahren geschaffen habe. Ob Huang künftig noch eine Rolle im Unternehmen spielt, geht aus der Mitteilung nicht hervor. Wer dauerhaft CEO wird, ist offen; dazu gibt es bisher nur Spekulationen. Auswirkungen auf GeForce-Produkte, Preise oder Treiber sind derzeit nicht bekannt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/mr-nvidia-muss-gehen-jensen-huang-tritt-nach-33-jahren-als-ceo-zurueck.100305/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Grafikkarten-Grafikkarte-97980/News/Nvidia-Jensen-Huang-Ruecktritt-CEO-Colette-Kress-Nachfolgerin-1559816/"}, {"name": "TechPowerUp", "url": "https://www.techpowerup.com/354732/nvidia-co-founder-and-ceo-jensen-huang-officially-resigns"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/hardware/graphics-cards/jensen-huang-resigns-cfo-colette-kress-appointed-interim-ceo-at-nvidia/"}, {"name": "heise online", "url": "https://www.heise.de/news/Nach-Bekanntwerden-einer-zweiten-Affaere-Nvidia-CEO-Jensen-Huang-abgetreten-11522193.html"}], "tags": ["Nvidia", "Jensen Huang", "Colette Kress", "Unternehmen"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.539Z"}, "bild": {"datei": "assets/img/news/2026-11-12-huang-ruecktritt-kress.webp", "ki_generiert": true}}, {"id": "2026-11-12-paradox-wester-ruecktritt", "datum": "2026-11-12T14:22:00+01:00", "label": "News", "bereich": "games", "themen": ["Paradox"], "kategorie": "Spiele", "titel": "Paradox-Chef Frederik Wester tritt ab, Mattias Lilja übernimmt im Januar", "schlagzeile": "Nach Bloodlines-2-Flop: Paradox bekommt einen neuen Chef", "kurz": "Paradox-Interactive-CEO Frederik Wester gibt seinen Posten ab und wechselt in den Verwaltungsrat. Sein Stellvertreter Mattias Lilja übernimmt am 4. Januar 2027. Hinter dem Publisher liegen mehrere schwierige Jahre.", "zusammenfassung": "Frederik Wester tritt laut Eurogamer als CEO von Paradox Interactive zurück und soll sich künftig als Mitglied des Verwaltungsrats um die langfristige Entwicklung kümmern. Nachfolger wird der bisherige Vize-CEO Mattias Lilja ab dem 4. Januar 2027, bis dahin bleibt Wester im Amt. Wester führte Paradox von 2009 bis 2018 und erneut seit 2021. In seine zweite Amtszeit fielen die schwierige Entwicklung von Vampire: The Masquerade Bloodlines 2, dessen kommerzieller Misserfolg den operativen Gewinn stark einbrechen ließ. Dazu kamen die Einstellung von Life by You, die Verschiebung von Prison Architect 2 und der holprige Start von Cities: Skylines 2, dessen Konsolenversion noch immer fehlt. Lilja will stärker ins Kerngeschäft investieren und enger mit Spielern und Moddern arbeiten. Als nächste Spiele stehen Lego Skylines und das Strategiespiel Afterworld an.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/paradox-ceo-frederik-wester-stepping-down"}, "weitere_links": [], "tags": ["Paradox", "Cities Skylines", "Stellaris", "Unternehmen"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.284Z"}, "bild": {"datei": "assets/img/news/2026-11-12-paradox-wester-ruecktritt.webp", "ki_generiert": true}}, {"id": "2026-11-12-siren-halo-gddr7", "datum": "2026-11-12T14:04:00+01:00", "label": "Leak", "bereich": "hardware", "themen": ["CPU", "APU", "AMD"], "kategorie": "Prozessoren", "titel": "Gerücht: AMDs Siren Halo soll GDDR7-Grafikspeicher statt nur LPDDR5X nutzen", "schlagzeile": "Leak: Bekommt AMDs Mega-APU Siren Halo echten GDDR7-Speicher?", "kurz": "Laut einem Leaker soll AMDs kommende Halo-APU Siren Halo mit GDDR7-Speicher arbeiten. Bisherige Halo-Chips nutzen gemeinsamen LPDDR5X-Speicher für CPU und GPU. Bestätigt ist nichts.", "zusammenfassung": "Der Hardware-Leaker Gotou_kai3 behauptet, dass AMDs Siren Halo GDDR7-Speicher bekommen soll, berichten Wccftech und PCGH. Siren Halo soll wie Medusa Halo auf Zen 6 und RDNA 5 setzen, aber als eigentlicher Nachfolger gelten und nicht als einfacher Refresh. Aktuelle Halo-Chips wie Strix Halo nutzen LPDDR5X als gemeinsamen Speicher für CPU und GPU. GDDR7 würde deutlich mehr Speicherbandbreite bringen, was vor allem der Grafikeinheit in Spielen helfen könnte. Unklar ist laut Wccftech, ob CPU und GPU beide Speicherpools nutzen können oder ob GDDR7 nur der Grafik vorbehalten wäre. Für KI-Anwendungen wäre eine reine GDDR7-Grafiklösung womöglich weniger flexibel als der große gemeinsame Speicher der heutigen Ryzen-AI-Max-Chips. AMD hat Siren Halo nicht angekündigt, Termine und Spezifikationen sind unbekannt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/CPU-CPU-154106/News/AMD-Siren-Halo-mit-GDDR7-Grafikspeicher-1559803/"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/amds-siren-halo-will-reportedly-support-gddr7-memory/"}], "zuverlaessigkeit": {"stufe": "niedrig bis mittel", "begruendung": "Einzelner Leaker (Gotou_kai3) ohne Belege; über PCGH und Wccftech verbreitet; von AMD nicht bestätigt."}, "tags": ["AMD", "Siren Halo", "APU", "GDDR7", "RDNA 5", "Zen 6"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.758Z"}, "bild": {"datei": "assets/img/news/2026-11-12-siren-halo-gddr7.webp", "ki_generiert": true}}, {"id": "2026-11-12-apache-http2-luecke", "datum": "2026-11-12T13:43:00+01:00", "label": "News", "bereich": "software", "themen": ["Linux", "Sicherheit"], "kategorie": "Sicherheit", "titel": "Kritische Lücke im HTTP/2-Modul von Apache: Update auf 2.4.71 empfohlen", "schlagzeile": "Kritische Apache-Lücke: Webserver mit HTTP/2 sofort updaten", "kurz": "Im Webserver Apache steckt eine kritische Lücke im Modul mod_http2, die Codeausführung aus der Ferne ermöglichen könnte. Betroffen sind nur Server mit aktiviertem HTTP/2. Version 2.4.71 behebt den Fehler.", "zusammenfassung": "Laut heise steckt die Lücke CVE-2026-119618 in der Funktion assign_headers() des Moduls mod_http2. Eine Speichermanipulation könnte dort zur Ausführung von Schadcode aus der Ferne führen. Red Hat bewertet die Lücke laut Golem mit 9,8 von 10 Punkten. Gefunden haben sie ein OSS-Scanner von Anthropic und zwei Forscher von Google Cloud Vulnerability Research. Da mod_http2 standardmäßig nicht aktiv ist, sind nur Server betroffen, die HTTP/2 nutzen. Experten wie Kevin Beaumont halten einen Exploit wegen Schutzmechanismen wie ASLR für schwierig. Trotzdem sollten Admins auf Apache 2.4.71 aktualisieren, die zwei weitere Lücken schließt. Wer nicht sofort updaten kann, sollte HTTP/2 vorerst abschalten.", "quelle": {"name": "heise online", "url": "https://www.heise.de/news/Kritische-Sicherheitsluecke-in-Apache2-ermoeglicht-Codeeinschleusung-11523150.html"}, "weitere_links": [{"name": "Golem.de", "url": "https://www.golem.de/news/red-hat-kritische-sicherheitsluecke-in-apache-http-server-entdeckt-2611-215134.html"}], "tags": ["Apache", "Linux", "Webserver", "Sicherheitslücke"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:23.124Z"}, "bild": {"datei": "assets/img/news/2026-11-12-apache-http2-luecke.webp", "ki_generiert": true}}, {"id": "2026-11-12-rtx5090-96gb-mod", "datum": "2026-11-12T11:17:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Grafikkarten", "titel": "Umgebaute RTX 5090 mit 96 GB Speicher taucht auf chinesischem Gebrauchtmarkt auf", "schlagzeile": "RTX 5090 mit 96 GB: China-Mod für rund 900.000 Dollar aufgetaucht", "kurz": "Auf der chinesischen Plattform Xianyu wird eine modifizierte GeForce RTX 5090 mit 96 GB Videospeicher angeboten. Der Platzhalterpreis liegt bei umgerechnet rund 900.000 US-Dollar, verhandelt wird privat. Ob die Karte wirklich funktioniert, ist nicht belegt.", "zusammenfassung": "Chinesische Modder bauen Desktop-GPUs auf eigene Platinen um und vervielfachen so den Speicher für KI-Anwendungen. Jetzt ist laut Wccftech und PCGH ein Angebot für eine RTX 5090 mit 96 GB aufgetaucht, so viel Speicher wie bei der RTX Pro 6000. Entdeckt hat es der Reparaturspezialist VIK-on auf Alibabas Gebrauchtmarkt Xianyu, zuerst berichtete VideoCardz. Der GB202-Chip sitzt auf einer eigenen Platine mit Samsung-Speicherchips auf beiden Seiten. Der Verkäufer bietet neben der Karte auch Platinenpläne und ein gepatchtes BIOS an, richtet sich aber nur an Geschäftskunden mit Vertraulichkeitsvereinbarung. Der angegebene Preis von 6.488.888 Yuan, rund 900.000 US-Dollar, ist ein Platzhalter, der tatsächliche Preis wird privat ausgehandelt. Benchmarks gibt es keine, die Funktion der Karte ist daher unbestätigt.", "quelle": {"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Geforce-RTX-5090-Grafikkarte-281029/News/96-GiByte-Speicher-Modifikation-1559779/"}, "weitere_links": [{"name": "Wccftech", "url": "https://wccftech.com/modded-rtx-5090-96gb-vram-china-listing/"}], "tags": ["RTX 5090", "Mod", "VRAM", "China", "KI"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.848Z"}, "bild": {"datei": "assets/img/news/2026-11-12-rtx5090-96gb-mod.webp", "ki_generiert": true}}, {"id": "2026-11-12-swtor-directx12-test", "datum": "2026-11-12T11:15:00+01:00", "label": "News", "bereich": "games", "themen": ["DirectX", "MMORPG"], "kategorie": "Spiele", "titel": "Star Wars: The Old Republic startet öffentlichen DirectX-12-Test, Grafik zunächst bewusst reduziert", "schlagzeile": "SWTOR bekommt DirectX 12 – und sieht erst mal schlechter aus", "kurz": "Fast 15 Jahre nach dem Release testet Star Wars: The Old Republic einen DirectX-12-Client. Der öffentliche Test startet noch diese Woche direkt im normalen Launcher. Viele Grafikeffekte fehlen anfangs absichtlich.", "zusammenfassung": "Entwickler Broadsword modernisiert laut PC Games die Technik des MMORPGs Star Wars: The Old Republic. Noch diese Woche startet ein öffentlicher Test des neuen DirectX-12-Clients, ohne Anmeldung oder Zugangscode. Im normalen Launcher lässt sich über einen kleinen Pfeil zwischen alter und neuer Version wählen, beide nutzen dieselben Live-Server und Charaktere. Viele Umgebungsdetails und Effekte fehlen im neuen Client noch oder sind vereinfacht, auch die Grafikoptionen sind eingeschränkt. Das ist Absicht: Zunächst geht es um Stabilität, Leistung und Kompatibilität mit möglichst vielen PCs. Spieler sollen Ruckler, Bildfehler und Abstürze samt Hardware melden. Für Mac-Spieler gibt es den Test vorerst nicht. Laut Broadsword läuft das Projekt bis weit ins Jahr 2027, danach soll die Grafik schrittweise mindestens das alte Niveau erreichen.", "quelle": {"name": "PC Games", "url": "https://www.pcgames.de/SWTOR-Star-Wars-The-Old-Republic-Spiel-17102/News/DirectX-12-doch-die-Grafik-wird-schlechter-1559693/"}, "weitere_links": [], "tags": ["SWTOR", "DirectX 12", "MMORPG", "Broadsword"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:22.580Z"}, "bild": {"datei": "assets/img/news/2026-11-12-swtor-directx12-test.webp", "ki_generiert": true}}, {"id": "2026-11-12-apex-neural-rendering", "datum": "2026-11-12T11:11:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Upscaling"], "kategorie": "Grafik", "titel": "Apex Neural Rendering: Start-up verspricht herstellerunabhängige Alternative zu DLSS, FSR und XeSS", "schlagzeile": "Besser als DLSS? Apex bringt Frame Generation für alle drei GPU-Lager", "kurz": "Das Unternehmen Apex Compute hat Apex Neural Rendering (ANR) vorgestellt, mit Super Resolution, Ray Reconstruction und Frame Generation für GeForce, Radeon und Arc. Die Frame Generation gibt es ab sofort als kostenlose Beta auf GitHub. Die Versprechen sind groß, ComputerBase hält sie aber für kaum nachvollziehbar.", "zusammenfassung": "Apex Compute, bisher auf Edge-KI-Beschleuniger spezialisiert, will mit Apex Neural Rendering (ANR) gegen DLSS, FSR und XeSS antreten. ANR soll Super Resolution, Ray Reconstruction und Frame Generation herstellerunabhängig auf Nvidia, AMD und Intel bieten. Laut Hersteller soll es bis zu 2,4-mal schneller sein und eine bessere Bildqualität als DLSS liefern. Bereits verfügbar ist nur die Frame Generation als kostenlose Beta auf GitHub, eingebunden wird sie über OptiScaler, mit den Stufen 2×, 3× und 4×. Super Resolution und Ray Reconstruction sind laut Apex noch in Entwicklung. Die Frame Generation läuft laut ComputerBase ab GeForce GTX 16 und RTX 2000, ab Radeon RX 5000 inklusive Steam Deck und auf Intel Arc A, unter Windows 10, Windows 11 und Linux mit Proton. ComputerBase kritisiert Unstimmigkeiten in den Herstellerangaben, etwa angebliche Messwerte von FSR mit mehr als einem KI-Zwischenbild, und unklare Faktoren in den Vergleichsvideos. Unabhängige Tests gibt es noch nicht, die Leistungs- und Qualitätsversprechen sind daher unbestätigt.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/grafikkarten/apex-neural-rendering-anr-soll-dlss-fsr-und-xess-in-allen-disziplinen-schlagen.100301/"}, "weitere_links": [{"name": "TechPowerUp", "url": "https://www.techpowerup.com/354727/apex-neural-rendering-beats-nvidia-dlss-in-both-image-quality-and-performance"}, {"name": "Wccftech", "url": "https://wccftech.com/apex-neural-rendering-challenges-nvidia-dlss-with-up-to-2-4x-faster-frame-generation-62-lower-vram-usage-and-broad-gpu-support/"}, {"name": "GamingOnLinux", "url": "https://www.gamingonlinux.com/2026/11/apex-compute-revealed-apex-neural-rendering-anr-their-cross-platform-answer-to-nvidia-dlss/"}], "tags": ["Upscaling", "Frame Generation", "DLSS", "FSR", "XeSS"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.653Z"}, "bild": {"datei": "assets/img/news/2026-11-12-apex-neural-rendering.webp", "ki_generiert": true}}, {"id": "2026-11-12-samsung-hbm-onyang", "datum": "2026-11-12T10:15:00+01:00", "label": "News", "bereich": "hardware", "themen": ["RAM", "Speicher"], "kategorie": "Speicher", "titel": "Speicherknappheit: Samsung baut neue HBM-Packaging-Linie und will sie ein Jahr früher fertigstellen", "schlagzeile": "RAM-Krise: Samsung zieht neue HBM-Fabrik um ein Jahr vor", "kurz": "Samsung hat in Onyang mit dem Bau einer neuen Linie für HBM-Packaging begonnen. Sie soll im Juni 2028 starten, ein Jahr früher als geplant. Grund ist die anhaltende Speicherknappheit.", "zusammenfassung": "Samsung hat laut ComputerBase auf seinem Onyang-Campus in Asan den Spatenstich für eine neue Produktionslinie gesetzt, die HBM-Speicher verpacken soll. Der Betrieb soll im Juni 2028 starten und damit ein Jahr früher als ursprünglich geplant. In Onyang investiert Samsung 46 Billionen Won, rund 31 Milliarden Euro, davon den Großteil in die Ausrüstung. Geplant sind etwa 31.000 Quadratmeter Reinraum auf drei Etagen und rund 700 neue Arbeitsplätze. Samsung hatte im Oktober erklärt, die HBM-Liefermengen für 2027 schon ausverhandelt zu haben und den Bedarf bei weitem nicht decken zu können. HBM steckt vor allem in KI-Beschleunigern, die Knappheit belastet aber den gesamten Speichermarkt und damit auch RAM-Preise für PC-Nutzer. Kurzfristig ändert die neue Linie an den Preisen nichts.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/arbeitsspeicher/speicherknappheit-samsung-will-neue-hbm-fabrik-ein-jahr-frueher-fertigstellen.100299/"}, "weitere_links": [], "tags": ["Samsung", "HBM", "RAM-Preise", "Speicherknappheit"], "ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T19:17:21.935Z"}, "bild": {"datei": "assets/img/news/2026-11-12-samsung-hbm-onyang.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:02.862Z"}, "id": "2026-11-12-outlook-mails-blockiert", "datum": "2026-11-12T05:53:00+01:00", "label": "News", "bereich": "software", "themen": ["Outlook", "Microsoft"], "kategorie": "Software", "titel": "Outlook.com: Fehlerhafte Spam-Regel hat tagelang echte E-Mails abgewiesen – die Mails sind verloren", "schlagzeile": "Outlook hat tagelang Mails abgewiesen – und die kommen nicht zurück", "kurz": "Eine fehlerhafte Spam-Regel von Microsoft hat tagelang legitime E-Mails an Outlook.com-, Hotmail- und Live-Adressen abgewiesen. Microsoft hat das Update zurückgenommen, Absender und Empfänger müssen nichts ändern. Abgewiesene Mails sind aber nicht wiederherstellbar, man muss Absender um erneutes Senden bitten.", "zusammenfassung": "Wer zuletzt auffällig wenige E-Mails im Outlook.com-Postfach hatte, war womöglich betroffen. Laut Windows Latest wurden mindestens ab dem 5. November legitime Mails an Outlook.com-, Hotmail-, Live- und MSN-Adressen abgewiesen. Absender erhielten Fehlermeldungen, ihren Mails fehlten SPF-, DKIM- oder DMARC-Einträge, obwohl das teils nicht stimmte. Microsoft bestätigte gegenüber Windows Latest, dass ein Update der Spam-Regeln die Ursache war. Das Unternehmen hat es zurückgenommen, der Mailfluss läuft laut Windows Latest seit dem 9. November wieder. Weder Absender noch Empfänger müssen Einstellungen ändern. Das Problem: Die abgewiesenen Mails landeten nicht im Spam-Ordner, sondern kamen nie an. Microsoft kann sie deshalb nicht wiederherstellen. Wer wichtige Mails erwartet hat, sollte Absender bitten, sie erneut zu schicken. Admins finden den Vorfall im Microsoft-365-Admin-Center unter der Kennung EX1545193. Wie viele Nutzer betroffen waren, nennt Microsoft nicht.", "quelle": {"name": "Windows Latest", "url": "https://www.windowslatest.com/2026/11/12/you-may-have-missed-emails-on-outlook-for-days-as-microsoft-confirms-its-spam-rule-wrongly-blocked-them-and-blamed-senders-settings/"}, "weitere_links": [], "tags": ["Outlook", "Microsoft", "E-Mail", "Spam"], "bild": {"datei": "assets/img/news/2026-11-12-outlook-mails-blockiert.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:02.974Z"}, "id": "2026-11-12-powershell-signatur-kb5132061", "datum": "2026-11-12T05:08:00+01:00", "label": "News", "bereich": "software", "themen": ["Windows"], "kategorie": "Windows", "titel": "November-Update KB5132061: Strengere Prüfung lässt manche signierte PowerShell-Skripte scheitern", "schlagzeile": "Windows-Update bremst signierte PowerShell-Skripte aus – so geht der Fix", "kurz": "Mit dem November-Sicherheitsupdate prüft Windows die Textkodierung signierter PowerShell-Skripte strenger. Skripte mit fehlerhaftem UTF-8 gelten danach womöglich als nicht signiert und laufen in verwalteten Umgebungen nicht mehr wie gewohnt. Microsoft empfiehlt, sie als UTF-8 mit BOM zu speichern und neu zu signieren.", "zusammenfassung": "Microsoft hat mit dem Update KB5132061 vom 10. November die Prüfung von PowerShell-Signaturen verschärft. Bisher konnte Windows Skripte mit ungültigem UTF-8 noch verarbeiten, indem es fehlerhafte Zeichen ersetzte. Das passiert jetzt nicht mehr, betroffene Dateien werden abgelehnt. Laut Microsoft meldet Get-AuthenticodeSignature dann „NotSigned“ für ein eigentlich signiertes Skript. Set-AuthenticodeSignature kann mit einem Fehler abbrechen. Auf Geräten mit App Control for Business können betroffene Skripte nur noch im eingeschränkten Sprachmodus laufen. Betroffen sind vor allem Skripte mit fehlerhaftem UTF-8, UTF-8 ohne BOM auf Systemen mit anderer Codepage und Dateien in Kodierungen wie Shift-JIS. Microsoft empfiehlt, die Skripte zu prüfen, als gültiges UTF-8 mit BOM zu speichern und neu zu signieren. Ein Beispielskript namens Repair-SignedPowerShellUtf8.ps1 sucht betroffene Dateien und überschreibt keine Originale. Laut Neowin gilt die Änderung neben Windows 11 auch für Windows 10 Enterprise LTSC 2021 und Windows Server 2025. Private Nutzer ohne signierte Skripte merken davon in der Regel nichts.", "quelle": {"name": "Neowin", "url": "https://www.neowin.net/news/latest-windows-11-update-kb5132061-could-break-your-powershell-scripts/"}, "weitere_links": [{"name": "Microsoft Support (KB5132061)", "url": "https://support.microsoft.com/en-us/servicing/os/windows-11/2026/11/kb5132061-windows-11-24h2-25h2-26h2-security-update"}, {"name": "Microsoft Support (Anleitung zur Kodierung)", "url": "https://support.microsoft.com/en-us/servicing/os/windows/docs/2026/11/powershell-sip-canonical-repair"}], "tags": ["Windows 11", "PowerShell", "KB5132061", "Sicherheit"], "bild": {"datei": "assets/img/news/2026-11-12-powershell-signatur-kb5132061.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.109Z"}, "id": "2026-11-12-tomb-raider-catalyst-switch2", "datum": "2026-11-12T04:01:00+01:00", "label": "News", "bereich": "games", "themen": ["Tomb Raider", "Switch 2"], "kategorie": "Spiele", "titel": "Amazon nennt Tomb Raider: Catalyst auch für Nintendo Switch 2", "schlagzeile": "Tomb Raider: Catalyst kommt wohl auch für die Switch 2", "kurz": "Ein Beitrag auf Amazons offizieller News-Seite nennt die Switch 2 als Plattform für beide kommenden Tomb-Raider-Spiele. Für Legacy of Atlantis war das bekannt, für Catalyst bisher nicht. Amazon ist Publisher von Catalyst, eine Bestätigung von Crystal Dynamics oder Nintendo fehlt noch.", "zusammenfassung": "Laut Insider Gaming steht in einem am 9. November aktualisierten Beitrag von Amazon News, dass beide neuen Tomb-Raider-Spiele für PS5, Xbox Series X/S, Nintendo Switch 2 und Steam erscheinen. Für Tomb Raider: Legacy of Atlantis (2027) war die Switch-2-Version schon offiziell, das Spiel ist im eShop vorbestellbar. Neu ist die Angabe für Tomb Raider: Catalyst. Das Spiel wurde in diesem Jahr auf 2028 verschoben. Catalyst wird von Amazon Game Studios veröffentlicht, daher hat die Angabe Gewicht. Insider Gaming hält einen Fehler im Artikel aber für möglich, auch wenn er seit zwei Tagen unverändert online ist. Crystal Dynamics und Nintendo haben die Switch-2-Fassung noch nicht bestätigt. Technische Details oder einen Termin für die Switch-2-Version gibt es nicht.", "quelle": {"name": "Insider Gaming", "url": "https://insider-gaming.com/tomb-raider-catalyst-switch-2/"}, "weitere_links": [], "tags": ["Tomb Raider", "Catalyst", "Switch 2", "Amazon"], "bild": {"datei": "assets/img/news/2026-11-12-tomb-raider-catalyst-switch2.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.236Z"}, "id": "2026-11-12-steam-erfolge-linux-64bit", "datum": "2026-11-12T02:16:00+01:00", "label": "News", "bereich": "games", "themen": ["Steam", "Linux"], "kategorie": "Spiele-Stores", "titel": "Steam-Client-Update: Achievement Sets für alle und der Linux-Client läuft endlich als 64-Bit-Programm", "schlagzeile": "Steam-Update: Neue Erfolge-Sets und 64 Bit für Linux", "kurz": "Valve hat ein neues Steam-Update für alle Nutzer veröffentlicht. Spiele können Erfolge jetzt in Sets für Grundspiel und DLC gruppieren, ohne dass eine 100-Prozent-Wertung verloren geht. Unter Linux ist der Steam-Client nun ein 64-Bit-Programm und läuft in einem Steam-Runtime-Container.", "zusammenfassung": "Valve hat am 11. November ein Steam-Client-Update für den stabilen Kanal veröffentlicht. Wichtigste Neuerung für alle sind die Steam Achievement Sets. Entwickler können Erfolge damit nach Grundspiel und DLC gruppieren. Neue Erfolge oder DLC-Erfolge machen eine bereits vollständige Erfolgs-Sammlung so nicht mehr unvollständig. Saisonale oder nicht mehr erreichbare Erfolge lassen sich archivieren. Dazu kommt eine überarbeitete Erfolgs-Seite. Unter Linux ist der Steam-Client nun eine 64-Bit-Anwendung und läuft in einem Steam-Runtime-Container. Das soll laut Valve für gleiches Verhalten auf verschiedenen Distributionen sorgen, es ist dieselbe Technik, die auch Spiele nutzen. Laut TechPowerUp war Steam unter Linux bisher noch ein 32-Bit-Programm. Zusätzlich behebt das Update unter anderem einen Absturz beim Aufwachen aus dem Standby. Ob Entwickler die neuen Erfolgs-Sets auch nutzen, liegt bei ihnen.", "quelle": {"name": "TechPowerUp", "url": "https://www.techpowerup.com/353772/linux-finally-gets-64-bit-steam-client-and-new-game-achievements-management"}, "weitere_links": [{"name": "Steam (Ankündigung Achievement Sets)", "url": "https://store.steampowered.com/news/posts/4149575031735702629"}, {"name": "9to5Linux", "url": "https://9to5linux.com/new-steam-client-update-introduces-linux-64-bit-support-steam-achievement-sets"}], "tags": ["Steam", "Valve", "Linux", "Achievements"], "bild": {"datei": "assets/img/news/2026-11-12-steam-erfolge-linux-64bit.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.349Z"}, "id": "2026-11-12-witcher3-ki-stimme-geralt", "datum": "2026-11-12T01:02:00+01:00", "label": "News", "bereich": "games", "themen": ["Witcher"], "kategorie": "Spiele", "titel": "The Witcher 3: CD Projekt passt die polnische Stimme von Geralt im neuen Add-on per KI an – mit Zustimmung des Sprechers", "schlagzeile": "Nach Schlaganfall: KI lässt Geralts polnische Stimme wieder jung klingen", "kurz": "Im kommenden Witcher-3-Add-on Songs of the Past wird die polnische Stimme von Geralt per KI nachbearbeitet. Sprecher Jacek Rozenek nimmt alle Zeilen selbst auf, seine Stimme hat sich nach einem Schlaganfall 2019 aber hörbar verändert. Das KI-Unternehmen Respeecher gleicht sie mit seiner Zustimmung an den Klang von früher an.", "zusammenfassung": "CD Projekt Red hat bestätigt, für die polnische Fassung der neuen Witcher-3-Erweiterung Songs of the Past KI einzusetzen. Das berichtete zuerst Game File, PC Gamer, VGC und IGN haben es aufgegriffen. Jacek Rozenek spricht Geralt seit jeher auf Polnisch, erlitt 2019 aber einen Schlaganfall und konnte zeitweise nicht sprechen. Nach langem Training kehrte er zurück, seine Stimme klingt heute jedoch tiefer und rauer. Weil die Erweiterung mitten in der Handlung von The Witcher 3 spielt, hätte der Unterschied auffallen können. Rozenek nimmt deshalb weiter alle Zeilen selbst auf, Respeecher passt sie danach an seinen Klang von vor rund zwölf Jahren an. Trainiert wurde das Modell mit seinen früheren Aufnahmen für das Spiel. Rozenek unterstützt das ausdrücklich und sagt, die Stimme solle so nah wie möglich an seiner von damals sein. Lokalisierungsproduzent Mikołaj Szwed nennt es einen Sonderfall wegen der Erkrankung und sieht darin eine ethische Nutzung mit Einwilligung. Für die englische Stimme von Doug Cockle ist laut CD Projekt nichts dergleichen geplant. CD Projekt arbeitete schon bei Cyberpunk 2077: Phantom Liberty mit Respeecher, damals mit Zustimmung der Familie eines verstorbenen Sprechers. Ein Termin für Songs of the Past steht in den Berichten nicht.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/the-witcher/cd-projekt-used-ai-to-modify-the-voice-of-geralts-polish-actor-after-a-stroke-left-it-significantly-changed-this-was-a-special-case/"}, "weitere_links": [{"name": "VGC", "url": "https://www.videogameschronicle.com/news/the-witcher-3-expansion-uses-ai-to-adjust-geralts-polish-voiceover-because-the-actor-suffered-a-stroke/"}, {"name": "IGN", "url": "https://www.ign.com/articles/cd-projekt-red-used-ai-to-alter-geralts-voice-due-to-polish-actors-health-issues"}], "tags": ["The Witcher 3", "CD Projekt Red", "KI", "Synchronisation"], "bild": {"datei": "assets/img/news/2026-11-12-witcher3-ki-stimme-geralt.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.467Z"}, "id": "2026-11-12-helldivers2-kosmetik-mods", "datum": "2026-11-12T00:29:00+01:00", "label": "News", "bereich": "games", "themen": ["Helldivers 2"], "kategorie": "Spiele", "titel": "Helldivers 2: Nach Anti-Cheat-Wechsel und Review-Welle sollen kosmetische Mods mit dem nächsten Hotfix wieder laufen", "schlagzeile": "Helldivers 2: Arrowhead will harmlose Mods wieder erlauben", "kurz": "Seit dem Wechsel auf Easy Anti-Cheat funktionieren in Helldivers 2 viele Mods nicht mehr, auf Steam folgten über 10.000 negative Reviews. Arrowhead kündigt an, dass einige rein kosmetische Mods mit dem nächsten Hotfix wieder laufen sollen. Mods, die das Gameplay verändern, bleiben verboten.", "zusammenfassung": "Arrowhead hat bei Helldivers 2 das Anti-Cheat-System von GameGuard auf Easy Anti-Cheat umgestellt. Ziel war laut Studio, Mods zu stoppen, die unfaire Vorteile bringen oder anderen schaden. Dabei hörten aber auch harmlose kosmetische Mods auf zu funktionieren. Die Reaktion fiel heftig aus: Laut PC Gamer kamen über 10.000 neue negative Steam-Reviews dazu, die jüngsten Bewertungen stehen auf „größtenteils negativ“. Im neuen Entwickler-Blog räumt Arrowhead ein, dass PC-Spieler Fan-Mods verloren haben. Nach Anpassungen sollen einige kosmetische Mods mit dem nächsten Hotfix wieder funktionieren. Mods, die das Gameplay verändern, bleiben verboten, weil sie technisch nicht von Cheats zu unterscheiden seien. Offiziell unterstützt werden Mods weiterhin nicht. Arrowhead entschuldigt sich außerdem für eine ungenaue Roadmap und verpasste Patch-Termine. Für Anfang Dezember sind unter anderem Jetpacks beim Tragen zweihändiger Gegenstände geplant. Ein Datum für den Hotfix nennt das Studio nicht.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/third-person-shooter/after-cracking-down-on-cheat-mods-in-helldivers-2-and-taking-another-steam-review-beating-arrowhead-plans-hotfix-that-should-allow-harmless-cosmetics/"}, "weitere_links": [], "tags": ["Helldivers 2", "Arrowhead", "Mods", "Anti-Cheat"], "bild": {"datei": "assets/img/news/2026-11-12-helldivers2-kosmetik-mods.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.583Z"}, "id": "2026-11-12-marvel-1943-fast-fertig", "datum": "2026-11-12T00:27:00+01:00", "label": "Leak", "bereich": "games", "themen": ["Marvel 1943"], "kategorie": "Spiele", "titel": "Bericht: Marvel 1943: Rise of Hydra soll fast fertig sein, aber deutlich kleiner als geplant", "schlagzeile": "Leak: Ist Marvel 1943 fast fertig – aber stark zusammengestrichen?", "kurz": "Nach Gerüchten über eine Einstellung berichtet Kotaku, Marvel 1943: Rise of Hydra sei nahezu fertig. Das Spiel soll aber deutlich weniger Inhalt und spielerische Tiefe bieten als geplant. Skydance hat dazu nichts Offizielles gesagt.", "zusammenfassung": "Um Marvel 1943: Rise of Hydra, das Captain-America- und Black-Panther-Spiel von Amy Hennig, gab es zuletzt Gerüchte über eine bevorstehende Einstellung. Laut Kotaku und Bloomberg-Reporter Jason Schreier hat die Führung von Skydance den Mitarbeitern per Slack mitgeteilt, dass das nicht stimmt. Kotaku berichtet zudem, das Spiel sei „close to done“, also fast fertig. Die Entwicklung soll aber schwierig gewesen sein und das Budget deutlich überschritten haben. Deshalb seien Umfang und Spieldauer stark gekürzt worden. Laut den Quellen von Kotaku ist das Spiel „light on gameplay“, vieles laufe über eine einzige Taste. Ursprünglich soll Marvel 1943 als Netflix-Spiel begonnen haben. Angekündigt wurde es 2024, seitdem wurde es mehrfach verschoben. Einen Termin gibt es nicht. Alle Angaben stammen aus anonymen Quellen, Skydance hat sie nicht bestätigt.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/marvel-1943-rise-of-hydra-is-reportedly-close-to-done-though-at-the-cost-of-cutting-back-on-content-and-length"}, "weitere_links": [], "zuverlaessigkeit": {"stufe": "mittel", "begruendung": "Bericht von Kotaku mit anonymen Quellen, Teile von Jason Schreier (Bloomberg) gestützt; über IGN (Bewertung hoch) aufgegriffen; von Skydance nicht bestätigt."}, "ursprungsquelle": "Kotaku (via IGN)", "tags": ["Marvel 1943", "Skydance", "Amy Hennig"], "bild": {"datei": "assets/img/news/2026-11-12-marvel-1943-fast-fertig.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.692Z"}, "id": "2026-11-12-nvidia-board-huang-abloesung", "datum": "2026-11-12T00:14:00+01:00", "label": "News", "bereich": "hardware", "themen": ["GPU", "Nvidia"], "kategorie": "Unternehmen", "titel": "Berichte: Nvidia-Verwaltungsrat berät über Absetzung von CEO Jensen Huang und sucht bereits Nachfolger", "schlagzeile": "Nvidia vor dem Chefwechsel? Verwaltungsrat berät über Huangs Absetzung", "kurz": "Laut Wall Street Journal bereitet Nvidias Verwaltungsrat die Absetzung von Firmengründer und CEO Jensen Huang vor. Auslöser ist ein Bericht der New York Times über eine zweite außereheliche Beziehung, diesmal zu einer ihm direkt unterstellten Managerin. Bloomberg zufolge sucht eine externe Firma bereits nach Nachfolgern. Bis heute mittag hat Nvidia weiterhin keine Entscheidung bekanntgegeben; die Meldungen beruhen auf anonymen Quellen.", "zusammenfassung": "Die Krise um Nvidia-Chef Jensen Huang spitzt sich zu. Nach Berichten des Wall Street Journal wollte der Verwaltungsrat am Mittwochabend (US-Zeit) über Huangs Zukunft beraten, eine Absetzung stehe im Raum. Auslöser ist ein neuer Bericht der New York Times: Huang soll neben der bereits eingeräumten Affäre auch eine Beziehung zu einer Vizepräsidentin gehabt haben, die direkt an ihn berichtet. Die Zeitung beruft sich auf fünf frühere Beschäftigte, ein angebliches Video eines Vorfalls im März hat sie nach eigenen Angaben nicht selbst gesehen. Weder Nvidia noch die Betroffenen haben den Bericht bestätigt. Laut Bloomberg arbeitet der Verwaltungsrat bereits mit einer externen Firma an der Suche nach einem Nachfolger, auch ein Interims-CEO werde erwogen. Hintergrund ist die seit Sonntag laufende Untersuchung zu Huangs Affäre mit einer Managerin des Nvidia-Kunden Megaspeed, die von US-Behörden als mutmaßliche chinesische Agentin eingestuft worden sein soll; China weist das zurück. Huang führt Nvidia seit der Gründung 1993, einen benannten Nachfolger gibt es laut PCGH nicht. Laut PCGH reicht für eine Abberufung die einfache Mehrheit der Direktoren. Die Aktie verlor nach den Berichten nachbörslich rund acht Prozent und fiel auf ein 52-Wochen-Tief. Am kommenden Dienstag legt Nvidia Quartalszahlen vor, am Mittwoch darauf ist ein vertrauliches Briefing im US-Kongress geplant. Konkrete Auswirkungen auf GeForce-Karten, Preise oder Treiber sind bisher nicht bekannt. Wichtig: Alles beruht auf Medienberichten mit anonymen Quellen von Wall Street Journal, New York Times und Bloomberg; bis heute mittag hat Nvidia keine Entscheidung bekanntgegeben, die Lage kann sich ändern.", "quelle": {"name": "ComputerBase", "url": "https://www.computerbase.de/news/wirtschaft/nvidia-krise-verwaltungsrat-beraet-ueber-rauswurf-von-jensen-huang.100297/"}, "weitere_links": [{"name": "PC Games Hardware", "url": "https://www.pcgameshardware.de/Wirtschaft-Thema-238882/News/Nvidia-Jensen-Huang-Affaere-Abloesung-CEO-Nachfolger-1559660/"}, {"name": "heise online", "url": "https://www.heise.de/news/Jensen-Huang-nach-weiterer-Affaere-mit-Mitarbeiterin-wohl-vor-dem-Aus-bei-Nvidia-11521625.html"}, {"name": "Golem.de", "url": "https://www.golem.de/news/zweite-affaere-nvidia-erwaegt-offenbar-jensen-huangs-absetzung-2611-215113.html"}, {"name": "IGN", "url": "https://www.ign.com/articles/nvidia-board-is-preparing-to-potentially-oust-ceo-jensen-huang"}, {"name": "PC Gamer", "url": "https://www.pcgamer.com/software/ai/nvidia-ceo-jensen-huang-allegedly-had-a-second-affair-with-another-nvidia-exec/"}], "tags": ["Nvidia", "Jensen Huang", "Unternehmen", "Aktie"], "bild": {"datei": "assets/img/news/2026-11-12-nvidia-board-huang-abloesung.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.780Z"}, "id": "2026-11-12-golden-joystick-2026", "datum": "2026-11-11T22:31:00+01:00", "label": "News", "bereich": "games", "themen": ["Awards"], "kategorie": "Spiele", "titel": "Golden Joystick Awards 2026: Resident Evil Requiem ist Spiel des Jahres, Crimson Desert gewinnt am PC", "schlagzeile": "Golden Joysticks: Resident Evil Requiem holt den Spiel-des-Jahres-Titel", "kurz": "Bei den 44. Golden Joystick Awards hat Resident Evil Requiem den Hauptpreis als Ultimate Game of the Year gewonnen. Bestes PC-Spiel wurde Crimson Desert. Der Multiplayer-Hit Meccha Chameleon räumte vier Preise ab, The Witcher 4 ist das meisterwartete Spiel.", "zusammenfassung": "Die Golden Joystick Awards gelten als ältestes Publikumsvoting der Spielebranche und fanden 2026 zum 44. Mal statt. Den Hauptpreis als Ultimate Game of the Year holte Resident Evil Requiem von Capcom. Das Horrorspiel gewann außerdem als bestes Konsolenspiel, für den besten Trailer und für die beste Hauptdarstellerin, Angela Sant'Albano als Grace Ashcroft. Capcom wurde laut TheGameVerse zudem Studio des Jahres. Bestes PC-Spiel wurde Crimson Desert, obwohl es auch auf Konsolen erscheint. Das Versteckspiel Meccha Chameleon gewann vier Preise: bestes Multiplayer-Spiel, bestes selbst veröffentlichtes Indie-Spiel, Streamers' Choice und Developers' Choice. The Witcher 3: Wild Hunt Remastered wurde bestes Remaster, The Witcher 4 meisterwartetes Spiel. Als beste Gaming-Hardware wählten die Fans den Steam Controller. Weitere Preise gingen an Onimusha: Way of the Sword (Audio), Control: Resonant (Grafikdesign), Doom: The Dark Ages – Revelations (Erweiterung) und Subnautica 2 (Early Access). Veranstalter der Awards ist der Verlag von PC Gamer.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/games/crimson-desert-wins-pc-game-of-the-year-at-the-2026-golden-joystick-awards/"}, "weitere_links": [{"name": "TheGameVerse auf X (Gewinnerliste)", "url": "https://x.com/TheGameVerse/status/2120750515277709426"}], "tags": ["Golden Joystick Awards", "Resident Evil Requiem", "Crimson Desert", "Awards"], "bild": {"datei": "assets/img/news/2026-11-12-golden-joystick-2026.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.876Z"}, "id": "2026-11-12-gta6-clip-realistisch", "datum": "2026-11-11T21:49:00+01:00", "label": "News", "bereich": "games", "themen": ["GTA 6"], "kategorie": "Spiele", "titel": "GTA 6: Rockstar teilt Ingame-Clip, den viele für ein echtes Handyvideo aus Miami halten", "schlagzeile": "Echt oder GTA 6? Neuer Clip von Rockstar narrt das Netz", "kurz": "Ein rund 15 Sekunden langer GTA-6-Clip aus Ego-Perspektive sorgt für Diskussionen, weil viele ihn für ein echtes Video halten. Er bildet ein reales Handyvideo der GTA-Autos aus der Marketing-Aktion in Miami nach. Rockstar teilte den Clip in seiner Instagram-Story, was laut IGN auf echtes Spielmaterial hindeutet.", "zusammenfassung": "Eine Woche vor dem Start von GTA 6 sorgt ein kurzer Clip für Staunen. Ursprünglich tauchte er beim Instagram-Konto „Only in Dade“ auf, das skurrile Szenen aus Miami-Dade sammelt. Zu sehen ist eine Fahrt über den Ocean Drive, vorbei an einer Reihe auffälliger Autos, dazu eine zweite Perspektive vom Gehweg. Der Clip bildet laut IGN, Polygon und Insider Gaming ein echtes Video nach, das im Oktober bei Rockstars Marketing-Aktion mit nachgebauten GTA-Autos in Miami entstand. Viele Zuschauer hielten das Material zunächst für reale Aufnahmen oder für KI. Rockstar teilte den Clip in seiner Instagram-Story und markierte ihn mit „Gefällt mir“, was IGN als starkes Zeichen für echtes Spielmaterial wertet. Ausdrücklich bestätigt hat Rockstar es nach Polygon-Angaben aber nicht. Der Look könnte laut Spekulationen von Fans zeigen, wie Aufnahmen mit der Handykamera im Spiel aussehen. Insider Gaming betont, dass der Clip nichts über einen möglichen Ego-Modus aussagt. GTA 6 erscheint am 19. November für PS5 und Xbox Series X/S und läuft laut Rockstar auf Konsolen mit 30 fps. Das Preloading läuft bereits.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/new-gta-6-surprise-gameplay-seemingly-released-in-yet-another-viral-marketing-stunt"}, "weitere_links": [{"name": "Insider Gaming", "url": "https://insider-gaming.com/rockstar-games-unreal-gta-6-clip-social-media-first-person/"}, {"name": "Polygon", "url": "https://www.polygon.com/gta-6-new-gameplay-onlyindade-ai-real-fake-rockstar-instagram/"}, {"name": "GamePro (News-Übersicht)", "url": "https://www.gamepro.de/news/"}], "tags": ["GTA 6", "Rockstar", "Grafik", "Marketing"], "bild": {"datei": "assets/img/news/2026-11-12-gta6-clip-realistisch.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:03.986Z"}, "id": "2026-11-12-black-forest-games-unabhaengig", "datum": "2026-11-11T21:37:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spielebranche", "titel": "Black Forest Games kauft sich von Embracer frei und gründet die Studiogruppe Third Signal", "schlagzeile": "Deutsches Destroy-All-Humans-Studio kauft sich von Embracer frei", "kurz": "Das deutsche Studio Black Forest Games hat sich per Management-Buy-out von THQ Nordic und Embracer gelöst. Es gründet zugleich Third Signal, eine Gruppe unabhängiger Studios. Mit THQ Nordic arbeitet das Team weiter zusammen.", "zusammenfassung": "Black Forest Games ist nach neun Jahren unter dem Dach von THQ Nordic und Embracer wieder eigenständig. Das gelang laut Eurogamer und PC Gamer über einen Management-Buy-out. Das Studio entwickelte unter anderem Giana Sisters: Twisted Dreams und die Remakes der ersten beiden Destroy-All-Humans-Spiele. Gegründet wurde es von früheren Mitarbeitern von Spellbound Entertainment, bekannt für Desperados und Arcania: Gothic 4. Zusammen mit der Unabhängigkeit startet Third Signal, eine Gruppe unabhängiger Studios, die künftig auch anderen Indie-Teams helfen soll. Third-Signal-Chef Andreas Tobler sagt sinngemäß, viele der besten Spiele des letzten Jahrzehnts stammten von Teams mit 50 statt 500 Leuten. Laut Pressemitteilung arbeiten THQ Nordic und Black Forest Games weiter bei der Entwicklung zusammen. Die Rechte an Destroy All Humans hat das Studio offenbar nicht übernommen. Geschäftsführer Adrian Goersch kündigt ein neues Projekt an, Details nennt er nicht. Das Studio war 2024 von Embracers Entlassungen betroffen und verlor damals rund 50 Stellen.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/destroy-all-humans-independent-thq-embracer"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/giana-sisters-developer-black-forest-games-buys-itself-out-of-embracer-some-of-the-best-games-of-the-last-decade-came-from-teams-of-fifty-not-five-hundred/"}], "tags": ["Black Forest Games", "Embracer", "THQ Nordic", "Third Signal"], "bild": {"datei": "assets/img/news/2026-11-12-black-forest-games-unabhaengig.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.101Z"}, "id": "2026-11-12-nintendo-dmca-github", "datum": "2026-11-11T21:14:00+01:00", "label": "News", "bereich": "games", "themen": ["Nintendo"], "kategorie": "Konsolen", "titel": "Nintendo lässt per DMCA 144 GitHub-Repositorys mit Switch-Modchip-Firmware und zwei Emulatoren entfernen", "schlagzeile": "Nintendo räumt GitHub auf: Switch-Emulatoren und Modchip-Firmware weg", "kurz": "Nintendo hat vier DMCA-Beschwerden an GitHub geschickt, die sich gegen die Switch-Emulatoren Yuzu und Citron Neo sowie gegen Modchip-Firmware richten. GitHub hat 144 Repositorys mit der Firmware entfernt. Laut TorrentFreak ist sie an anderer Stelle auf der Plattform aber weiterhin zu finden.", "zusammenfassung": "Nintendo geht erneut gegen Werkzeuge zum Umgehen des Switch-Kopierschutzes vor. Laut IGN gingen vier DMCA-Beschwerden bei GitHub ein, die das Unternehmen öffentlich dokumentiert hat. Im Visier stehen die Emulatoren Yuzu und Citron Neo, vor allem aber Firmware für Modchips wie Picofly. Solche Chips werden auf die Switch-Hauptplatine gelötet und umgehen den Kopierschutz. Von der Firmware hat GitHub 144 Repositorys entfernt und durch einen DMCA-Hinweis ersetzt. Nintendo argumentiert in der Beschwerde vom 6. November, die technischen Schutzmaßnahmen sollten das Spielen von Raubkopien und auf fremden Geräten verhindern. Laut TorrentFreak ist die Firmware an anderen Stellen auf GitHub aber weiterhin verfügbar. Schon 2024 hatte Nintendo rund 8.500 Kopien von Yuzu entfernen lassen. IGN bringt die neue Welle mit Berichten in Verbindung, wonach Emulatoren kurz zuvor das neue Ocarina-of-Time-Remake am PC lauffähig gemacht haben; ein direkter Zusammenhang ist nicht belegt. Ob Nintendo weitere Schritte plant, ist offen.", "quelle": {"name": "IGN", "url": "https://www.ign.com/articles/nintendo-takes-down-switch-emulators-and-mod-chip-firmware-in-massive-github-dmca-sweep"}, "weitere_links": [], "tags": ["Nintendo", "Switch", "Emulation", "DMCA", "GitHub"], "bild": {"datei": "assets/img/news/2026-11-12-nintendo-dmca-github.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.209Z"}, "id": "2026-11-12-id-veteranen-hidden-horses", "datum": "2026-11-11T21:09:00+01:00", "label": "News", "bereich": "games", "themen": ["Branche"], "kategorie": "Spielebranche", "titel": "Rund 20 frühere id-Software-Entwickler gründen das Studio Hidden Horses und planen einen Arena-Shooter", "schlagzeile": "Nach Xbox-Entlassungen: Ex-id-Entwickler gründen eigenes Shooter-Studio", "kurz": "Rund 20 ehemalige Entwickler von id Software haben das Studio Hidden Horses gegründet, das den Beschäftigten selbst gehört. Ihr erstes Projekt ist der Einzelspieler-Arena-Shooter Danger Pay. Finanziert werden soll er unter anderem über Kickstarter.", "zusammenfassung": "Bei den Xbox-Entlassungen im Juli 2026 verlor id Software laut Berichten 136 Entwickler. Rund 20 von ihnen haben jetzt Hidden Horses gegründet, ein Studio im Besitz der Beschäftigten. Laut PC Gamer bringen die Gründer zusammen über 250 Jahre Erfahrung mit. Das Studio soll demokratisch geführt werden und langfristige Stabilität über schnelles Wachstum und fragwürdige Monetarisierung stellen. Mitgründer Dustin Land sagt, man wolle das Team zusammenhalten und klassische Shooter machen. Das erste Spiel heißt Danger Pay, ein Einzelspieler-Arena-Shooter rund um eine brutale TV-Spielshow. Als Vorbilder nennt das Studio den Film The Running Man von 1987 und das Arcade-Spiel Smash TV. Für die Finanzierung ist eine Kickstarter-Kampagne geplant. Plattformen, Termin und Kickstarter-Start sind noch nicht bekannt.", "quelle": {"name": "PC Gamer", "url": "https://www.pcgamer.com/gaming-industry/former-id-software-developers-form-their-own-employee-owned-shooter-studio-in-the-wake-of-microsofts-mass-layoffs/"}, "weitere_links": [], "tags": ["id Software", "Hidden Horses", "Danger Pay", "Shooter"], "bild": {"datei": "assets/img/news/2026-11-12-id-veteranen-hidden-horses.webp", "ki_generiert": true}}, {"ki_unterstuetzt": true, "approved": true, "freigabe": {"status": "freigegeben", "von": "M-TEC", "am": "2026-11-12T10:57:04.315Z"}, "id": "2026-11-12-tes6-sentinel-pause", "datum": "2026-11-11T20:36:00+01:00", "label": "News", "bereich": "games", "themen": ["Elder Scrolls"], "kategorie": "Spiele", "titel": "Bethesda: Zum Skyrim-Jubiläum keine Neuigkeiten zu The Elder Scrolls 6: Sentinel – und auch „für einige Zeit“ nicht", "schlagzeile": "15 Jahre Skyrim, aber kein Elder Scrolls 6: Bethesda bremst die Fans", "kurz": "Zum 15. Geburtstag von Skyrim hatten Fans auf Neuigkeiten zu The Elder Scrolls 6: Sentinel gehofft. Bethesda Game Studios stellte auf Reddit klar, dass es keine große Ankündigung gibt. Neues zu Sentinel werde es „für einige Zeit“ nicht geben.", "zusammenfassung": "Am 11. November wurde The Elder Scrolls V: Skyrim 15 Jahre alt. Im Subreddit zu The Elder Scrolls 6 spekulierten Fans auf eine Überraschung zum Jubiläum, angeheizt durch einen Podcast-Teaser zu einer „großen Ankündigung“. Der Podcaster stellte später klar, dass sie nichts mit Bethesda zu tun hat. Dann meldete sich auch das offizielle Konto von Bethesda Game Studios auf Reddit. Man werde keine große Ankündigung machen und „für einige Zeit“ nichts Neues zu Sentinel zeigen, schrieb das Studio. Den Titel Sentinel hatte Bethesda erst Anfang November offiziell gemacht. Angekündigt wurde The Elder Scrolls 6 bereits 2018. Zum Jubiläum gibt es Skyrim auf allen Plattformen günstiger. The Elder Scrolls Online macht das Greymoor-Kapitel kostenlos zum Teil des Grundspiels, eine Skyrim-Aktion läuft dort bis 2. Dezember. Wann es neue Infos zu Sentinel gibt, ist offen.", "quelle": {"name": "Eurogamer", "url": "https://www.eurogamer.net/dont-expect-elder-scrolls-6-sentinel-for-some-time-bethesda"}, "weitere_links": [{"name": "PC Gamer", "url": "https://www.pcgamer.com/games/the-elder-scrolls/bethesda-shoots-down-elder-scrolls-6-sentinel-announcement-rumor-on-skyrims-15th-anniversary/"}], "tags": ["The Elder Scrolls 6", "Sentinel", "Skyrim", "Bethesda"], "bild": {"datei": "assets/img/news/2026-11-12-tes6-sentinel-pause.webp", "ki_generiert": true}}]};
